/**
 * Cloudflare Worker — NSPB Excel add-in backend.
 *
 *   Excel task pane (same origin)
 *        ├── GET  /*                  → static assets (taskpane.html/js/css, icons)
 *        ├── GET  /api/health         → liveness check
 *        ├── POST /api/test-connection → NSPB credentials sanity check
 *        └── POST /api/chat           → Claude tool loop (calls Anthropic + NSPB)
 *
 * Stateless by design: the user's Anthropic key and NSPB credentials both
 * travel with every /api/chat request (stored in OfficeRuntime.storage on
 * the add-in side). Nothing persists server-side, so the same deployment
 * works for any user.
 */

// Gemini endpoints — same pattern MCP3 uses (see Gemini.gs:51).
const GEMINI_API_BASE = "https://generativelanguage.googleapis.com/v1beta/models/";
const GEMINI_MODEL_FAST = "gemini-2.5-flash";       // 500 RPD free, fast
const GEMINI_MODEL_REASONING = "gemini-2.5-pro";    // 100 RPD free, smarter for variance/analysis
const GEMINI_MAX_TOKENS = 4096;

// Claude endpoints
const CLAUDE_API_URL = "https://api.anthropic.com/v1/messages";
const CLAUDE_MODEL_FAST = "claude-haiku-4-5";
const CLAUDE_MODEL_REASONING = "claude-sonnet-4-5";
const CLAUDE_API_VERSION = "2023-06-01";

// Detect provider from key prefix. Returns "gemini" | "claude" | "unknown".
function detectProvider(key) {
  const k = String(key || "").trim();
  if (!k) return "unknown";
  if (/^AIza[A-Za-z0-9_-]{20,}$/.test(k)) return "gemini";
  if (/^sk-ant-/.test(k)) return "claude";
  return "unknown";
}

// Plain-text generation that works with either provider. Used by /api/ping
// and /api/nl2sql (no tool-calling). For tool-calling chat (runChatTurn),
// only Gemini is supported today — Claude tool-use needs a separate adapter.
async function callTextLLM(key, prompt, opts) {
  const o = opts || {};
  const provider = detectProvider(key);
  if (provider === "gemini") {
    const model = o.reasoning ? GEMINI_MODEL_REASONING : GEMINI_MODEL_FAST;
    const url = GEMINI_API_BASE + model + ":generateContent?key=" + encodeURIComponent(key);
    const body = {
      contents: [{ role: "user", parts: [{ text: prompt }] }],
      generationConfig: { maxOutputTokens: o.maxTokens || 1024, temperature: o.temperature || 0.2 }
    };
    if (o.system) body.systemInstruction = { parts: [{ text: o.system }] };
    const r = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body)
    });
    const j = await r.json();
    if (!r.ok) throw new Error("Gemini " + r.status + ": " + (j.error?.message || JSON.stringify(j).slice(0,300)));
    const text = j.candidates?.[0]?.content?.parts?.map(p => p.text || "").join("") || "";
    return { text, provider: "gemini", model };
  }
  if (provider === "claude") {
    const model = o.reasoning ? CLAUDE_MODEL_REASONING : CLAUDE_MODEL_FAST;
    const body = {
      model,
      max_tokens: o.maxTokens || 1024,
      temperature: o.temperature || 0.2,
      messages: [{ role: "user", content: prompt }]
    };
    if (o.system) body.system = o.system;
    const r = await fetch(CLAUDE_API_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-api-key": key,
        "anthropic-version": CLAUDE_API_VERSION
      },
      body: JSON.stringify(body)
    });
    const j = await r.json();
    if (!r.ok) throw new Error("Claude " + r.status + ": " + (j.error?.message || JSON.stringify(j).slice(0,300)));
    const text = (j.content || []).map(b => b.text || "").join("");
    return { text, provider: "claude", model };
  }
  throw new Error("Unknown AI key — must start with AIza (Gemini) or sk-ant- (Claude)");
}

