// Parse `<res_EnumBusinessRules>` XML into the merged attachedRules array.
// Each rule is `<rule attr="..." attr="...">RuleName</rule>`.
function parseSvRules(xml, into) {
  if (!xml) return;
  const re = /<rule\s+([^>]*?)>([\s\S]*?)<\/rule>/g;
  let m;
  while ((m = re.exec(xml))) {
    const attrs = m[1];
    const name = svUnescape(m[2]).trim();
    if (!name) continue;
    const get = (k) => (attrs.match(new RegExp(k + '="([^"]*)"')) || [])[1] || "";
    into.push({
      name,
      description:    svUnescape(get("desc")),
      hasRTP:         get("rtp") === "1",
      runOnSave:      get("runOnSave") === "1",
      runBeforeSave:  get("runBeforeSave") === "1",
      runOnLoad:      get("runOnLoad") === "1"
    });
  }
}

// Generate contextual analysis + action chips for a form based on its module.
function buildFormChips(form, attachedRules, tkb, rulesSource) {
  const chips = [];
  const name = (form.name || "").toLowerCase();

  // Look up module from LCM KB
  let module = form.module || null;
  if (!module && tkb && Array.isArray(tkb.forms)) {
    const norm = s => (s||"").toLowerCase().replace(/^nfs_/i,"").replace(/\.+$/,"").trim();
    const lf = tkb.forms.find(f => norm(f.name) === norm(form.name));
    if (lf) module = lf.module || null;
  }
  const mod = (module || "").toLowerCase();

  // ── SmartView navigation chips — minimal, all 📐 ─────────────────────
  // Four ops, each on a DIFFERENT dimension to teach the user the spectrum
  // of moves available. **Each chip discloses the dimension in parens** so
  // the user learns which dim the member belongs to (e.g. "Revenue (Account)").
  // This is how a finance user builds intuition about the cube — without it
  // chips look like magic; with it they teach the multi-dim structure.
  let zoomInMember = "Revenue", zoomInDim = "Account";
  let bottomDim = "Department";
  let keepMember = "Marketing", keepDim = "Department";
  if (mod.includes("opex") || name.includes("opex") || name.includes("expense")) {
    zoomInMember = "Salaries & Wages"; zoomInDim = "Account";
    bottomDim   = "Department";
    keepMember  = "Sales";              keepDim   = "Department";
  } else if (mod.includes("revenue") || name.includes("revenue")) {
    zoomInMember = "Revenue";           zoomInDim = "Account";
    bottomDim   = "Customer";
    keepMember  = "Direct";             keepDim   = "Channel";
  } else if (mod.includes("workforce") || name.includes("workforce") || name.includes("employee")) {
    zoomInMember = "Salaries & Wages"; zoomInDim = "Account";
    bottomDim   = "Department";
    keepMember  = "Sales";              keepDim   = "Department";
  } else if (mod.includes("balance") || name.includes("balance")) {
    zoomInMember = "Total Assets";     zoomInDim = "Account";
    bottomDim   = "Subsidiary";
    keepMember  = "Cash";               keepDim   = "Account";
  } else if (mod.includes("cash")) {
    zoomInMember = "Cash from Ops";    zoomInDim = "Account";
    bottomDim   = "Subsidiary";
    keepMember  = "Operations";         keepDim   = "Activity";
  } else if (mod.includes("income") || name.includes("income") || name.includes("p&l")) {
    zoomInMember = "Revenue";           zoomInDim = "Account";
    bottomDim   = "Subsidiary";
    keepMember  = "Direct";             keepDim   = "Channel";
  }
  // Chip format: `LABEL → COMMAND`. Label includes "(<Dim>)" so the user
  // sees which dimension the member belongs to. Command stays clean.
  chips.push(`📐 Zoom in on ${zoomInMember} (${zoomInDim} dim) → zoom in on ${zoomInMember}`);
  chips.push(`📐 Zoom to bottom of ${bottomDim} (${bottomDim} dim) → zoom to bottom of ${bottomDim}`);
  chips.push(`📐 Zoom out (collapse one level) → zoom out`);
  chips.push(`📐 Keep only ${keepMember} (${keepDim} dim) → keep only ${keepMember}`);

  // ── Analysis chips disabled for now ────────────────────────────────────
  // After-form-open is for NAVIGATION (drill / pivot / filter / run rule),
  // not analytics. The previous "Actual vs Forecast / Top variance drivers /
  // month-over-month trend" chips would silently rebuild the grid from
  // scratch via build_adhoc — confusing UX. They'll come back as TWO
  // distinct families with their own icons:
  //   🧠  Analyze the CURRENT view (paint cells, write a narrative below)
  //   🛠  Rebuild the grid as a different query (e.g. "Actual vs Forecast YTD")
  // Both are not yet implemented end-to-end. When ready, gate them behind
  // a feature flag here.

  // Only show "Run X" chips for runnable Business Rules. Parser tags each
  // attached rule with `kind`: "runnable" | "calcScript" | "notRegistered".
  // - calcScript (CURRENCY/DEFAULT) auto-fire in SmartView, can't be invoked via REST.
  // - notRegistered means the rule isn't in kb.rules[] (no Job Definition).
  // Both are skipped here so we never offer a button that would 400.
  // Backward compat: older KB without `kind` falls back to name lookup.
  const runnableNames = new Set(
    (tkb && Array.isArray(tkb.rules) ? tkb.rules : [])
      .map(r => (r.name || "").toLowerCase())
      .filter(Boolean)
  );
  const isRunnable = (r) => {
    if (!r || !r.name) return false;
    if (r.kind) return r.kind === "runnable";
    // Legacy KB (schema < 5) — fall back to calcType + registered-name check.
    if (r.calcType === "3") return false;
    if (runnableNames.size > 0) return runnableNames.has(r.name.toLowerCase());
    return true;
  };
  const seen = new Set();
  const sortedRules = [
    ...attachedRules.filter(r => r.runOnSave && isRunnable(r)),
    ...attachedRules.filter(r => !r.runOnSave && isRunnable(r))
  ];
  // Cap chip count: form has direct attachments → up to 6 rules; cube-wide
  // fallback (no real attachment) → up to 3 only, since they're guesses.
  const isCubeWideChips = /cube-wide/i.test(rulesSource || "");
  const RULE_CHIP_MAX = isCubeWideChips ? 3 : 6;
  let added = 0;
  for (const r of sortedRules) {
    if (!r.name || seen.has(r.name)) continue;
    if (added >= RULE_CHIP_MAX) break;
    seen.add(r.name);
    const tag = r.runOnSave ? " (on-save)" : "";
    chips.push(`▶️ Run rule ${r.name}${tag} → run rule ${r.name}`);
    // Pair every Run chip with an Explain chip — same rule, but the
    // user can ask the AI to summarize it (in plain English, no Groovy
    // dump). This is the anti-churn moment: user opens a form, sees
    // rules they don't know, can drill into each one's purpose in
    // one click without leaving the chat.
    chips.push(`📐 Explain rule ${r.name} → explain rule ${r.name}`);
    added++;
  }

  // Add a Submit chip for INPUT forms — lets the user push edited yellow
  // cells back to NSPB without leaving the chat. Only for data-entry forms.
  const isInputForm = form && (form.isInput === true || form.category === "input" || form.kind === "input");
  if (isInputForm) {
    chips.push(`💾 Submit data → submit data from this sheet`);
  }

  return chips;
}

// Build an adhoc-style gridDescriptor from a parsed form slice so modify_grid
// can navigate form-origin grids (add/remove members, pivot, zoom) exactly
// like chat-built ad-hocs. Axis assignment comes from the SmartView response
// (<dim row=/col=> attrs, captured by parseSmartViewSlice); member lists come
// from the slice header rows / row-label columns. Tenant-agnostic by
// construction — works the same on standard NSPB cubes (Plan/Workforc…) and
// custom apps (OEP_FS/WFPlan…) because everything is read from the live
// response + detected appConfig. Best-effort: returns null rather than
// throwing — opening the form must NEVER fail because of synthesis
// (invariant: runOpenForm resilient).
function synthesizeFormDescriptor(parsed, respXml, opts) {
  const bail = (reason) => {
    console.log("[OPEN_FORM_SYNTH] no descriptor:", reason, "form:", (opts && opts.sheetName) || "?");
    return null;
  };
  try {
    const axes = (parsed && parsed.axes) || {};
    const rowDims = axes.rowDims || [], colDims = axes.colDims || [];
    if (!rowDims.length || !colDims.length) return bail("no axis attrs in response");
    const g = parsed.grid || [];
    const M = colDims.length, N = rowDims.length;
    if (g.length <= M) return bail("grid smaller than header block");
    const uniq = (arr) => {
      const seen = new Set(), out = [];
      for (const v of arr) {
        const s = String(v == null ? "" : v).trim();
        if (!s || seen.has(s)) continue;
        seen.add(s); out.push(s);
      }
      return out;
    };
    // Header row k (top M rows) holds col-dim k's members across the data
    // area; label column k (leading N cols) holds row-dim k's members.
    const colAxis = colDims.map((d, k) => ({ dimension: d, members: uniq((g[k] || []).slice(N)) }));
    const rowAxis = rowDims.map((d, k) => ({ dimension: d, members: uniq(g.slice(M).map(r => (r || [])[k])) }));
    if (colAxis.some(c => !c.members.length) || rowAxis.some(r => !r.members.length)) return bail("empty member list on an axis");
    // UNIFORMITY CHECK — the adhoc rebuild is the CARTESIAN product of the
    // per-dim lists. Real Planning forms are often sparse / segmented (each
    // Entity block selects different Accounts) or carry formula rows; for
    // those the product ≠ what the form showed and a rebuild would silently
    // replace the form with plausible-but-wrong intersections. Only uniform
    // cartesian layouts get a descriptor; anything else stays read-only.
    const dataRows = g.slice(M).filter(r => (r || []).some(c => c !== "" && c != null)).length;
    const dataCols = (g[0] || []).length - N;
    const rowsProduct = rowAxis.reduce((a, r) => a * r.members.length, 1);
    const colsProduct = colAxis.reduce((a, c) => a * c.members.length, 1);
    if (rowsProduct !== dataRows) return bail(`non-cartesian rows (${rowsProduct} product vs ${dataRows} rendered)`);
    if (colsProduct !== dataCols) return bail(`non-cartesian cols (${colsProduct} product vs ${dataCols} rendered)`);
    if (rowsProduct * colsProduct > 250000) return bail("cartesian too large");
    // Cube — source priority:
    //  1. the form's own inventory cube when it's a real name (LCM KBs may
    //     store a numeric plan-type id — ignore those),
    //  2. the response's <cube> tag (presence varies by tenant version),
    //  3. the detected appConfig cube whose dim list covers every axis + POV
    //     dim (tightest fit wins when several qualify).
    let cube = null;
    const formCube = opts && opts.formCube;
    if (formCube && isNaN(Number(formCube))) cube = String(formCube);
    if (!cube) {
      const tag = (respXml.match(/<cube[^>]*>([^<]+)<\/cube>/) || [])[1];
      if (tag) cube = svUnescape(tag);
    }
    const allDims = rowDims.concat(colDims, (parsed.pov || []).map(p => p.dim));
    const cfg = opts && opts.appConfig;
    if (!cube && cfg && cfg.cubeDims) {
      const candidates = Object.keys(cfg.cubeDims).filter(c =>
        allDims.every(d => (cfg.cubeDims[c] || []).includes(d)));
      candidates.sort((a, b) => (cfg.cubeDims[a] || []).length - (cfg.cubeDims[b] || []).length);
      cube = candidates[0] || null;
      if (candidates.length > 1) console.log("[OPEN_FORM_SYNTH] cube ambiguous:", candidates.join(","), "→ picked", cube);
    }
    if (!cube) return bail("cube undeterminable (no form cube, no <cube> tag, no appConfig match)");
    const pov = {};
    for (const p of (parsed.pov || [])) if (p.dim && p.member) pov[p.dim] = p.member;
    console.log("[OPEN_FORM_SYNTH] OK:", opts.sheetName, "cube:", cube,
                "rows:", rowAxis.map(r => `${r.dimension}(${r.members.length})`).join("×"),
                "cols:", colAxis.map(c => `${c.dimension}(${c.members.length})`).join("×"));
    return {
      cube,
      sheetName: opts.sheetName,
      pov,
      rowAxis,
      colAxis,
      origin: "form",
      asOf: Date.now()
    };
  } catch (e) { return bail("exception: " + (e.message || e)); }
}

// Open a form via SmartView req_GetFormSlice + parse the slice into a 2D
// grid. Optionally append the form's attached business rules. Looks up the
// form in the user's discovered inventory (case-insensitive name match); the
// caller passes `opts.forms` (array of {name, path, cube, formId, ...}) so we
// don't hit NSPB for inventory data on every form open.
async function runOpenForm(settings, args, opts) {
  const formName = (args && args.form_name || "").trim();
  if (!formName) throw new Error("open_form: form_name required");
  const wantRules = args.attached_rules !== false;
  const liveForms = Array.isArray(opts.forms) ? opts.forms : [];
  const tkbForLookup = opts.tenantKb || ((typeof EMBED_TENANT_KB !== "undefined" && EMBED_TENANT_KB) ? EMBED_TENANT_KB : null);
  const kbForms = (tkbForLookup && Array.isArray(tkbForLookup.forms)) ? tkbForLookup.forms : [];
  // Merge live + KB forms by name so forms only present in the LCM export are findable too.
  const seenNames = new Set();
  const inventory = [];
  for (const f of liveForms) {
    const k = (f.name || "").trim().toLowerCase();
    if (!k || seenNames.has(k)) continue;
    seenNames.add(k); inventory.push(f);
  }
  for (const f of kbForms) {
    const k = (f.name || "").trim().toLowerCase();
    if (!k || seenNames.has(k)) continue;
    seenNames.add(k);
    inventory.push({ name: f.name, path: f.path || "", cube: f.cube || "", formId: f.formId || "", category: f.isInput ? "input" : (f.isInput === false ? "review" : "unknown"), description: f.description || "" });
  }

  if (!inventory.length) {
    throw new Error("Forms inventory is empty. Open Settings → click 'Forms' to discover forms first.");
  }

  // 1. Find the form. Case-insensitive exact match preferred; partial as
  //    fallback. If multiple matches, prefer the shortest path.
  // Normalize: strip NFS_ prefix and trailing dots/spaces (NSPB often adds
  // a trailing period to form names, and NFS_ is a tenant-internal prefix
  // invisible to users). "Income Statement" → matches "Income Statement."
  // and "NFS_Income Statement" without requiring the user to know the exact name.
  const normName = s => (s || "").toLowerCase().replace(/^nfs[_\s]*/i, "").replace(/[\.\s]+$/, "").trim();
  const lc = formName.toLowerCase();
  const lcNorm = normName(formName);
  // Strict exact match first (case-insensitive, no normalization).
  let exact = inventory.filter(f => (f.name || "").toLowerCase() === lc);
  // Normalized exact match: strip NFS_ prefix + trailing punctuation on both sides.
  if (!exact.length) {
    exact = inventory.filter(f => normName(f.name) === lcNorm);
    // If normalized match found multiple (e.g. "Income Statement." AND
    // "NFS_Income Statement" both normalize to "income statement"), prefer
    // the non-NFS one with the shorter path.
    if (exact.length > 1) {
      exact.sort((a, b) => {
        const aNfs = /^nfs[_\s]/i.test(a.name || "") ? 1 : 0;
        const bNfs = /^nfs[_\s]/i.test(b.name || "") ? 1 : 0;
        return aNfs - bNfs || (a.path || "").length - (b.path || "").length;
      });
      exact = [exact[0]];
    }
  }
  if (!exact.length) {
    // No exact match — try (a) substring contains, (b) Levenshtein distance
    // to catch typos. Surface the union as chips so the user picks one.
    const partial = inventory.filter(f => (f.name || "").toLowerCase().includes(lc));
    let candidates = partial.slice();
    if (candidates.length < 5) {
      // Fallback: Levenshtein-similarity rank for typo-style misspellings
      // (e.g. "Income Statment" → "Income Statement").
      const norm = s => (s || "").toLowerCase().replace(/^nfs[_\s]*/i, "").replace(/[\.\s]+$/, "").trim();
      const target = norm(formName);
      const scored = inventory
        .filter(f => !partial.includes(f))
        .map(f => ({ f, d: levenshtein(target, norm(f.name)) }))
        // tolerate up to 35% of the longer-string length, capped at 6 edits
        .filter(x => x.d <= Math.min(6, Math.ceil(Math.max(target.length, x.f.name.length) * 0.35)))
        .sort((a, b) => a.d - b.d);
      for (const s of scored) {
        if (candidates.length >= 8) break;
        candidates.push(s.f);
      }
    }
    if (!candidates.length) {
      throw new Error(`Form "${formName}" not found. Available forms (sample): ` +
        inventory.slice(0, 8).map(f => f.name).join(" · "));
    }
    candidates.sort((a, b) => (a.path || "").length - (b.path || "").length);
    const chips = candidates.slice(0, 8).map(f =>
      `CHIP: ${f.name} → open ${f.name}`).join("\n");
    throw new Error(
      `No exact match for "${formName}". Did you mean one of these?\n${chips}\n` +
      `Please select one above or type the exact name.`
    );
  }
  exact.sort((a, b) => (a.path || "").length - (b.path || "").length);
  const form = exact[0];
  const fullPath = (form.path && form.path !== "/" ? form.path : "") + "/" + form.name;

  // LCM lookup FIRST (used to be after the slice): when the tenant KB knows
  // this form, its instructions/rules are definitive and the
  // HspFormRuntimeServlet round-trip is SKIPPED entirely; when it doesn't,
  // the props fetch runs IN PARALLEL with the slice instead of after it.
  // Both shave seconds off every first form open.
  const tkbNow = opts.tenantKb
    || ((typeof EMBED_TENANT_KB !== "undefined" && EMBED_TENANT_KB) ? EMBED_TENANT_KB : null);
  const normLcm = s => (s || "").toLowerCase().replace(/^nfs_/i, "").replace(/\.+$/, "").trim();
  const lcmForm = (tkbNow && Array.isArray(tkbNow.forms))
    ? tkbNow.forms.find(f =>
        (f.name || "").toLowerCase() === (form.name || "").toLowerCase() ||
        normLcm(f.name) === normLcm(form.name))
    : null;
  const lcmFormFound = !!lcmForm;

  const propsPromise = (form.formId && !lcmFormFound) ? (async () => {
    try {
      const propsUrl = String(settings.host).replace(/\/+$/, "") +
        `/HyperionPlanning/servlet/HspFormRuntimeServlet?Action=getFormProps` +
        `&Application=${encodeURIComponent(settings.appName || "NetSuite")}` +
        `&formId=${encodeURIComponent(form.formId)}`;
      const propsResp = await fetch(propsUrl, {
        method: "GET",
        headers: {
          "Authorization": basicAuth(settings.username, settings.password),
          "Accept": "application/json"
        }
      });
      if (propsResp.ok) return await propsResp.text();
    } catch (e) {
      console.log("open_form: HspFormRuntimeServlet failed (non-fatal):", e.message);
    }
    return "";
  })() : Promise.resolve("");

  // 2. SV session.
  let sID = await smartViewOpenApp(settings);

  // 3. req_GetFormSlice — full preferences block as captured from real Smart
  //    View Excel add-in. Critical: <navigate withData="1"/> tells the server
  //    to populate cell values; without it the slice comes back as empty cells
  //    even when the form has data. <sliceLimitation> sets the row/col cap
  //    (Excel max). All other <preferences> children mirror the SV defaults.
  //    We CAPTURE failures here rather than throwing — user still wants
  //    instructions + rules even when the slice can't render (e.g. errcode
  //    60000 when missing access to a required dimension).
  const buildSliceXml = (sid, withData = "0") =>
    `<req_GetFormSlice>` +
    `<sID>${svEscape(sid)}</sID>` +
    `<name>${svEscape(fullPath)}</name>` +
    `<preferences>` +
      `<row_suppression zero="0" invalid="0" missing="0" underscore="0" noaccess="0"/>` +
      `<celltext val="1"/>` +
      `<zoomin ancestor="top" mode="children"/>` +
      `<navigate withData="${withData}"/>` +
      `<includeSelection val="1"/>` +
      `<repeatMemberLabels val="1"/>` +
      `<withinSelectedGroup val="0"/>` +
      `<removeUnSelectedGroup val="0"/>` +
      `<col_suppression zero="0" invalid="0" missing="0" underscore="0" noaccess="0"/>` +
      `<block_suppression missing="0"/>` +
      `<useExpenseType val="0"/>` +
      `<enableMeaningless val="0"/>` +
      `<repeatMemberLabelsInForms val="0"/>` +
      `<enableClientSideIndentation val="0"/>` +
      `<includeDescriptionInLabel val="0"/>` +
      `<missingLabelText val="#NumericZero"/>` +
      `<noAccessText val="#No Access"/>` +
      `<essIndent val="2"/>` +
      `<FormatSetting val="2"/>` +
      `<sliceLimitation rows="1048576" cols="16384"/>` +
      `<pageMemberIndent val="1"/>` +
      `<ValidIntersections val="1"/>` +
      `<supportsDesignTimeFormatting val="1"/>` +
      `<supportsSuppressedDims val="1"/>` +
    `</preferences>` +
    `</req_GetFormSlice>`;
  let respXml = "";
  let sliceError = null;
  let parsed = { grid: [] };
  try {
    // Try withData="1" first (structure + values) so users see numbers
    // immediately. Fall back to withData="0" if it errors — that happens
    // when the user lacks data access to a POV dim, in which case the
    // structure-only call still succeeds.
    respXml = await svPost(settings, buildSliceXml(sID, "1"));
    if (svSessionExpired(respXml)) {
      sID = await smartViewOpenApp(settings, true);
      respXml = await svPost(settings, buildSliceXml(sID, "1"));
    }
    // If withData=1 returned an exception, retry with structure-only
    const initialExc = respXml.match(/<(?:res_Exception|exception)[^>]*errcode="([^"]+)"/i);
    if (initialExc) {
      console.log("[OPEN_FORM_FALLBACK]", form.name, "withData=1 errcode=" + initialExc[1] + ", retrying withData=0");
      respXml = await svPost(settings, buildSliceXml(sID, "0"));
    }
    // Oracle uses both <res_Exception> and lowercase <exception> depending on
    // the endpoint / error type.
    const exc = respXml.match(/<(?:res_Exception|exception)[^>]*errcode="([^"]+)"[^>]*>[\s\S]*?<desc>([\s\S]*?)<\/desc>/i)
             || respXml.match(/<(?:res_Exception|exception)[^>]*errcode="([^"]+)"[^>]*\/>/i);
    if (exc) {
      const errcode = exc[1];
      const errdesc = svUnescape(exc[2] || "").slice(0, 240).trim();
      if (errcode === "60000") {
        // errcode 60000 covers a few cases: composite/dashboard forms,
        // forms with restricted POV access, or artifacts that SmartView
        // declines to serve. Swallow silently and let the higher-level
        // 'no grid' fallback explain — we don't surface specific reasons.
      } else {
        sliceError = `errcode=${errcode}: ${errdesc}`;
      }
    } else {
      try {
        parsed = parseSmartViewSlice(respXml);
        console.log("[OPEN_FORM_PARSE_OK]", form.name, "rows=", parsed.rows, "cols=", parsed.cols, "povLen=", (parsed.pov||[]).length);
      } catch (parseErr) {
        // If parse throws with the raw errcode 60000 in the message, suppress it.
        const msg = String(parseErr.message || parseErr);
        if (!msg.includes('errcode=""60000""') && !msg.includes("errcode=\"60000\"")) {
          sliceError = `parse failed: ${msg}`;
        }
        console.log("[OPEN_FORM_PARSE_ERR]", form.name, msg);
      }
    }
    if (sliceError) {
      console.log("[OPEN_FORM_SLICE_ERR]", form.name, sliceError, "xml head:", respXml.slice(0, 600));
    }
  } catch (e) {
    sliceError = String(e && e.message || e);
  }

  // 4a. Form props — the fetch was launched in parallel with the slice (or
  //     skipped when the LCM KB knows this form); just collect it here.
  let instructions = "";
  let formProps = null;
  const rawPropsText = await propsPromise;
  if (rawPropsText) {
    try {
      formProps = JSON.parse(rawPropsText);
      instructions = formProps.instructions || formProps.formInstructions ||
                     formProps.description || formProps.instructionsHTML || "";
    } catch (_) {
      // Salvage <instructions>...</instructions> from XML/HTML response.
      const m = rawPropsText.match(/<instructions[^>]*>([\s\S]*?)<\/instructions>/i);
      if (m) instructions = m[1].trim();
    }
  }

  // 4b. Attached-rule discovery — try multiple sources in priority order:
  //  (0)   EMBED_TENANT_KB (LCM export) — definitive, zero extra API calls.
  //  (i)   formProps JSON with broad field-name aliases.
  //  (ii)  formProps raw XML/HTML — scan for <rule>, <businessRule>, etc.
  //  (iii) SmartView req_EnumBusinessRules with subformId=formId.
  let attachedRules = [];
  let rulesSource = "none";

  // (0) LCM source — most reliable; comes from the Oracle export, not runtime.
  // The lookup itself was hoisted above the slice fetch (lcmForm /
  // lcmFormFound / tkbNow) so the props round-trip could be skipped.
  if (lcmForm) {
    if (!instructions && lcmForm.instructions) {
      instructions = lcmForm.instructions;
    }
    if (Array.isArray(lcmForm.attachedRules) && lcmForm.attachedRules.length) {
      const ruleMap = {};
      if (Array.isArray(tkbNow.rules)) for (const r of tkbNow.rules) ruleMap[r.name] = r;
      for (const lr of lcmForm.attachedRules) {
        const full = ruleMap[lr.name] || {};
        attachedRules.push({
          name: lr.name,
          description: full.description || lr.description || "",
          hasRTP: !!(full.hasRTP || lr.hasRTP),
          runOnSave: !!(lr.runOnSave),
          runBeforeSave: false,
          runOnLoad: false
        });
      }
      if (attachedRules.length) rulesSource = "lcm";
    } else {
      // LCM explicitly has no rules for this form — mark as confirmed-empty
      rulesSource = "lcm-none";
    }
  }

  // (i–iii) Runtime fallbacks — only used when the form is NOT in the LCM KB.
  // If LCM found the form (lcmFormFound=true), trust it completely — even if it
  // says no rules. SmartView EnumBusinessRules returns cube-wide rules that are
  // not form-specific, which is misleading.

  // (i) JSON formProps.
  if (!lcmFormFound && formProps) {
    const aliases = ["businessRules", "attachedRules", "rules", "runOnSaveRules",
                     "runOnLoadRules", "runBeforeSaveRules", "formRules", "ruleList",
                     "rulesList", "attachedBusinessRules", "ruleDefinitions"];
    let rulesField = null;
    for (const k of aliases) {
      if (Array.isArray(formProps[k]) && formProps[k].length) { rulesField = formProps[k]; break; }
    }
    if (rulesField) {
      for (const r of rulesField) {
        const name = r.name || r.ruleName || r.businessRuleName || r.label || "";
        if (!name) continue;
        attachedRules.push({
          name,
          description:    r.description || r.desc || "",
          hasRTP:         !!(r.hasRuntimePrompts || r.rtp || r.hasRTP),
          runOnSave:      !!(r.runOnSave || r.runAfterSave),
          runBeforeSave:  !!(r.runBeforeSave),
          runOnLoad:      !!(r.runOnLoad || r.runOnFormLoad)
        });
      }
      if (attachedRules.length) rulesSource = "formProps-json";
    }
  }

  // (ii) XML/HTML formProps fallback.
  if (!lcmFormFound && !attachedRules.length && rawPropsText && !formProps) {
    const re = /<(?:rule|businessRule|associatedRule|attachedRule)\s+([^>]*?)>([\s\S]*?)<\/(?:rule|businessRule|associatedRule|attachedRule)>/g;
    let m;
    while ((m = re.exec(rawPropsText))) {
      const attrs = m[1];
      const name = svUnescape(m[2]).trim();
      if (!name) continue;
      const get = (k) => (attrs.match(new RegExp(k + '="([^"]*)"')) || [])[1] || "";
      attachedRules.push({
        name,
        description:    svUnescape(get("desc") || get("description")),
        hasRTP:         get("rtp") === "1",
        runOnSave:      get("runOnSave") === "1",
        runBeforeSave:  get("runBeforeSave") === "1",
        runOnLoad:      get("runOnLoad") === "1"
      });
    }
    if (attachedRules.length) rulesSource = "formProps-xml";
  }

  // (iii) SV req_EnumBusinessRules with subformId=formId.
  if (!lcmFormFound && !attachedRules.length && wantRules && form.formId) {
    const rulesXml =
      `<req_EnumBusinessRules>` +
      `<sID>${svEscape(sID)}</sID>` +
      `<cube>${svEscape(form.cube || "Plan")}</cube>` +
      `<subformId>${svEscape(form.formId)}</subformId>` +
      `<runOnSave>0</runOnSave>` +
      `</req_EnumBusinessRules>`;
    try {
      const rulesResp = await svPost(settings, rulesXml);
      parseSvRules(rulesResp, attachedRules);
      if (attachedRules.length) rulesSource = "sv-subform";
    } catch (e) {
      console.log("open_form: EnumBusinessRules(subformId) failed:", e.message);
    }
  }

  // Cube-wide fallback intentionally removed — it returned ALL rules for the
  // cube (45+) regardless of whether they apply to this form, which is
  // misleading. If no form-specific rules are found, we report none.

  // 5. Build the output grid — form slice with POV header rows on top, like
  //    a native SmartView ad-hoc grid. POV format mirrors what SmartView
  //    writes when you Open Form: each POV dim on its own row, label on the
  //    left, member on the right. Then a blank separator, then the slice.
  //    This way the user can connect SmartView and Refresh without losing
  //    context — POV is visible and editable like any normal SV grid.
  const sheetName = String(form.name || "form").replace(/[:\\/\?\*\[\]]/g, "-").slice(0, 25);
  const formGrid = parsed.grid;
  const pov = Array.isArray(parsed.pov) ? parsed.pov : [];
  const out = [];

  if (sliceError) {
    // Leave grid empty — form is a dashboard or no access. Gemini will explain.
  } else {
    // POV column placement: align with the FIRST DATA column (where the
    // column-dim header sits). The slice has N row-label columns on the
    // left (one per row dim) and column-headers above the data area —
    // we detect this by scanning the slice for the first column whose
    // top header row has content. Col B (idx 1) is just a fallback.
    const gridCols = formGrid.length && formGrid[0] ? formGrid[0].length : 2;
    let firstDataCol = 1;
    // Scan the first row of formGrid that has any non-empty cell — that's
    // typically the topmost column-header row. Find the first non-empty
    // column there.
    for (const row of formGrid) {
      let foundCol = -1;
      for (let c = 0; c < row.length; c++) {
        const v = row[c];
        if (v !== "" && v != null) { foundCol = c; break; }
      }
      if (foundCol >= 0) { firstDataCol = foundCol; break; }
    }
    const povCol = Math.min(firstDataCol, gridCols - 1);
    if (pov.length) {
      for (const p of pov) {
        const mbr = p.member || p.value || "";
        const row = new Array(Math.max(gridCols, povCol + 1)).fill("");
        row[povCol] = mbr;
        out.push(row);
      }
      // No separator — go straight from POV into the slice
    }
    // Strip all-empty rows from the form slice (some forms have spacer rows)
    for (const row of formGrid) {
      const allEmpty = row.every(c => c === "" || c == null);
      if (!allEmpty) out.push(row.slice());
    }
  }

  // Build rules summary for the tool result (shown in chat by Gemini).
  const sourceLabel = ({
    "lcm":            "LCM export (definitive)",
    "lcm-none":       "none (confirmed by LCM export — no rules attached to this form)",
    "formProps-json": "form-specific",
    "formProps-xml":  "form-specific",
    "sv-subform":     "form-specific",
    "sv-cube":        "cube-wide (no form-specific rules found)",
    "none":           "none"
  })[rulesSource] || rulesSource;

  const instructionsPlain = instructions
    ? String(instructions).replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim()
    : null;

  // When the form has no LCM-attached rules and we fell back to cube-wide
  // rules (~50 of them), Gemini lists every single one — overwhelming. Filter
  // by name relevance to the form: keep rules whose name contains any token
  // from the form name (≥3 chars). Always cap at 6.
  // FILTER OUT calc scripts (CURRENCY/DEFAULT) and unregistered rules — the
  // user only wants to see ACTUAL Business Rules they can invoke. Calc scripts
  // auto-fire in SmartView and aren't runnable via REST. The kind classifier
  // is set in parse-lcm.js (v5+); fall back to legacy heuristics for older KBs.
  const runnableNamesSet = new Set(
    (tkbNow && Array.isArray(tkbNow.rules) ? tkbNow.rules : [])
      .map(r => (r.name || "").toLowerCase())
      .filter(Boolean)
  );
  const isRunnableBR = (r) => {
    if (!r || !r.name) return false;
    if (r.kind) return r.kind === "runnable";
    if (r.calcType === "3") return false;
    if (runnableNamesSet.size > 0) return runnableNamesSet.has(r.name.toLowerCase());
    return true;
  };
  const runnableAttached = attachedRules.filter(isRunnableBR);

  // Cube-wide rules = the form has NO directly-attached rules in LCM, so the
  // worker fell back to listing rules of the same cube. These are guesses,
  // not confirmed associations — cap them tight (3 max) so we don't bury the
  // user under 8+ irrelevant chips.
  const isCubeWide = /cube-wide/i.test(rulesSource) || /cube-wide/i.test(sourceLabel);
  const CUBEWIDE_MAX = 3;
  const ATTACHED_MAX = 6;
  let displayRules = runnableAttached;
  if (isCubeWide) {
    const formTokens = (form.name || "")
      .replace(/^NFS_/i, "")
      .split(/[\s_\-/().,]+/)
      .filter(t => t && t.length >= 3 && !/^(the|and|for|with|by|of)$/i.test(t))
      .map(t => t.toLowerCase());
    const score = (rule) => {
      const n = String(rule.name || "").toLowerCase();
      let s = 0;
      for (const tok of formTokens) if (n.includes(tok)) s += 2;
      // Bonus: rules with description (more documented) and onSave (active)
      if (rule.description) s += 0.5;
      if (rule.runOnSave) s += 1;
      return s;
    };
    displayRules = runnableAttached
      .map(r => ({ r, s: score(r) }))
      .sort((a, b) => b.s - a.s)
      .filter(x => x.s > 0)
      .slice(0, CUBEWIDE_MAX)
      .map(x => x.r);
    if (displayRules.length === 0) {
      displayRules = runnableAttached
        .filter(r => r.runOnSave || r.description)
        .slice(0, CUBEWIDE_MAX);
    }
    // Last resort: just take the first N if name-scoring + heuristic both
    // came up empty. Better than showing 8 random rules.
    if (displayRules.length === 0) {
      displayRules = runnableAttached.slice(0, CUBEWIDE_MAX);
    }
  } else if (runnableAttached.length > ATTACHED_MAX) {
    displayRules = runnableAttached.slice(0, ATTACHED_MAX);
  }

  // ── Skeleton rows for fully-suppressed forms ───────────────────────────────
  // Data-entry dead-end: at an empty intersection Oracle suppresses every
  // row, so an INPUT form renders headers-only and the user has nowhere to
  // type. Rebuild the row skeleton from the form's LCM definition (rowDims /
  // rowMembers, leaves resolved live via REST). Data cells stay BLANK on
  // purpose — NOT 0: submit writes numeric cells, so placeholder zeros would
  // write real 0s into the cube.
  let skeletonRows = 0;
  try {
    // Header-row count: from the response axis attrs when present, else from
    // the KB's column-dim list — some tenants/forms omit row=/col= attrs in
    // the <dim> tags entirely (seen live: "no axis attrs in response").
    const headerRowCount = Math.max(
      ((parsed.axes && parsed.axes.colDims) || []).length,
      (lcmForm && Array.isArray(lcmForm.columnDims)) ? lcmForm.columnDims.length : 0
    );
    const noDataRows = !sliceError && out.length > 0 && (parsed.grid || []).length <= headerRowCount;
    if (noDataRows && lcmForm &&
        Array.isArray(lcmForm.rowDims) && lcmForm.rowDims.length &&
        Array.isArray(lcmForm.rowMembers) && lcmForm.rowMembers.length) {
      // Cube: tightest appConfig fit over the form's real dim names.
      const allFormDims = [].concat(lcmForm.rowDims, lcmForm.columnDims || [], lcmForm.povDims || []);
      let skCube = null;
      const cfg = (opts && opts.appConfig) || null;
      if (cfg && cfg.cubeDims) {
        const cands = Object.keys(cfg.cubeDims).filter(c =>
          allFormDims.every(d => (cfg.cubeDims[c] || []).includes(d)));
        cands.sort((a, b) => (cfg.cubeDims[a] || []).length - (cfg.cubeDims[b] || []).length);
        skCube = cands[0] || null;
      }
      const dim0 = lcmForm.rowDims[0];
      let members = [];
      for (const seed of lcmForm.rowMembers.slice(0, 5)) {
        let leaves = null;
        if (skCube) {
          try { leaves = await resolveRowMembers(settings, skCube, dim0, `ILvl0Descendants(${seed})`); }
          catch (_) { /* probe can fail on odd POV defaults — fall back to the seed */ }
        }
        members = members.concat((leaves && leaves.length) ? leaves : [seed]);
        if (members.length >= 200) break;
      }
      members = [...new Set(members)].slice(0, 200);
      const width = out.reduce((w, r) => Math.max(w, (r || []).length), 2);
      for (const m of members) {
        const row = new Array(width).fill("");
        row[0] = m;
        out.push(row);
      }
      skeletonRows = members.length;
      console.log("[OPEN_FORM_SKELETON]", form.name, "rows:", skeletonRows, "cube:", skCube, "dim:", dim0);
    }
  } catch (e) { console.log("[OPEN_FORM_SKELETON] failed:", e.message || e); }

  // Data presence — a form that renders only headers (rows fully suppressed
  // at this POV) or all-blank cells must NOT read as success in the chat.
  let formDataCells = 0;
  for (const r of out) for (const v of (r || [])) if (typeof v === "number") formDataCells++;

  return {
    sheetName: `Form_${sheetName}`,
    grid: out.length ? out : null,   // null = no sheet written (dashboard/FR/no-access)
    dataCellCount: out.length ? formDataCells : null,
    skeletonRows,   // >0 = rows rebuilt from the form definition (suppressed slice)
    sliceError: sliceError || null,  // exposed so Gemini can explain FR vs dashboard
    types: Array.isArray(parsed.types) ? parsed.types : null,   // parallel 2D type-codes
    statuses: Array.isArray(parsed.statuses) ? parsed.statuses : null,  // parallel 2D access bitmasks (0x2=read-only)
    pov: Array.isArray(parsed.pov) ? parsed.pov : [],   // [{dim, member, alias}, ...]
    // Adhoc-style descriptor synthesized from the slice — lets modify_grid
    // navigate this form grid (add year, pivot, zoom…) like any ad-hoc.
    gridDescriptor: (out.length && !sliceError)
      ? synthesizeFormDescriptor(parsed, respXml, {
          appConfig: (opts && opts.appConfig) || null,
          formCube: form.cube || null,   // inventory cube (ignored when it's a numeric LCM plan-type id)
          sheetName: `Form_${sheetName}`
        })
      : null,
    inPlace: false,
    format: "raw",   // skip default ad-hoc styling — keep clean for SmartView Refresh
    sectionRows: null,
    formCategory: (() => {
      // Prefer LCM isInput (definitive) over discovered form.category.
      if (tkbNow && Array.isArray(tkbNow.forms)) {
        const lf = tkbNow.forms.find(f => (f.name||"").toLowerCase() === (form.name||"").toLowerCase());
        if (lf && lf.isInput !== undefined) return lf.isInput ? "input" : "review";
      }
      return form.category || null;
    })(),
    // These fields go into the tool result → Gemini presents them in chat:
    instructions: instructionsPlain || null,
    rulesSource: sourceLabel,
    suggestedChips: buildFormChips(form, attachedRules, tkbNow, sourceLabel),
    totalRulesAvailable: runnableAttached.length,
    rulesShown: displayRules.length,
    rulesFiltered: runnableAttached.length > displayRules.length,
    rules: displayRules.map(r => ({
      name: r.name,
      description: r.description || "",
      triggers: [
        r.runOnLoad ? "on-load" : null,
        r.runBeforeSave ? "before-save" : null,
        r.runOnSave ? "on-save" : null
      ].filter(Boolean).join(", ") || "manual",
      hasRTP: r.hasRTP
    })),
    debug: {
      formPath: fullPath,
      formId: form.formId,
      cube: form.cube,
      ruleCount: attachedRules.length,
      rulesSource,
      hasInstructions: !!instructions,
      sliceError,
      formPropsKeys: formProps ? Object.keys(formProps).slice(0, 20) : null
    }
  };
}
