// ── EXPLAIN_TOOL family ─────────────────────────────────────────────
// Anti-churn / teaching tools. NSPB has a steep learning curve and most
// teams give up because they don't understand it. These tools translate
// the cube + LCM into plain English, grounded in the tenant's REAL forms
// and rules — not generic Hyperion docs.
//
// Powered by data parse-lcm.js extracts: form layouts, rule bodies
// (Groovy / CalcScript source), substitution variables, FDMEE rules,
// dim hierarchies. All embedded in tenant-kb.json at build time so the
// runtime is instant and grounded.
const EXPLAIN_TOOL = {
  name: "explain",
  description: "Plain-English explanation of any NSPB artifact — grounded in the tenant's real metadata (forms, rules, dims, vars from the LCM-parsed knowledge base). Use when the user says: 'explain rule X', 'qué hace la rule X', 'explain form X', 'cómo funciona el form X', 'explain account X', 'where can I edit account X', 'what calculates X', 'why is X zero', 'why isn't X calculating', 'show data flow', 'how does data move from A to B', 'what does this rule do', 'what is X for', '¿qué es X?'.\n\nThis tool reads the embedded tenant KB (rule bodies, form layouts, etc.) and either returns a structured explanation directly, OR — when the user asks deeper questions — flags the rule body for the AI to summarize in the same turn.",
  input_schema: {
    type: "object",
    properties: {
      target: {
        type: "string",
        enum: ["rule", "form", "account", "variable", "variance", "data_flow", "concept"],
        description: "What kind of artifact to explain. 'rule' → look up the calc script body. 'form' → look up the form metadata + attached rules. 'account' → cross-ref where it's editable + what calculates it. 'variable' → look up a substitution variable + which rules / forms reference it. 'variance' → explain a specific variance (current vs prior). 'data_flow' → trace data movement. 'concept' → explain a generic NSPB term using the KB."
      },
      name: {
        type: "string",
        description: "The rule / form / account / concept name. For 'why is X zero' use the account name."
      },
      includeBody: {
        type: "boolean",
        description: "For target='rule': include the FULL script body in the response so the AI can summarize it. Use when the user asks 'what does this rule actually do' / 'walk me through the script'."
      }
    },
    required: ["target"]
  }
};

