// Wide-scan probe of NSPB REST endpoints — looking for ones that expose
// metadata we currently get from LCM (form descriptions/instructions,
// rule descriptions, navigation flow detail, dashboards, attached rules).
// Returns 2xx hits with sample bodies so we can identify usable paths.
async function probeMetadataEndpoints(settings) {
  const base = String(settings.host).replace(/\/+$/, "");
  const app = encodeURIComponent(settings.appName || "NetSuite");
  const auth = basicAuth(settings.username, settings.password);
  const candidates = [
    // Forms
    `${base}/HyperionPlanning/rest/v3/applications/${app}/forms`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/forms?limit=3`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/forms?expand=details`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/forms/all`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/dataforms`,
    // Form properties / instructions / rules
    `${base}/HyperionPlanning/rest/v3/applications/${app}/forms/Income%20Statement`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/forms/Income%20Statement/properties`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/forms/Income%20Statement/businessrules`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/forms/Income%20Statement/rules`,
    // Business rules
    `${base}/HyperionPlanning/rest/v3/applications/${app}/businessrules`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/businessrules?limit=3`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/rules`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/calcs`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/calcrules`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/groovyrules`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/rulesets`,
    // Dashboards / reports
    `${base}/HyperionPlanning/rest/v3/applications/${app}/dashboards`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/reports`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/infolets`,
    // Navigation flows (detail)
    `${base}/HyperionPlanning/rest/v3/applications/${app}/navflows`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/navflows?expand=clusters`,
    // Smart Push / Data Map
    `${base}/HyperionPlanning/rest/v3/applications/${app}/smartpushes`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/datamaps`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/clearcubes`,
    // Cell-level / valid intersections
    `${base}/HyperionPlanning/rest/v3/applications/${app}/validintersections`,
    // Approvals
    `${base}/HyperionPlanning/rest/v3/applications/${app}/approvalunits`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/scenarios`,
    // Members / aliases
    `${base}/HyperionPlanning/rest/v3/applications/${app}/aliastables`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/attributes`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/usergroups`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/users`,
    // efsvbuirest (NSPB Web UI internal)
    `${base}/HyperionPlanning/efsvbuirest/v1/applications/${app}/dataforms`,
    `${base}/HyperionPlanning/efsvbuirest/v1/applications/${app}/forms`,
    `${base}/HyperionPlanning/efsvbuirest/v1/applications/${app}/businessrules`,
    `${base}/HyperionPlanning/efsvbuirest/v1/applications/${app}/dashboards`,
    `${base}/HyperionPlanning/efsvbuirest/v1/applications/${app}/navflows`,
    // v1 / v2 variations (some tenants only expose older versions)
    `${base}/HyperionPlanning/rest/v1/applications/${app}/forms`,
    `${base}/HyperionPlanning/rest/v1/applications/${app}/businessrules`,
    `${base}/HyperionPlanning/rest/v2/applications/${app}/forms`,
    `${base}/HyperionPlanning/rest/v2/applications/${app}/businessrules`,
  ];
  const results = [];
  for (const url of candidates) {
    try {
      const r = await fetch(url, {
        method: "GET",
        headers: { "Authorization": auth, "Accept": "application/json" }
      });
      const text = await r.text();
      let json = null;
      try { json = JSON.parse(text); } catch (_) {}
      results.push({
        url: url.replace(base, ""),
        status: r.status,
        ok: r.ok,
        bytes: text.length,
        sample: text.slice(0, 400),
        keys: json && typeof json === "object" ? Object.keys(json).slice(0, 10) : null,
        items: json && Array.isArray(json.items) ? json.items.length : null
      });
    } catch (e) {
      results.push({ url: url.replace(base, ""), status: 0, error: String(e.message || e) });
    }
  }
  return { probedAt: Date.now(), results };
}

// Probe NSPB for scheduled-job endpoints. Oracle docs are vague — the
// scheduler sits behind various paths depending on tenant version. Try a
// list of candidates and report which one returned 2xx with parseable JSON.
async function probeScheduleEndpoints(settings) {
  const base = String(settings.host).replace(/\/+$/, "");
  const app = encodeURIComponent(settings.appName || "NetSuite");
  const auth = basicAuth(settings.username, settings.password);
  const candidates = [
    `${base}/HyperionPlanning/rest/v3/applications/${app}/schedules`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/schedule`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/scheduledjobs`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/jobdefinitions`,
    `${base}/HyperionPlanning/rest/v1/applications/${app}/schedules`,
    `${base}/HyperionPlanning/rest/jobs/v3/applications/${app}/schedule`,
    `${base}/interop/rest/v1/applicationsnapshots?type=schedule`,
    `${base}/interop/rest/v1/jobs/scheduled`,
    `${base}/aif/rest/V1/jobs?type=scheduled&limit=5`,
    `${base}/aif/rest/V1/scheduledjobs`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/jobs?type=schedule`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/jobs?status=SCHEDULED`,
    `${base}/HyperionPlanning/rest/v3/applications/${app}/jobs?scheduled=true`,
  ];
  const results = [];
  for (const url of candidates) {
    try {
      const r = await fetch(url, {
        method: "GET",
        headers: { "Authorization": auth, "Accept": "application/json" }
      });
      const text = await r.text();
      const body = text.slice(0, 500);
      let json = null;
      try { json = JSON.parse(text); } catch (_) {}
      results.push({
        url: url.replace(base, ""),
        status: r.status,
        ok: r.ok,
        bytes: text.length,
        sample: body,
        keys: json && typeof json === "object" ? Object.keys(json).slice(0, 8) : null,
        items: json && (Array.isArray(json.items) ? json.items.length : null)
      });
    } catch (e) {
      results.push({ url: url.replace(base, ""), status: 0, error: String(e.message || e) });
    }
  }
  return { probedAt: Date.now(), results };
}

// Strip one layer of surrounding double quotes. NSPB stores some values
// quoted ("TP6") and others bare (TP6); a round-trip must compare equal.
function unquoteVarValue(v) {
  return String(v == null ? "" : v).trim().replace(/^"([\s\S]*)"$/, "$1");
}

async function listSubstVars(settings) {
  const data = await nspbGet(settings, "/substitutionvariables");
  return Array.isArray(data.items) ? data.items : [];
}

// Scope of a listed variable. NSPB has spelled this field differently across
// versions, so accept all three; "" means the response didn't say.
function substVarScope(v) {
  return String((v && (v.planType || v.planningType || v.cube)) || "").trim();
}

function findSubstVar(items, name) {
  const needle = String(name || "").toLowerCase();
  return (items || []).find(v =>
    String((v && (v.name || v.variable)) || "").toLowerCase() === needle) || null;
}

async function setSubstVar(settings, name, value, cube) {
  const cleanName = String(name || "").replace(/^&/, "").trim();
  if (!cleanName) throw new Error("Variable name required");
  const valStr = value == null ? "" : String(value);

  // NSPB requires the /plantypes/{cube}/ segment always (sniff confirmed —
  // POST to plain /substitutionvariables returns 405). App-level vars use the
  // literal token "ALL" both in the URL path AND in the body's planType;
  // cube-scoped vars use the cube name in both places. They MUST match —
  // otherwise NSPB returns 400 "Plan type specified does not match the request".
  let before = null;
  try { before = await listSubstVars(settings); } catch (_) { /* non-fatal */ }

  // When the caller didn't name a cube, resolve the variable's REAL scope
  // before writing. An app-level ("ALL") payload aimed at a cube-scoped
  // variable is accepted by NSPB but lands on a different variable, so the
  // one the rules actually read never moves.
  let urlCube = String(cube || "").trim();
  if (!urlCube) {
    const scope = substVarScope(findSubstVar(before, cleanName));
    if (scope && !/^(global|all)$/i.test(scope)) urlCube = scope;
  }
  urlCube = urlCube || "ALL";
  const collectionPath = `/plantypes/${encodeURIComponent(urlCube)}/substitutionvariables`;
  const item = { name: cleanName, value: valStr, planType: urlCube };

  await nspbPost(settings, collectionPath, { items: [item] });

  // Read back. A 2xx on the POST is NOT evidence the value changed — NSPB
  // acks writes it then scopes elsewhere, which is exactly how the chat came
  // to report "✓ Variable updated" over a variable that never moved. Callers
  // must surface `verified` instead of trusting the ack.
  let actualValue = null;
  let verified = null;          // true | false | null (couldn't read back)
  let variables = null;
  try {
    const after = await listSubstVars(settings);
    variables = after.map(v => ({
      name:  (v && (v.name || v.variable)) || "",
      value: v && v.value != null ? String(v.value) : "",
      scope: substVarScope(v) || "Global"
    })).filter(v => v.name);
    const hit = findSubstVar(after, cleanName);
    if (hit) {
      actualValue = hit.value != null ? String(hit.value) : "";
      verified = unquoteVarValue(actualValue) === unquoteVarValue(valStr);
    } else {
      verified = false;
    }
  } catch (_) { /* leave verified null — "couldn't confirm" */ }

  return {
    name: cleanName,
    value: valStr,
    actualValue,
    verified,
    cube: cube || null,
    scope: /^all$/i.test(urlCube) ? "application" : "cube",
    via: urlCube,
    variables,
    variablesLoadedAt: variables ? Date.now() : null
  };
}

// ── Dimension discovery (single bulk call per dim) ──────────────────────────
// `GET /plantypes/{cube}/dimensions/{dim}` returns the ENTIRE member tree
// in one response (nested children[] arrays with name, parentName, level,
// aliasPath, etc). This is dramatically better than the member-by-member
// walk MCP3 uses: 1 subrequest per dim instead of N, which keeps us under
// Cloudflare's 50-subrequest-per-invocation limit even on the free tier.
//
// Returns a flat array of { name, alias, parent, level, hasChildren }.
async function loadDimMembers(settings, dim, cube) {
  const planCube = cube || CLIENT_CONFIG.mainCube || "Plan";
  const data = await nspbGet(settings,
    "/plantypes/" + encodeURIComponent(planCube) +
    "/dimensions/" + encodeURIComponent(dim));

  const out = [];
  function walk(node, depth) {
    if (!node || !node.name) return;
    // NSPB's tree response doesn't include a raw alias field; aliasPath is
    // the alias-rendered hierarchy path. The leaf segment is the alias if
    // it differs from the name.
    let alias = "";
    if (node.alias) {
      alias = typeof node.alias === "string" ? node.alias
            : (node.alias.Default || node.alias.default ||
               Object.values(node.alias)[0] || "");
    } else if (node.aliasPath) {
      const leaf = String(node.aliasPath).split("/").pop();
      if (leaf && leaf !== node.name) alias = leaf;
    }
    const children = node.children || [];
    out.push({
      name: node.name,
      alias,
      parent: node.parentName || "",
      level: typeof node.level === "number" ? node.level : depth,
      hasChildren: children.length > 0
    });
    for (const ch of children) walk(ch, depth + 1);
  }

  // Top-level response has `children[]` = the dim's top-level members.
  // (The dim object itself is the implicit root — we skip it since its
  // "name" is just the dim name and carries no useful info.)
  for (const ch of (data.children || [])) walk(ch, 0);
  return out;
}

async function runDiscover(settings, dimsOverride) {
  const dims = Array.isArray(dimsOverride) && dimsOverride.length
    ? dimsOverride
    : (CLIENT_CONFIG.discoveryDims || []);
  if (!dims.length) throw new Error("No dims to discover (check clientNetsuite.js)");

  // Use the cube from settings if provided (passed by taskpane when appConfig is known),
  // otherwise fall back to CLIENT_CONFIG.mainCube.
  const cube = settings.mainCube || CLIENT_CONFIG.mainCube || "Plan";

  const catalog = {};
  const errors = {};
  for (const d of dims) {
    try {
      catalog[d] = await loadDimMembers(settings, d, cube);
    } catch (e) {
      console.log(`discover: ${d} failed:`, e && e.message);
      errors[d] = String(e && e.message || e);
    }
  }
  return { loadedAt: Date.now(), catalog, errors };
}

// ── Business-rule discovery ─────────────────────────────────────────────────
// Oracle EPM/NSPB exposes job definitions at /jobdefinitions. Filtering by
// jobtype=RULES gets us the business rules (other jobtypes: RULESETS, BUSINESS_RULE,
// EXPORT_DATA, IMPORT_DATA, ...). Some tenants vary the param spelling — try
// both lower and camel-case as a fallback.
// Get a rule's job-definition info — includes RTPs (Runtime Prompts).
// Returns { name, jobId, parameters: [{name, type, dim?, defaultValue}, ...] }
// or { error: "..." } if not found / not registered as a Job Definition.
async function runGetRuleInfo(settings, ruleName) {
  if (!settings || !settings.host || !settings.username || !settings.password) {
    throw new Error("settings (host/username/password) required");
  }
  if (!ruleName) throw new Error("rule_name required");
  const host = String(settings.host).replace(/\/+$/, "");
  const app = settings.appName || "NetSuite";
  const url = `${host}/HyperionPlanning/rest/v3/applications/${encodeURIComponent(app)}/jobdefinitions?jobType=RULES`;
  const res = await fetch(url, {
    method: "GET",
    headers: {
      "Authorization": basicAuth(settings.username, settings.password),
      "Accept": "application/json"
    }
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    return { ok: false, error: `Planning REST ${res.status}: ${text.slice(0, 200)}` };
  }
  const data = await res.json();
  const items = data.items || data.jobDefinitions || [];
  const lcName = ruleName.toLowerCase();
  const found = items.find(it => (it.jobName || it.name || "").toLowerCase() === lcName);
  if (!found) {
    return {
      ok: false,
      error: `Rule "${ruleName}" is not registered as a Job Definition. ` +
             `It may be a Calc Manager rule that wasn't added to Application → Jobs. ` +
             `Available registered job rules: ${items.length}.`,
      registeredCount: items.length
    };
  }
  // Each rule's RTPs come either inline or via a separate fetch.
  const params = found.parameters || found.runtimePrompts || found.prompts || [];
  return {
    ok: true,
    name: found.jobName || found.name,
    jobId: found.jobId || found.id,
    parameters: params.map(p => ({
      name: p.name || p.promptName || p.parameterName,
      type: p.type || p.promptType || p.dataType || "member",
      dim: p.dimensionName || p.dim || null,
      defaultValue: p.defaultValue || p.value || null,
      promptText: p.displayName || p.promptText || p.description || null
    }))
  };
}

// Execute a business rule via Planning REST `/jobs` endpoint. Cube name is
// auto-resolved from the tenant KB (preferred) or guessed from the rule's
// own metadata. Returns { jobId, status, message }.
async function runRunRule(settings, ruleName, opts) {
  if (!settings || !settings.host || !settings.username || !settings.password) {
    throw new Error("settings (host/username/password) required");
  }
  if (!ruleName) throw new Error("rule_name required");
  const tkb = (opts && opts.tenantKb) || ((typeof EMBED_TENANT_KB !== "undefined" && EMBED_TENANT_KB) ? EMBED_TENANT_KB : null);
  const kbRules = (tkb && Array.isArray(tkb.rules)) ? tkb.rules : [];
  const r = kbRules.find(x => (x.name || "").toLowerCase() === ruleName.toLowerCase());
  const cube = (opts && opts.cube) || (r && r.cube) || null;
  const host = String(settings.host).replace(/\/+$/, "");
  const app = settings.appName || "NetSuite";
  const url = `${host}/HyperionPlanning/rest/v3/applications/${encodeURIComponent(app)}/jobs`;
  // Planning REST job submit — NO `cubeName` field (that's an EPM Automate
  // CLI param, not REST). The cube is implicit in the rule definition.
  // RTPs (runtime prompts) go in `parameters` if the rule needs them.
  const body = {
    jobType: "RULES",
    jobName: ruleName,
  };
  if (opts && opts.parameters && typeof opts.parameters === "object") {
    body.parameters = opts.parameters;
  }
  const res = await fetch(url, {
    method: "POST",
    headers: {
      "Authorization": basicAuth(settings.username, settings.password),
      "Content-Type": "application/json",
      "Accept": "application/json"
    },
    body: JSON.stringify(body)
  });
  const text = await res.text();
  let data = null;
  try { data = JSON.parse(text); } catch (_) {}
  if (!res.ok) {
    const msg = (data && (data.detail || data.message || data.error)) || text.slice(0, 300);
    return { ok: false, status: res.status, error: msg };
  }
  return {
    ok: true,
    jobId: data && (data.jobId || data.jobID || data.id),
    status: data && (data.descriptiveStatus || data.status),
    message: data && (data.detail || data.message) || "submitted",
    raw: data
  };
}

async function runDiscoverRules(settings) {
  const tries = [
    "/jobdefinitions?jobtype=RULES",
    "/jobdefinitions?jobType=RULES",
    "/jobdefinitions"
  ];
  let lastErr = null;
  for (const p of tries) {
    try {
      const data = await nspbGet(settings, p);
      const items = data.items || data.jobDefinitions || data.jobDefinitionList || [];
      if (items.length > 0) console.log("discover-rules sample item keys:", JSON.stringify(Object.keys(items[0])), "sample:", JSON.stringify(items[0]).slice(0, 400));
      const rules = [];
      for (const it of items) {
        const jt = it.jobType || it.type || it.jobtype || "";
        if (jt && !/RULE/i.test(jt)) continue;
        // Oracle Planning often stores name/planType inside parameters[]
        const params = {};
        if (Array.isArray(it.parameters)) {
          for (const p of it.parameters) {
            if (p && p.name) params[String(p.name).toLowerCase()] = p.value != null ? String(p.value) : "";
          }
        }
        const name = it.jobName || it.jobDefinitionName || it.name || it.jobDefinitionId ||
                     params.jobname || params.jobdefinitionname || params.name ||
                     params.rulename || it.id || it.displayName || "";
        const cube = it.planType || it.cube || it.planTypeName || it.cubeName || it.plantype ||
                     params.plantype || params.cube || params.plantypename || "";
        rules.push({ name, jobType: jt, cube, description: it.description || "" });
      }
      // Enrich with descriptions from embedded LCM-derived KB (REST API doesn't return them)
      try {
        const tkb = (typeof EMBED_TENANT_KB !== "undefined" && EMBED_TENANT_KB) ? EMBED_TENANT_KB : null;
        const kbRules = (tkb && Array.isArray(tkb.rules)) ? tkb.rules : [];
        if (kbRules.length) {
          const byName = new Map(kbRules.map(r => [String(r.name || "").trim().toLowerCase(), r]));
          for (const r of rules) {
            if (r.description) continue;
            const hit = byName.get(String(r.name || "").trim().toLowerCase());
            if (hit && hit.description) r.description = hit.description;
          }
        }
      } catch (e) { console.log("discover-rules KB enrich failed:", e && e.message); }
      return { loadedAt: Date.now(), rules };
    } catch (e) {
      lastErr = e;
      console.log("discover-rules path failed:", p, e && e.message);
    }
  }
  return { loadedAt: Date.now(), rules: [], error: String(lastErr && lastErr.message || lastErr) };
}

// ── Job-history discovery ───────────────────────────────────────────────────
// Three sources, in priority order:
//   1) SmartView XML protocol — `req_EnumJobs`. Verified working via Smart View
//      Diagnostics XMLs. Returns rich metadata (jobID, jobName, jobType,
//      runStatus, startTime/endTime as compact "YYYYMMDDHHMMSS" strings),
//      plus type-code → display-label mapping in the same response.
//   2) Planning REST — `/jobs?limit=N`. Fallback for tenants where SV jobs is
//      restricted; usually returns less detail and may be empty.
//   3) FDMEE/AIF REST — `/aif/rest/V1/jobs?limit=N`. Data Management ("data
//      exchange") integrations, batches, pipelines. Different base path —
//      composed directly because nspbGet() prefixes /HyperionPlanning/...
async function runDiscoverJobs(settings) {
  const limit = 50;
  const errors = {};
  const merged = [];

  // Compact "20260424040038" → ISO "2026-04-24T04:00:38Z" so the client can
  // sort and Date-parse uniformly across all three sources.
  const compactToIso = (s) => {
    if (!s || !/^\d{14}$/.test(String(s))) return null;
    const t = String(s);
    return `${t.slice(0,4)}-${t.slice(4,6)}-${t.slice(6,8)}T${t.slice(8,10)}:${t.slice(10,12)}:${t.slice(12,14)}Z`;
  };

  // 1) SmartView req_EnumJobs.
  try {
    const sID = await smartViewOpenApp(settings);
    const xml = `<req_EnumJobs><sID>${svEscape(sID)}</sID>` +
                `<filters><userName></userName><jobType></jobType><runStatus></runStatus>` +
                `<startTime></startTime><endTime></endTime><jobName></jobName></filters>` +
                `</req_EnumJobs>`;
    const resp = await svPost(settings, xml);
    if (svSessionExpired(resp)) {
      const sID2 = await smartViewOpenApp(settings, true);
      const retry = await svPost(settings, xml.replace(/<sID>[\s\S]*?<\/sID>/, `<sID>${svEscape(sID2)}</sID>`));
      // reuse the retry response below
      parseSvJobs(retry, compactToIso, merged);
    } else {
      parseSvJobs(resp, compactToIso, merged);
    }
  } catch (e) {
    errors.sv = String(e && e.message || e);
  }

  // 2) Planning REST — only if SV returned nothing (rare).
  if (!merged.length) {
    try {
      const data = await nspbGet(settings, `/jobs?limit=${limit}`);
      const items = data.items || data.jobInstances || [];
      for (const j of items) {
        merged.push({
          source: "planning",
          id:      j.jobId || j.id || "",
          name:    j.jobName || j.name || "",
          jobType: j.jobType || "",
          jobTypeLabel: j.jobType || "",
          cube:    j.planType || j.planningType || "",
          status:  j.descriptiveStatus || j.status || "",
          startTime: j.startTime || j.submittedTime || null,
          endTime:   j.endTime || j.completedTime || null,
          errorMessage: j.errorMessage || j.errorMsg || ""
        });
      }
    } catch (e) {
      errors.planningRest = String(e && e.message || e);
    }
  }

  // 3) DM (FDMEE) jobs. Primary endpoint is `/aif/ui/model/job/process`
  //    (verified via NSPB DevTools — the Process Details page hits this).
  //    Fallback to `/aif/rest/V1/jobs` for older/different tenants.
  const host = String(settings.host).replace(/\/+$/, "");
  const dmAuth = basicAuth(settings.username, settings.password);
  const dmTries = [
    `${host}/aif/ui/model/job/process?limit=${limit}`,
    `${host}/aif/rest/V1/jobs?limit=${limit}`
  ];
  let dmDone = false;
  for (const url of dmTries) {
    if (dmDone) break;
    try {
      const dmResp = await fetch(url, {
        method: "GET",
        headers: { "Authorization": dmAuth, "Accept": "application/json" }
      });
      const txt = await dmResp.text();
      if (!dmResp.ok) {
        errors[`dm@${url.replace(host, "")}`] = `${dmResp.status}: ${txt.slice(0, 100)}`;
        continue;
      }
      const data = txt ? JSON.parse(txt) : {};
      const items = data.items || data.jobs || data.processes || data.list || [];
      if (items.length) dmDone = true;
      for (const j of items) {
        // Field aliases differ between /aif/ui/model/job/process (legacy, UI)
        // and /aif/rest/V1/jobs (REST V1, the one that works under Basic Auth).
        // REST V1 returns jobStatus/processType/executedBy; legacy UI uses
        // processStatus/category/userName. Cover both.
        merged.push({
          source: "dm",
          id:      j.processId || j.jobId || j.id || "",
          name:    j.processName || j.jobName || j.integrationName || j.name || j.processType || "",
          jobType: j.processType || j.category || j.type || "DM",
          jobTypeLabel: j.processType || j.category || "Data Management",
          cube:    j.targetApp || j.targetApplication || "",
          status:  j.jobStatus || j.processStatus || j.status || j.statusText || "",
          startTime: j.startTime || j.executionStart || j.startedAt || null,
          endTime:   j.endTime || j.executionEnd || j.completedAt || null,
          errorMessage: j.errorCount ? `${j.errorCount} errors` : (j.errorMessage || ""),
          period:   j.period || "",
          userName: j.executedBy || j.userName || j.user || j.submittedBy || "",
          logFile:  j.logFileName || j.logFile || ""
        });
      }
    } catch (e) {
      errors[`dm@${url.replace(host, "")}`] = String(e && e.message || e);
    }
  }

  // Sort newest first; keep up to 80 to avoid bloating /api/chat body.
  merged.sort((a, b) => {
    const ta = a.startTime ? new Date(a.startTime).getTime() : 0;
    const tb = b.startTime ? new Date(b.startTime).getTime() : 0;
    return tb - ta;
  });
  const jobs = merged.slice(0, 80);

  if (!jobs.length) {
    const firstErr = Object.values(errors)[0] || "no jobs returned";
    return { loadedAt: Date.now(), jobs: [], error: firstErr };
  }
  return { loadedAt: Date.now(), jobs, partialErrors: Object.keys(errors).length ? errors : undefined };
}

// Parse a <res_EnumJobs> response into the merged jobs array. Uses the
// type-code → display-label map embedded in the response so users see
// "Refresh Database" instead of "cubeRefresh", etc.
function parseSvJobs(xml, compactToIso, merged) {
  // Extract type-code → label map.
  const typeCodes = (xml.match(/<jobTypes>[\s\S]*?<types[^>]*>([^<]*)<\/types>/) || [])[1] || "";
  const typeLabels = (xml.match(/<jobTypes>[\s\S]*?<display[^>]*>([^<]*)<\/display>/) || [])[1] || "";
  const codes = typeCodes.split("|");
  const labels = typeLabels.split("|");
  const typeMap = {};
  for (let i = 0; i < codes.length; i++) typeMap[codes[i]] = svUnescape(labels[i] || codes[i]);

  // Same for status.
  const statusCodes  = (xml.match(/<jobStatus>[\s\S]*?<status[^>]*>([^<]*)<\/status>/) || [])[1] || "";
  const statusLabels = (xml.match(/<jobStatus>[\s\S]*?<display[^>]*>([^<]*)<\/display>/) || [])[1] || "";
  const statusMap = {};
  const sCodes  = statusCodes.split("|");
  const sLabels = statusLabels.split("|");
  for (let i = 0; i < sCodes.length; i++) statusMap[sCodes[i]] = svUnescape(sLabels[i] || sCodes[i]);

  // Each <job .../> is a self-closing tag with attributes.
  const re = /<job\s+([^/>]+)\/>/g;
  let m;
  while ((m = re.exec(xml))) {
    const attrs = m[1];
    const get = (key) => {
      const r = attrs.match(new RegExp(`${key}="([^"]*)"`));
      return r ? r[1] : "";
    };
    const code = get("jobType");
    const stCode = get("runStatus");
    merged.push({
      source: "planning",
      id:      get("jobID"),
      name:    svUnescape(get("jobName")),
      jobType: code,
      jobTypeLabel: typeMap[code] || code,
      cube:    "",
      status:  statusMap[stCode] || stCode,
      statusCode: stCode,
      startTime: compactToIso(get("startTime")) || svUnescape(get("startTimeUser")),
      endTime:   compactToIso(get("endTime"))   || svUnescape(get("endTimeUser")),
      userName:  svUnescape(get("userName")),
      errorMessage: ""
    });
  }
}

// ── Integrations & pipelines discovery (AIF UI) ─────────────────────────────
// Endpoints captured from NSPB DevTools when navigating to Data Management →
// Data Integration. Returns the list of Data Rules (source→target movements)
// and Pipelines (sequences of rules). Both are read-only inventory.
async function runDiscoverIntegrations(settings) {
  const host = String(settings.host).replace(/\/+$/, "");
  const auth = basicAuth(settings.username, settings.password);
  const out = { loadedAt: Date.now(), integrations: [], pipelines: [], errors: {} };

  const fetchJson = async (urlPath) => {
    const r = await fetch(host + urlPath, {
      method: "GET",
      headers: { "Authorization": auth, "Accept": "application/json" }
    });
    const t = await r.text();
    if (!r.ok) throw new Error(`${r.status} ${urlPath}: ${t.slice(0, 100)}`);
    return t ? JSON.parse(t) : {};
  };

  // Data rules (integrations) live ONLY under /aif/ui/model/integration/datarule
  // which requires session auth — Basic Auth from a Worker returns 401. As a
  // partial workaround, expose recent DATARULE-typed jobs via /aif/rest/V1/jobs
  // so the user at least sees which integrations have run lately + their status.
  try {
    const data = await fetchJson("/aif/rest/V1/jobs?type=DATARULE&limit=50");
    const items = data.items || data.jobs || (Array.isArray(data) ? data : []);
    const seen = new Set();
    for (const it of items) {
      const name = it.processName || it.jobName || it.integrationName || it.processType || "";
      if (!name || seen.has(name)) continue;
      seen.add(name);
      out.integrations.push({
        name,
        sourceApp:   it.sourceApplication || it.sourceApp || "",
        targetApp:   it.targetApplication || it.targetApp || "",
        category:    it.category || "DATARULE",
        period:      it.period || "",
        lastRun:     it.startTime || it.executionStart || null,
        status:      it.jobStatus || it.status || "",
        description: it.description || "(name inferred from recent job runs — full integration list requires NSPB UI)"
      });
    }
  } catch (e) {
    out.errors.datarule = String(e && e.message || e);
  }

  // Pipelines list: /aif/rest/V1/pipeline works under Basic Auth (singular path).
  try {
    const data = await fetchJson("/aif/rest/V1/pipeline");
    const items = data.items || data.pipelines || data.response || data.list || (Array.isArray(data) ? data : []);
    for (const it of items) {
      out.pipelines.push({
        name:        it.name || it.pipelineName || "",
        description: it.displayName || it.description || "",
        stageCount:  Array.isArray(it.stages) ? it.stages.length : (it.stageCount || 0),
        lastRun:     it.lastRun || it.lastUpdate || it.lastRunTime || null,
        status:      it.status || ""
      });
    }
  } catch (e) {
    out.errors.pipeline = String(e && e.message || e);
  }
  return out;
}

// ── App-config auto-discovery (cubes / dims / defaults / period / years) ──
// Replaces the hardcoded CLIENT_CONFIG.cubes/cubeDims/cubeDimDefaults so the
// add-in works on any NSPB tenant without code edits. Uses Planning REST
// (Basic-Auth-friendly): /plantypes, /plantypes/{cube}/dimensions,
// /dimensions/{dim}/members/{dim}?descendants=Children. The client persists
// the result and ships it on every /api/chat — when present the worker uses
// it instead of CLIENT_CONFIG so a fresh tenant gets its own structure.
async function runDiscoverAppConfig(settings) {
  const out = {
    appName: settings.appName || "NetSuite",
    cubes: [],
    mainCube: null,
    cubeDims: {},
    cubeDimDefaults: {},
    periodMembers: [],
    years: [],
    scenarios: [],
    detectedAt: new Date().toISOString(),
    errors: {}
  };
  // 1. List cubes / plan types
  try {
    const data = await nspbGet(settings, "/plantypes");
    const items = data.items || [];
    out.cubes = items.map(p => p.cubeName || p.planTypeName).filter(Boolean);
    // mainCube = the one with the largest dim count (typically the financial cube).
    let maxDims = -1;
    for (const p of items) {
      const n = p.numDimensions || 0;
      if (n > maxDims) { maxDims = n; out.mainCube = p.cubeName || p.planTypeName; }
    }
    if (!out.mainCube && out.cubes.length) out.mainCube = out.cubes[0];
  } catch (e) {
    out.errors.plantypes = String(e.message || e);
  }

  // 2. Per cube — dim list. Dim's root member is the dim name itself in
  //    Hyperion (always valid). We use that as the default — guarantees
  //    build_adhoc grids never fail on missing-dim issues. Specific defaults
  //    (Actual scenario, FY24, etc.) the user supplies in the query or
  //    Gemini infers via find_member.
  for (const cube of out.cubes) {
    try {
      const data = await nspbGet(settings, `/plantypes/${encodeURIComponent(cube)}/dimensions`);
      const items = data.items || [];
      out.cubeDims[cube] = items.map(d => d.name).filter(Boolean);
      const defaults = {};
      for (const d of items) {
        if (d.name) defaults[d.name] = d.name;  // dim root member
      }
      out.cubeDimDefaults[cube] = defaults;
    } catch (e) {
      out.errors[`dims/${cube}`] = String(e.message || e);
    }
  }

  // 3. Period structure — children of root return aggregation buckets
  //    (Y-T-D, M-T-D, BegBalance, TotalYear) on this tenant. Real month
  //    members (TP1-12 / Jan-Dec / Ene-Dic) are the descendants of
  //    "TotalYear" (or whichever child has the most descendants — that's
  //    the "all months" parent by convention). We capture BOTH the top
  //    level (for context) and the resolved monthMembers (for "by month"
  //    column packs in buildSystemPrompt).
  try {
    const top = await nspbGet(settings, `/dimensions/Period/members/Period?descendants=Children`);
    const topKids = top.children || [];
    out.periodMembers = topKids.map(c => c.name).filter(Boolean);

    // Find the child with the most descendants — usually TotalYear or "All
    // Periods". Fall back to literal "TotalYear" / "YearTotal" name match.
    const namedYearParent = topKids.find(c =>
      ["TotalYear", "YearTotal", "All Periods", "Year"].includes(c.name)
    );
    let yearParentName = namedYearParent && namedYearParent.name;
    if (!yearParentName && topKids.length) {
      // Pick whichever isn't a -T-D aggregation; TotalYear is the canonical
      // ancestor of months.
      const candidate = topKids.find(c => !/(T-D|TrendValues|BegBalance)/.test(c.name || ""));
      if (candidate) yearParentName = candidate.name;
    }
    if (yearParentName) {
      try {
        const desc = await nspbGet(settings,
          `/dimensions/Period/members/${encodeURIComponent(yearParentName)}?descendants=Descendants`);
        // Walk the tree, collect ALL leaf members (no children). Those are
        // months. If hierarchy is Year > Q1..Q4 > Months, we get months.
        // If it's Year > Months directly, we get months.
        const leaves = [];
        const walk = (n) => {
          if (!n) return;
          if (Array.isArray(n.children) && n.children.length) {
            for (const c of n.children) walk(c);
          } else if (n.name) {
            leaves.push(n.name);
          }
        };
        walk(desc);
        out.monthMembers = leaves;
        out.yearTotalMember = yearParentName;
      } catch (e) {
        out.errors.periodMonths = String(e.message || e);
      }
    }
  } catch (e) {
    out.errors.period = String(e.message || e);
  }

  // 4. Years populated. Years usually has "All Years" → FY14, FY15, ... so
  //    we go one level deeper. Some tenants may have YYYY (2024) instead.
  try {
    const data = await nspbGet(settings, `/dimensions/Years/members/Years?descendants=Children`);
    const kids = data.children || [];
    const collected = [];
    for (const c of kids) {
      // If immediate child is "All Years" or similar group, take ITS children.
      if (Array.isArray(c.children) && c.children.length) {
        for (const cc of c.children) if (cc.name) collected.push(cc.name);
      } else if (c.name) {
        collected.push(c.name);
      }
    }
    // Filter to FY-style or 4-digit-year-style names; sort newest first.
    out.years = collected
      .filter(n => /^FY\d{2,4}$|^\d{4}$/.test(n))
      .sort()
      .reverse();
    if (!out.years.length) out.years = collected;  // fallback if naming is exotic
  } catch (e) {
    out.errors.years = String(e.message || e);
  }

  // 5. Scenario children — Actual/Budget/Forecast variants by name.
  try {
    const data = await nspbGet(settings, `/dimensions/Scenario/members/Scenario?descendants=Children`);
    const kids = data.children || [];
    out.scenarios = kids.map(c => c.name).filter(Boolean);
  } catch (e) {
    out.errors.scenarios = String(e.message || e);
  }

  return out;
}

// ── DM Applications + Source Systems discovery ──────────────────────────────
// `/aif/ui/model/integration/application?type=ALL` lists every application
// registered in Data Management (both source apps like NSPB itself, and
// target apps like NetSuite GL files). `/sourcesystems` is the source-system
// registry (e.g. file-based, EPM, ERP). Together they describe the WHERE of
// data movement; integrations (Data Rules) describe the HOW.
async function runDiscoverApplications(settings) {
  const host = String(settings.host).replace(/\/+$/, "");
  const auth = basicAuth(settings.username, settings.password);
  const fetchJson = async (u) => {
    const r = await fetch(host + u, {
      method: "GET",
      headers: { "Authorization": auth, "Accept": "application/json" }
    });
    const t = await r.text();
    if (!r.ok) throw new Error(`${r.status} ${u}: ${t.slice(0, 80)}`);
    return t ? JSON.parse(t) : {};
  };

  const out = { loadedAt: Date.now(), applications: [], sourceSystems: [], errors: {} };

  try {
    // Use the V1 REST endpoint — Basic-Auth-friendly. The UI-model variant
    // (/aif/ui/model/integration/application?type=ALL) requires session auth.
    const data = await fetchJson("/aif/rest/V1/applications");
    const items = data.items || data.applications || data.list || (Array.isArray(data) ? data : []);
    for (const a of items) {
      out.applications.push({
        id:         a.applicationId || a.id || a.appId || "",
        name:       a.applicationName || a.name || "",
        type:       a.applicationType || a.type || "",
        category:   a.applicationSubType || a.category || a.applicationClass || "",
        targetClass:a.targetAppName || a.targetApplicationClass || "",
        description:a.description || ""
      });
    }
  } catch (e) {
    out.errors.applications = String(e.message || e);
  }

  // Source systems endpoint (/aif/ui/model/sourcesystems) returns 401 with
  // Basic Auth — no V1 REST equivalent exists for this tenant. Emit an empty
  // list with a note so the inventory sheet still renders cleanly.
  out.errors.sourceSystems = "endpoint requires NSPB session auth (Basic Auth gives 401)";
  return out;
}

// ── Currencies ───────────────────────────────────────────────────────────────
async function runDiscoverCurrencies(settings) {
  try {
    const data = await nspbGet(settings, "/currencies");
    const items = data.items || data.currencies || (Array.isArray(data) ? data : []);
    const currencies = items.map(c => ({
      code:      c.currencyCode  || c.code  || c.name || "",
      name:      c.currencyName  || c.description || c.displayName || "",
      symbol:    c.symbol        || "",
      scale:     c.scale         || c.precision  || "",
      reporting: c.reportingCurrency || c.isReporting || ""
    }));
    return { loadedAt: Date.now(), currencies };
  } catch (e) {
    return { loadedAt: Date.now(), currencies: [], error: String(e && e.message || e) };
  }
}

// ── Versions (Scenario → Version hierarchy) ──────────────────────────────────
async function runDiscoverVersions(settings) {
  const out = { loadedAt: Date.now(), versions: [], errors: {} };
  try {
    const data = await nspbGet(settings, "/dimensions/Version/members/Version?descendants=Children");
    const items = data.items || data.memberList || data.members || [];
    for (const it of items) {
      out.versions.push({
        name:        it.memberName  || it.name  || "",
        description: it.alias       || it.description || "",
        type:        it.versionType || it.type  || "",
        enabled:     it.enabled !== false
      });
    }
  } catch (e) {
    out.errors.version = String(e && e.message || e);
  }
  return out;
}

// ── Currently running Planning jobs ──────────────────────────────────────────
async function runDiscoverRunningJobs(settings) {
  const out = { loadedAt: Date.now(), runningJobs: [], errors: {} };
  for (const status of ["PROCESSING", "RUNNING", "PENDING"]) {
    try {
      const data = await nspbGet(settings, `/jobs?status=${status}&limit=20`);
      const items = data.items || data.jobInstances || [];
      for (const it of items) {
        out.runningJobs.push({
          id:        it.jobId     || it.id        || "",
          name:      it.jobName   || it.name      || "",
          type:      it.jobType   || it.type      || "",
          status:    it.status    || status,
          startTime: it.startTime || it.submittedTime || "",
          user:      it.executedBy|| it.userName  || "",
          cube:      it.planType  || it.cube      || ""
        });
      }
    } catch (e) {
      out.errors[status] = String(e && e.message || e);
    }
  }
  return out;
}

// ── DM Categories (scenario→period mapping buckets in FDMEE) ─────────────────
async function runDiscoverDMCategories(settings) {
  const host = String(settings.host).replace(/\/+$/, "");
  const auth = basicAuth(settings.username, settings.password);
  const out  = { loadedAt: Date.now(), categories: [], errors: {} };
  for (const p of ["/aif/rest/V1/categories", "/aif/rest/V1/category"]) {
    try {
      const r = await fetch(host + p, { headers: { "Authorization": auth, "Accept": "application/json" } });
      const t = await r.text();
      if (!r.ok) { out.errors[p] = `${r.status}: ${t.slice(0, 80)}`; continue; }
      const data  = t ? JSON.parse(t) : {};
      const items = data.items || data.categories || data.list || (Array.isArray(data) ? data : []);
      for (const c of items) {
        out.categories.push({
          name:        c.categoryName || c.name     || c.category || "",
          description: c.description  || "",
          frequency:   c.frequency    || c.categoryFrequency || "",
          startPeriod: c.startPeriod  || "",
          endPeriod:   c.endPeriod    || ""
        });
      }
      if (out.categories.length) break;
    } catch (e) { out.errors[p] = String(e && e.message || e); }
  }
  return out;
}

// ── DM Locations ─────────────────────────────────────────────────────────────
async function runDiscoverLocationsV1(settings) {
  const host = String(settings.host).replace(/\/+$/, "");
  const auth = basicAuth(settings.username, settings.password);
  const out  = { loadedAt: Date.now(), locations: [], errors: {} };
  for (const p of ["/aif/rest/V1/locations", "/aif/rest/V1/location"]) {
    try {
      const r = await fetch(host + p, { headers: { "Authorization": auth, "Accept": "application/json" } });
      const t = await r.text();
      if (!r.ok) { out.errors[p] = `${r.status}: ${t.slice(0, 80)}`; continue; }
      const data  = t ? JSON.parse(t) : {};
      const items = data.items || data.locations || data.list || (Array.isArray(data) ? data : []);
      for (const loc of items) {
        out.locations.push({
          name:      loc.name        || loc.locationName || "",
          targetApp: loc.targetApp   || loc.targetApplicationName || "",
          sourceApp: loc.sourceApp   || loc.sourceApplicationName || "",
          currency:  loc.currency    || loc.functionalCurrency    || "",
          category:  loc.category    || "",
          description: loc.description || ""
        });
      }
      if (out.locations.length) break;
    } catch (e) { out.errors[p] = String(e && e.message || e); }
  }
  if (!out.locations.length) out.note = "Locations may require session auth — not available via Basic Auth on this tenant";
  return out;
}

// ── Period mappings — try V1 REST (Basic Auth) ────────────────────────────────
async function runDiscoverPeriodMappingsV1(settings) {
  const host = String(settings.host).replace(/\/+$/, "");
  const auth = basicAuth(settings.username, settings.password);
  const out  = { loadedAt: Date.now(), mappings: [], errors: {} };
  for (const p of ["/aif/rest/V1/periodmappings", "/aif/rest/V1/periodmapping", "/aif/rest/V1/periods"]) {
    try {
      const r = await fetch(host + p, { headers: { "Authorization": auth, "Accept": "application/json" } });
      const t = await r.text();
      if (!r.ok) { out.errors[p] = `${r.status}: ${t.slice(0, 80)}`; continue; }
      const data  = t ? JSON.parse(t) : {};
      const items = data.items || data.mappings || data.list || (Array.isArray(data) ? data : []);
      for (const m of items) {
        out.mappings.push({
          source:   m.sourcePeriod || m.source   || m.period || "",
          target:   m.targetPeriod || m.target   || "",
          year:     m.year         || "",
          category: m.category     || ""
        });
      }
      if (out.mappings.length) break;
    } catch (e) { out.errors[p] = String(e && e.message || e); }
  }
  if (!out.mappings.length) out.note = "Period mappings require session auth — V1 REST endpoints returned nothing on this tenant";
  return out;
}

// ── Period mapping discovery ────────────────────────────────────────────────
async function runDiscoverPeriodMappings(settings) {
  // /aif/ui/model/periodmapping/global requires NSPB session auth (Basic Auth
  // gives 401 from a Worker). No /aif/rest/V1/* equivalent exposed by Oracle.
  // Returning empty + a note so the inventory sheet renders cleanly with an
  // explanation instead of crashing.
  return {
    loadedAt: Date.now(),
    mappings: [],
    error: "endpoint requires NSPB session auth (Basic Auth gives 401) — view in NSPB UI: Application → Data Exchange → Period Mapping"
  };
}

// ── Maintenance window ──────────────────────────────────────────────────────
// /interop/epmuirest/v2/maintenance/* requires NSPB session auth (401 with
// Basic Auth from a Worker). Returned with an empty/error response so the
// client init() doesn't show a noisy banner — just silently no-ops.
async function runGetMaintenanceWindow(settings) {
  return {
    loadedAt: Date.now(),
    error: "endpoint requires NSPB session auth (Basic Auth gives 401)"
  };
}

// ── Navigation flow discovery ──────────────────────────────────────────────
// Walks the cluster→card→tab tree from /flows/2/nodes recursively. Each leaf
// is typically a form, dashboard, or report. We DON'T fetch /pageparams for
// every leaf (would blow Cloudflare's 50 sub-request limit) — that's deferred
// to on-demand resolution when the user opens a specific node.
async function runDiscoverNavigation(settings) {
  // /HyperionPlanning/efsvbuirest/epmcommon/v2/internal/vbshell/flows/2/nodes
  // requires NSPB session auth — Basic Auth from a Worker returns 401. There
  // is no documented /aif/rest/V1/* equivalent for the navigation tree. The
  // canonical surface is the NSPB UI itself.
  return {
    loadedAt: Date.now(),
    nodes: [],
    errors: [{ err: "endpoint requires NSPB session auth (Basic Auth gives 401) — navigate the menu in NSPB UI" }]
  };
}

// ── Substitution-variable discovery ─────────────────────────────────────────
// Endpoint mirrored from MCP3 (EPMClient.gs:1307): list app-scope sub vars.
// Returns name + value + scope (planType or "Global"). Read-only — no setter.
async function runDiscoverVariables(settings) {
  try {
    const data = await nspbGet(settings, "/substitutionvariables");
    const items = data.items || [];
    const variables = items.map(v => ({
      name:  v.name || v.variable || "",
      value: v.value != null ? String(v.value) : "",
      scope: v.planningType || v.cube || "Global"
    })).filter(v => v.name);
    return { loadedAt: Date.now(), variables };
  } catch (e) {
    return { loadedAt: Date.now(), variables: [], error: String(e && e.message || e) };
  }
}

// ── Form discovery ─────────────────────────────────────────────────────────
// Primary path: SmartView XML wire protocol with `req_ListDocuments` and
// recursive folder walk from "/". This is what the Smart View add-in itself
// uses (verified via Smart View Diagnostics in C:\Users\...\AppData\Roaming\
// Oracle\SmartView\Diagnostics — req/res XMLs are dumped per session).
// Forms aren't reliably exposed via REST in NSPB (probed ~10 paths, all 404),
// so REST is now the FALLBACK for tenants where SV is restricted.
// Heuristic input/review classifier. Triggered at Discover time, no extra
// HTTP calls. Three signals merged:
//   1) Type code from req_ListDocuments (8 = data form, 40 = composite/dashboard)
//   2) Name keywords (English + Spanish)
//   3) Description keywords
// Returns "input" | "review" | "unknown". Not perfect, but accurate enough
// for filtering / coloring at scale.
function classifyForm(form) {
  const name = String(form.name || "").toLowerCase();
  const desc = String(form.description || "").toLowerCase();
  const text = name + " " + desc;
  // Type 40 is typically composite/dashboard → review.
  if (form.type === "40") return "review";
  // Strong review signals.
  if (/\b(review|summary|report|dashboard|analysis|view|trend|variance|rollup|consolidat|kpi)\b/.test(text)) return "review";
  // Strong input signals.
  if (/\b(entry|input|adjust|edit|manage|load|import|export|setup|set ?up|config|update|enter|maintain|carga|edicion|edición|alta|modificar)\b/.test(text)) return "input";
  // Plan/forecast/budget without "review" → input by default.
  if (/\b(plan|forecast|budget|target|allocation|allocate)\b/.test(text)) return "input";
  // Type 8 default → input (most common data form).
  if (form.type === "8") return "input";
  return "unknown";
}

// Primary forms endpoint: /HyperionPlanning/efsvbuirest/v3/internal/applications/{app}/objects.
// This is the same call the NSPB web UI makes when the user navigates to
// "Forms" — captured via DevTools Network tab. It's a generic "objects" API
// with Mongo-style filters: {objectType, subType, hidden, parentId}.
// Returns rich metadata including subType (Simple / Ad Hoc / Smart / Exchange
// Rate Form) which we use for accurate input/review classification.
async function runDiscoverFormsViaObjectsApi(settings) {
  const filter = {
    "$or": [
      {
        "objectType": "Form",
        "subType":    { "$in": ["Simple", "Ad Hoc", "Smart", "Exchange Rate Form"] },
        "hidden":     false
      },
      { "objectType": "Folder" }
    ]
  };
  const app = encodeURIComponent(settings.appName || "NetSuite");
  const q = encodeURIComponent(JSON.stringify(filter));
  const url = String(settings.host).replace(/\/+$/, "") +
              `/HyperionPlanning/efsvbuirest/v3/internal/applications/${app}/objects?q=${q}&limit=2000&offset=0`;
  const resp = await fetch(url, {
    method: "GET",
    headers: {
      "Authorization": basicAuth(settings.username, settings.password),
      "Accept": "application/json"
    }
  });
  const text = await resp.text();
  if (!resp.ok) throw new Error(`objectsApi ${resp.status}: ${text.slice(0, 160)}`);
  const data = text ? JSON.parse(text) : {};
  const items = data.items || data.objects || [];

  // Separate folders and forms; build folder id→{name,parentId} map; resolve
  // each form's full path by walking the parent chain.
  const folderMap = {};
  const formItems = [];
  for (const it of items) {
    if (it.objectType === "Folder") folderMap[it.id] = { name: it.name || "", parentId: it.parentId };
    else if (it.objectType === "Form") formItems.push(it);
  }
  const buildPath = (parentId) => {
    const parts = [];
    let cur = parentId, safety = 12;
    while (cur && folderMap[cur] && safety-- > 0) {
      parts.unshift(folderMap[cur].name);
      cur = folderMap[cur].parentId;
    }
    return parts.length ? "/" + parts.join("/") : "/";
  };
  const subTypeCategory = {
    "Simple":              "input",
    "Ad Hoc":              "review",
    "Smart":               "review",
    "Exchange Rate Form":  "input",
    "Composite":           "review",
    "Dashboard":           "review"
  };
  // Some tenants put the form variant under different keys; probe all of them.
  const subTypeOf = (f) => f.subType || f.objectSubType || f.formSubType ||
                            f.formType || f.type || f.kind || "";
  // Diagnostic: if the FIRST form has no recognizable subType, log its keys
  // so we can spot the field name on the next deploy.
  if (formItems.length && !subTypeOf(formItems[0])) {
    console.log("discover-forms: first item has no subType; keys =",
                Object.keys(formItems[0]).slice(0, 30));
  }
  const forms = formItems.map(f => {
    const subType = subTypeOf(f);
    const formRecord = {
      name:        f.name || "",
      path:        buildPath(f.parentId),
      cube:        f.cube || f.planType || "",
      description: f.description || "",
      type:        subType,
      formId:      f.id || f.formId || "",
      subType
    };
    // Prefer subType-based category; if subType missing/unknown, fall back to
    // the heuristic that classifies by name + description keywords.
    formRecord.category = subTypeCategory[subType] ||
                          classifyForm({ name: formRecord.name, type: subType, description: formRecord.description });
    return formRecord;
  }).filter(f => f.name);
  return { loadedAt: Date.now(), forms, source: "objectsApi" };
}

async function runDiscoverForms(settings) {
  // 0. Try the objects API first — that's the modern UI endpoint and gives
  //    us the richest metadata (subType, hidden, parentId for path).
  try {
    const out = await runDiscoverFormsViaObjectsApi(settings);
    if (out.forms && out.forms.length) {
      return out;
    }
  } catch (e) {
    console.log("discover-forms: objectsApi failed, trying SmartView:", e && e.message);
  }

  // 1. Try SmartView protocol second.
  let sID;
  try {
    sID = await smartViewOpenApp(settings);
  } catch (e) {
    // Couldn't even open a session — go straight to REST fallback.
    console.log("discover-forms: SV OpenApplication failed, trying REST:", e && e.message);
    return await runDiscoverFormsViaRest(settings);
  }

  const visited = new Set();
  const allForms = [];
  const allFolders = [];
  const errors = [];
  const MAX_FORMS = 500;
  const MAX_FOLDERS = 200;
  const MAX_DEPTH = 6;

  // Pull a pipe-delimited list out of <tag enc="1">A|B|C</tag> within a body.
  // SmartView returns parallel lists for forms (names, descriptions, planTypes,
  // formsId, types) — caller zips them by index.
  const pickPipe = (block, tag) => {
    const m = block.match(new RegExp(`<${tag}[^>]*>([^<]*)</${tag}>`));
    return m ? m[1].split("|") : [];
  };

  async function walk(folder, depth) {
    if (depth > MAX_DEPTH) return;
    if (visited.has(folder)) return;
    visited.add(folder);
    if (allForms.length >= MAX_FORMS || allFolders.length >= MAX_FOLDERS) return;

    const buildXml = (sid) =>
      `<req_ListDocuments><sID>${svEscape(sid)}</sID>` +
      `<type>all</type><folder>${svEscape(folder)}</folder></req_ListDocuments>`;

    let resp;
    try {
      resp = await svPost(settings, buildXml(sID));
      if (svSessionExpired(resp)) {
        sID = await smartViewOpenApp(settings, true);
        resp = await svPost(settings, buildXml(sID));
      }
    } catch (e) {
      errors.push({ folder, err: String(e && e.message || e) });
      return;
    }

    // <res_Exception> bubbles real Oracle errors back as plain XML — surface
    // them but don't abort the whole walk; some folders may legitimately be
    // ACL-restricted while siblings are readable.
    const exc = resp.match(/<res_Exception[^>]*errcode="([^"]+)"[^>]*>([\s\S]*?)<\/res_Exception>/);
    if (exc) {
      errors.push({ folder, err: `errcode=${exc[1]}: ${exc[2].slice(0, 120)}` });
      return;
    }

    // Subfolders.
    const folderBlock = resp.match(/<folders>([\s\S]*?)<\/folders>/);
    const subfolders = folderBlock
      ? pickPipe(folderBlock[1], "names").map(svUnescape).filter(Boolean)
      : [];
    for (const sub of subfolders) {
      const child = (folder === "/" ? "" : folder) + "/" + sub;
      allFolders.push(child);
    }

    // Forms — parallel pipe-aligned arrays.
    const formsBlock = resp.match(/<forms>([\s\S]*?)<\/forms>/);
    if (formsBlock) {
      const block = formsBlock[1];
      const names = pickPipe(block, "names");
      const descs = pickPipe(block, "descriptions");
      const types = pickPipe(block, "types");
      const planTypes = pickPipe(block, "planTypes");
      const ids   = pickPipe(block, "formsId");
      for (let i = 0; i < names.length; i++) {
        const n = names[i];
        if (!n) continue;
        const form = {
          name: svUnescape(n),
          path: folder,
          cube: planTypes[i] || "",
          description: svUnescape(descs[i] || ""),
          type: types[i] || "",
          formId: ids[i] || ""
        };
        form.category = classifyForm(form);
        allForms.push(form);
        if (allForms.length >= MAX_FORMS) break;
      }
    }

    // Recurse — sequential, not parallel, to keep within Cloudflare's
    // subrequest budget on the free plan (50 max).
    for (const sub of subfolders) {
      const child = (folder === "/" ? "" : folder) + "/" + sub;
      await walk(child, depth + 1);
      if (allForms.length >= MAX_FORMS || allFolders.length >= MAX_FOLDERS) break;
    }
  }

  await walk("/", 0);

  // 2. If SV walk yielded nothing, fall back to REST probe.
  if (!allForms.length) {
    console.log("discover-forms: SV walk found 0 — falling back to REST");
    const restResult = await runDiscoverFormsViaRest(settings);
    if (errors.length && (!restResult.forms || !restResult.forms.length)) {
      restResult.svErrors = errors.slice(0, 5);
    }
    return restResult;
  }

  // De-duplicate by name+cube+path (a form sometimes appears in multiple folders).
  const seen = new Set();
  const forms = allForms.filter(f => {
    const k = f.name + "|" + f.cube + "|" + f.path;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });

  return {
    loadedAt: Date.now(),
    forms,
    folders: allFolders,
    walkedFolders: visited.size,
    walkErrors: errors.length ? errors.slice(0, 5) : undefined
  };
}

// REST-based fallback (formerly the primary). Forms aren't exposed reliably
// via REST in this tenant — kept as a safety net for environments where the
// SV protocol is locked down.
async function runDiscoverFormsViaRest(settings) {
  const cubes = (CLIENT_CONFIG.cubes || []);
  const collected = [];
  const errors = [];   // ordered: [{path, status, snippet}, ...]

  const tryPath = async (p) => {
    try {
      const data = await nspbGet(settings, p);
      const items = data.items || data.forms || data.dataForms || [];
      for (const it of items) {
        const name = it.name || it.formName || it.formObjectDefinition || "";
        if (!name) continue;
        collected.push({
          name,
          path: it.path || it.formPath || "",
          cube: it.planType || it.cube || ""
        });
      }
      return items.length > 0;
    } catch (e) {
      const msg = String(e && e.message || e);
      const m = msg.match(/NSPB (\d+)/);
      errors.push({ path: p, status: m ? m[1] : "ERR", snippet: msg.slice(0, 80) });
      return false;
    }
  };

  // 1) Per-cube probes — varies by Oracle version (plantypes vs cubes,
  //    recursive flag, /list suffix).
  for (const cube of cubes) {
    const enc = encodeURIComponent(cube);
    const cubeProbes = [
      `/plantypes/${enc}/forms?recursive=true`,
      `/plantypes/${enc}/forms`,
      `/cubes/${enc}/forms?recursive=true`,
      `/cubes/${enc}/forms`,
      `/plantypes/${enc}/forms/list`
    ];
    for (const p of cubeProbes) if (await tryPath(p)) break;
  }

  // 2) Flat-list / app-scope probes — try only if per-cube returned nothing.
  if (!collected.length) {
    const flatProbes = [
      "/forms?recursive=true",
      "/forms",
      "/forms/list",
      "/dataforms",
      "/dataforms?recursive=true",
      "/internal/forms",
      "/jobdefinitions?jobtype=FORM_DEFINITION"
    ];
    for (const p of flatProbes) if (await tryPath(p)) break;
  }

  // De-duplicate by name+path.
  const seen = new Set();
  const forms = collected.filter(f => {
    const k = f.name + "|" + f.path;
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  });

  if (!forms.length) {
    // Surface a concise summary of EVERY path attempted so the user (or me)
    // can spot which endpoint shape this tenant actually accepts.
    const summary = errors.slice(0, 10)
      .map(e => `${e.status} ${e.path}`)
      .join(" | ");
    return {
      loadedAt: Date.now(),
      forms: [],
      error: `no form-list endpoint responded. Tried ${errors.length} paths. First few: ${summary}`,
      attempts: errors
    };
  }
  return { loadedAt: Date.now(), forms };
}

// ── SmartView wire protocol helpers ──────────────────────────────────────────
// Protocol reverse-engineered from Excel Smart View diagnostics. Reference
// impl: MCP3 google_sheets_addon/EPMClient.gs smartViewExecuteGrid_ (L220+).

const SV_ENDPOINT = "/interop/rest/smartview/HyperionPlanning/SmartView";
const SV_SESSION_TTL_MS = 25 * 60 * 1000;
const MEMBER_CACHE_TTL_MS = 60 * 60 * 1000;

// Best-effort caches at module scope — survive on warm Worker instances,
// reopen on cold starts. Keyed strings are safe to index.
const svSessionCache = new Map();    // host|user|app → { sID, openedAt }
const memberResolveCache = new Map(); // host|cube|dim|expr → { members, ts }

// SmartView uses "Reporting Segment" (with space); REST and Gemini use
// "ReportingSegment". Translate on XML emission.
const SV_DIM_NAME_FIXUP = { ReportingSegment: "Reporting Segment" };

function svDimName(n) { return SV_DIM_NAME_FIXUP[n] || n; }

function svEscape(s) {
  return String(s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;")
    .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function svUnescape(s) {
  return String(s)
    .replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/&amp;/g, "&");
}

function svSessionExpired(xml) {
  if (!xml) return false;
  if (/<res_Exception[^>]*errcode="1013"/i.test(xml)) return true;
  if (/Session.*(expired|invalid|timed out)/i.test(xml)) return true;
  return false;
}

async function svPost(settings, body) {
  const url = String(settings.host).replace(/\/+$/, "") + SV_ENDPOINT;
  const resp = await fetch(url, {
    method: "POST",
    redirect: "manual",
    headers: {
      "Authorization": basicAuth(settings.username, settings.password),
      "Content-Type": "application/xml",
      "Accept": "application/xml"
    },
    body
  });
  if (resp.status >= 300 && resp.status < 400) {
    throw new Error("SmartView redirected — likely bad credentials or wrong host");
  }
  const text = await resp.text();
  if (!resp.ok) throw new Error(`SmartView ${resp.status}: ${text.slice(0, 400)}`);
  return text;
}

async function smartViewOpenApp(settings, forceRefresh = false) {
  const key = `${settings.host}|${settings.username}|${settings.appName || "NetSuite"}`;
  const cached = svSessionCache.get(key);
  if (!forceRefresh && cached && (Date.now() - cached.openedAt) < SV_SESSION_TTL_MS) {
    return cached.sID;
  }
  const xml = await svPost(settings,
    `<req_OpenApplication><app>${svEscape(settings.appName || "NetSuite")}</app></req_OpenApplication>`);
  const m = xml.match(/<sID>([\s\S]*?)<\/sID>/);
  if (!m) throw new Error("SmartView OpenApplication: no sID in response");
  const sID = m[1];
  svSessionCache.set(key, { sID, openedAt: Date.now() });
  return sID;
}

async function smartViewOpenCube(settings, sID, cube) {
  const xml = await svPost(settings,
    `<req_OpenCube><sID>${svEscape(sID)}</sID><cube>${svEscape(cube)}</cube></req_OpenCube>`);
  if (svSessionExpired(xml)) throw new Error("SV_SESSION_EXPIRED");
  return xml;
}

// Expand ILvl0Descendants(X) / Descendants(X) / Children(X) to literal member
// list via REST exportdataslice. SmartView rejects these expressions inline.
async function resolveRowMembers(settings, cube, dim, expr, povHint) {
  // Function name can contain digits — ILvl0Descendants, Lvl0Descendants. The
  // older `[A-Za-z]+` rejected them and silently treated the whole expression
  // as a literal member name, so zoom_bottom returned 1 row instead of leaves.
  if (!/^[A-Za-z][A-Za-z0-9]*\(.+\)$/.test(expr)) return [expr]; // already a literal
  // exportdataslice only accepts the INCLUSIVE function variants (verified
  // live on 2026-07-06: Children/Descendants → 400 with a misleading
  // "required dimensions are not present" error; IChildren/IDescendants/
  // ILvl0Descendants → 200). Callers dedupe the parent, so inclusive is safe.
  expr = expr.replace(/^Children\(/i, "IChildren(").replace(/^Descendants\(/i, "IDescendants(");
  const key = `${settings.host}|${cube}|${dim}|${expr}`;
  const cached = memberResolveCache.get(key);
  if (cached && (Date.now() - cached.ts) < MEMBER_CACHE_TTL_MS) return cached.members;

  // Probe POV: config defaults, backfilled from the caller's known POV
  // (grid descriptor). Dims covered by NEITHER get omitted — and Oracle
  // rejects the export when required dims are missing ("all of the required
  // dimensions are not present"), so the hint matters on sparse defaults.
  const hint = (povHint && typeof povHint === "object") ? povHint : {};
  const defaults = effectiveCubeDefaults(settings, cube);
  const otherDims = effectiveCubeDims(settings, cube).filter(d => d !== dim && d !== "Period");
  const povDims = otherDims.filter(d => defaults[d] || hint[d]);
  const probe = {
    exportPlanningData: true,
    gridDefinition: {
      suppressMissingBlocks: false,
      pov: { dimensions: povDims, members: povDims.map(d => [defaults[d] || hint[d]]) },
      columns: [{ dimensions: ["Period"], members: [["YearTotal"]] }],
      rows: [{ dimensions: [dim], members: [[expr]] }]
    }
  };
  const resp = await nspbPost(settings,
    "/plantypes/" + encodeURIComponent(cube) + "/exportdataslice", probe);
  const members = (resp.rows || []).map(r => {
    const h = r.headers;
    return Array.isArray(h) ? h[0] : h;
  }).filter(Boolean);
  // Diagnostic: a 0/1-member expansion usually means the exportdataslice
  // probe suppressed rows (POV intersection without data) or dims lacking
  // defaults got omitted from the probe POV. Visible in `wrangler tail`.
  console.log("[RESOLVE]", cube, dim, expr,
              "→", members.length, "members",
              "| probe pov:", povDims.length, "of", otherDims.length, "dims had defaults");
  if (!members.length) throw new Error(`Cannot resolve ${expr} on ${dim}`);
  memberResolveCache.set(key, { members, ts: Date.now() });
  return members;
}

// Build the full <req_ExecuteGrid> XML for an initial ad-hoc grid load.
// colAxis = [{ name, members: [...] }, ...]   (POV dims are 1-member col dims)
// rowAxis = [{ name, members: [...] }, ...]
function buildExecuteGridXml({ cube, sID, colAxis, rowAxis }) {
  const M = colAxis.length;
  const N = rowAxis.length;
  const colSizes = colAxis.map(c => c.members.length);
  const rowSizes = rowAxis.map(r => r.members.length);
  const nDataCols = colSizes.reduce((a, b) => a * b, 1);
  const nDataRows = rowSizes.reduce((a, b) => a * b, 1);
  const totalCols = N + nDataCols;
  const totalRows = M + nDataRows;
  const cellCount = totalRows * totalCols;

  // Cartesian-unroll block sizes (product of dims after this one).
  const colBlock = new Array(M);
  for (let i = M - 1, prod = 1; i >= 0; i--) { colBlock[i] = prod; prod *= colSizes[i]; }
  const rowBlock = new Array(N);
  for (let j = N - 1, prod = 1; j >= 0; j--) { rowBlock[j] = prod; prod *= rowSizes[j]; }

  let id = 0;
  const dimsXml = colAxis.map((d, k) =>
      `<dim id="${id++}" name="${svEscape(svDimName(d.name))}" col="${k}" hidden="0" expand="0"/>`).join("")
    + rowAxis.map((d, k) =>
      `<dim id="${id++}" name="${svEscape(svDimName(d.name))}" row="${k}" hidden="0" expand="0"/>`).join("");

  const vals = new Array(cellCount);
  const types = new Array(cellCount);
  for (let r = 0; r < totalRows; r++) {
    for (let c = 0; c < totalCols; c++) {
      const idx = r * totalCols + c;
      if (r < M && c < N) {
        vals[idx] = ""; types[idx] = "7";
      } else if (r < M) {
        const p = c - N;
        const mi = Math.floor(p / colBlock[r]) % colSizes[r];
        vals[idx] = svEscape(colAxis[r].members[mi]); types[idx] = "0";
      } else if (c < N) {
        const p = r - M;
        const mi = Math.floor(p / rowBlock[c]) % rowSizes[c];
        vals[idx] = svEscape(rowAxis[c].members[mi]); types[idx] = "0";
      } else {
        vals[idx] = ""; types[idx] = "2";
      }
    }
  }

  const preferences =
    `<row_suppression zero="0" invalid="0" missing="0" underscore="0" noaccess="0"/>` +
    `<celltext val="1"/>` +
    `<zoomin ancestor="top" mode="children"/>` +
    `<navigate withData="1"/>` +
    `<includeSelection val="1"/>` +
    `<repeatMemberLabels val="1"/>` +
    `<withinSelectedGroup val="0"/>` +
    `<removeUnSelectedGroup val="0"/>` +
    `<col_suppression zero="0" invalid="0" missing="0" underscore="0" noaccess="0"/>` +
    `<block_suppression missing="0"/>` +
    `<useExpenseType val="0"/>` +
    `<enableMeaningless val="0"/>` +
    `<repeatMemberLabelsInForms val="0"/>` +
    `<enableClientSideIndentation val="0"/>` +
    `<includeDescriptionInLabel val="2"/>` +
    `<missingLabelText val="#NumericZero"/>` +
    `<noAccessText val="#No Access"/>` +
    `<aliasTableName val="Default"/>` +
    `<essIndent val="2"/>` +
    `<formulaRetention retrieve="1" zoomin_out="1" keep_removeonly="1" fill="1" comments="1"/>` +
    `<sliceLimitation rows="1048576" cols="16384"/>`;

  return `<req_ExecuteGrid>` +
    `<sID>${svEscape(sID)}</sID>` +
    `<action>refresh</action>` +
    `<ords></ords>` +
    `<preferences>${preferences}</preferences>` +
    `<grid>` +
      `<cube>${svEscape(cube)}</cube>` +
      `<dims>${dimsXml}</dims>` +
      `<perspective type="Reality"/>` +
      `<slices><slice rows="${totalRows}" cols="${totalCols}">` +
        `<viewableMap><viewableRowMap></viewableRowMap><viewableColMap></viewableColMap></viewableMap>` +
        `<data><generations></generations>` +
          `<range start="0" end="${cellCount - 1}">` +
            `<vals>${vals.join("|")}</vals>` +
            `<types>${types.join("|")}</types>` +
          `</range>` +
        `</data>` +
        `<metadata/><conditionalFormats/>` +
      `</slice></slices>` +
    `</grid>` +
  `</req_ExecuteGrid>`;
}

function svCoerceCell(v) {
  const s = String(v == null ? "" : v);
  if (s === "" || s === "#Missing" || s === "#NoAccess") return null;
  const stripped = s.replace(/,/g, "");
  if (/^-?\d+(\.\d+)?$/.test(stripped)) return Number(stripped);
  // Parenthesized negative: (1,234.56)
  if (/^\(-?\d+(\.\d+)?\)$/.test(stripped)) return -Number(stripped.slice(1, -1));
  return s;
}

function parseSmartViewSlice(xml) {
  // Find the LAST <slice rows= cols=> — responses sometimes echo the request
  // slice first with empty data, then emit the real response slice after.
  const sliceHeaders = [...xml.matchAll(/<slice\s+rows="(\d+)"\s+cols="(\d+)"/g)];
  if (!sliceHeaders.length) {
    throw new Error("SmartView response: no <slice> found — " + xml.slice(0, 400));
  }
  const last = sliceHeaders[sliceHeaders.length - 1];
  const rows = parseInt(last[1], 10);
  const cols = parseInt(last[2], 10);

  // Search vals/types/txts in the substring AFTER the chosen slice header so we
  // don't grab the request-echo data if the server includes it.
  const tail = xml.slice(last.index);
  const valsMatch = tail.match(/<vals[^>]*>([\s\S]*?)<\/vals>/);
  const typesMatch = tail.match(/<types[^>]*>([\s\S]*?)<\/types>/);
  const txtsMatch = tail.match(/<txts[^>]*>([\s\S]*?)<\/txts>/);
  // Per-cell access bitmask — this is how Smart View itself knows which form
  // cells are read-only (bit 0x2). Without it the client can only guess
  // editability from <types>, which marks blocked data cells as data too.
  const statusMatch = tail.match(/<status[^>]*>([\s\S]*?)<\/status>/);
  if (!valsMatch) {
    throw new Error("SmartView response: no <vals> in slice — " + tail.slice(0, 400));
  }

  const rangeMatch = tail.match(/<range\s+start="(\d+)"/);
  const rangeStart = rangeMatch ? parseInt(rangeMatch[1], 10) : 0;

  const valsArr = valsMatch[1].split("|");
  const typesArr = typesMatch ? typesMatch[1].split("|") : [];
  const txtsArr = txtsMatch ? txtsMatch[1].split("|") : [];
  const statusArr = statusMatch ? statusMatch[1].split("|") : [];

  // ── Parse the POV (page axis) members. SmartView returns pages in one
  // of several shapes depending on the form type. Try each and merge.
  //
  // Shape D (Oracle Cloud actual): <pages><page dimId="4" mbr="SUB_2"/>...</pages>
  //   — dim referenced by numeric id, requires dimId→name mapping from
  //     <dim id="N" name="X"/> blocks elsewhere in the response.
  // Shape A: <pages><page name="Class"><member>NoClass</member></page></pages>
  // Shape B: <page name="..." sel="..."/>
  // Shape C: <dim name="..." selectedMember="..."/>
  const povMembers = [];
  const seenDims = new Set();
  const addPov = (dim, member, alias) => {
    if (!dim || !member) return;
    if (seenDims.has(dim)) return;
    seenDims.add(dim);
    povMembers.push({ dim, member, alias: alias || "" });
  };

  // Build dimId → name lookup AND extract fixed-POV members directly from
  // the <dim id="N" name="X" ...> opening tags. NSPB Cloud uses both:
  //   - Hidden fixed POV: <dim id="0" name="Location" pov="NSP_Total Location" hidden="1" ...>
  //     ↑ member is in the `pov` attribute of the dim tag itself
  //   - Page-axis POV (changeable): <dim id="4" name="Subsidiary" page="0" display="United States" ...>
  //     ↑ member is in the separate <page dimId="4" mbr="SUB_2"/> block
  // Match BOTH self-closing `<dim ... />` AND opening `<dim ...>` (with body).
  const dimIdToName = new Map();
  // Axis assignment — the <dim> tags carry row="k" / col="k" attributes that
  // say which axis each dim sits on and in what order. This is what lets us
  // synthesize an adhoc gridDescriptor from an opened form (so modify_grid
  // can navigate form-origin grids). Hidden dims are fixed POV, not axis.
  const axisRowDims = [];   // [{name, pos}]
  const axisColDims = [];
  const seenAxisDim = new Set();
  const dimDefs = [...xml.matchAll(/<dim\b([^>]*?)\/?>/g)];
  for (const m of dimDefs) {
    const a = m[1] || "";
    const idMatch = a.match(/\bid="([^"]+)"/);
    const nameMatch = a.match(/\bname="([^"]+)"/);
    if (!idMatch || !nameMatch) continue;
    const dim = svUnescape(nameMatch[1]);
    dimIdToName.set(idMatch[1], dim);
    const hidden = /\bhidden="1"/.test(a);
    const rowAt = a.match(/\brow="(\d+)"/);
    const colAt = a.match(/\bcol="(\d+)"/);
    if (!hidden && !seenAxisDim.has(dim)) {
      if (rowAt)      { axisRowDims.push({ name: dim, pos: parseInt(rowAt[1], 10) }); seenAxisDim.add(dim); }
      else if (colAt) { axisColDims.push({ name: dim, pos: parseInt(colAt[1], 10) }); seenAxisDim.add(dim); }
    }
    // Fixed-POV (hidden) dims carry their member in the `pov` attribute.
    const povAttr = a.match(/\bpov="([^"]+)"/);
    if (povAttr) {
      addPov(dim, svUnescape(povAttr[1]));
    }
  }
  axisRowDims.sort((a, b) => a.pos - b.pos);
  axisColDims.sort((a, b) => a.pos - b.pos);

  // Shape D: <page dimId="N" mbr="X"/> — page-axis (changeable) POV
  const pagesD = [...xml.matchAll(/<page\s+([^>]*?)\/>/g)];
  for (const m of pagesD) {
    const a = m[1] || "";
    const dimId = (a.match(/\bdimId="([^"]+)"/) || [])[1];
    const mbr = (a.match(/\bmbr="([^"]+)"/) || [])[1];
    if (dimId && mbr && dimIdToName.has(dimId)) {
      addPov(dimIdToName.get(dimId), svUnescape(mbr));
    }
  }

  // Shape A: <page name="..."> ... <member>X</member></page>
  const pagesA = [...xml.matchAll(/<page\s+([^>]*?)>([\s\S]*?)<\/page>/g)];
  for (const m of pagesA) {
    const attrs = m[1] || "";
    const inner = m[2] || "";
    const nameMatch = attrs.match(/\bname="([^"]+)"/);
    if (!nameMatch) continue;
    const dim = svUnescape(nameMatch[1]);
    const memMatch = inner.match(/<member[^>]*>([\s\S]*?)<\/member>/);
    if (!memMatch) continue;
    const memText = svUnescape(memMatch[1]).trim();
    const aliasMatch = inner.match(/<alias[^>]*>([\s\S]*?)<\/alias>/);
    const alias = aliasMatch ? svUnescape(aliasMatch[1]).trim() : "";
    addPov(dim, memText, alias);
  }

  // Shape B: <page name="X" sel="Y"/>
  for (const m of pagesD) {
    const a = m[1] || "";
    const dim = (a.match(/\bname="([^"]+)"/) || [])[1];
    const member = (a.match(/\bsel(?:ectedMember)?="([^"]+)"/) || [])[1]
                || (a.match(/\bcur="([^"]+)"/) || [])[1];
    if (dim && member) addPov(svUnescape(dim), svUnescape(member));
  }
  // Shape C: <dim name="X" selectedMember="Y"/>
  for (const m of dimDefs) {
    const a = m[1] || "";
    const dim = (a.match(/\bname="([^"]+)"/) || [])[1];
    const member = (a.match(/\bselectedMember="([^"]+)"/) || [])[1]
                || (a.match(/\bsel="([^"]+)"/) || [])[1];
    if (dim && member) addPov(svUnescape(dim), svUnescape(member));
  }

  const grid = [];
  const types = [];   // parallel 2D array of SV cell types — used by the
                      // browser to paint INPUT cells yellow for data-entry forms.
  const statuses = [];  // parallel 2D access bitmasks (bit 0x2 = read-only);
                        // null when the response has no <status> block.
  for (let r = 0; r < rows; r++) {
    const row = new Array(cols);
    const trow = new Array(cols);
    const srow = new Array(cols);
    for (let c = 0; c < cols; c++) {
      const idx = r * cols + c - rangeStart;
      if (idx < 0 || idx >= valsArr.length) { row[c] = ""; trow[c] = ""; srow[c] = ""; continue; }
      const t = typesArr[idx];
      trow[c] = t || "";
      srow[c] = statusArr[idx] || "";
      const rawVal = svUnescape(valsArr[idx] || "");
      const rawTxt = svUnescape(txtsArr[idx] || "");
      // Prefer alias text when present (aliases come back in <txts> when the
      // server doesn't inline them into <vals>).
      const display = rawTxt || rawVal;
      if (t === "7") row[c] = "";
      else if (t === "0" || t === undefined) row[c] = display;
      else row[c] = svCoerceCell(rawVal);
    }
    grid.push(row);
    types.push(trow);
    statuses.push(srow);
  }
  return {
    grid, types, statuses: statusMatch ? statuses : null, rows, cols, pov: povMembers,
    axes: { rowDims: axisRowDims.map(d => d.name), colDims: axisColDims.map(d => d.name) }
  };
}

// ── build_adhoc implementation ───────────────────────────────────────────────
// Gemini occasionally hallucinates function names (e.g. "ILv10Descendants"
// with digit-zero instead of "ILvl0Descendants" with lowercase-L). Normalize
// to the canonical enum so downstream callers — SmartView, REST resolver,
// seedFromExpansion — don't have to second-guess the input. Anything we can't
// recognize falls through to "Member" so the caller still gets a literal seed
// instead of a Cartesian explosion or a silent miss.
const FN_ENUM = ["Member", "Children", "Descendants", "ILvl0Descendants", "Siblings"];
function normalizeFn(fn) {
  if (!fn) return "Member";
  const exact = FN_ENUM.find(v => v === fn);
  if (exact) return exact;
  const lower = String(fn).toLowerCase();
  // Strip digits to merge "ILv10Descendants" and "ILvl0Descendants" into the
  // same key, then look up by lowercase-letters-only signature.
  const sig = lower.replace(/[^a-z]/g, "");
  const map = {
    member: "Member",
    children: "Children",
    descendants: "Descendants",
    ilvldescendants: "ILvl0Descendants",
    lvldescendants: "ILvl0Descendants",
    idescendants: "Descendants",
    leaves: "ILvl0Descendants",
    siblings: "Siblings",
    ichildren: "Children"
  };
  return map[sig] || "Member";
}

function buildRowMemberExpr(row) {
  const fn = normalizeFn(row.fn);
  return fn === "Member" ? row.member : `${fn}(${row.member})`;
}

// "ILvl0Descendants(TL)" → "TL"   "IDescendants(TR)" → "TR"   "TL_01" → "TL_01"
function seedFromExpansion(expr) {
  const m = String(expr || "").match(
    /^@?(?:ILvl0Descendants|Lvl0Descendants|Descendants|IDescendants|Children|IChildren|Siblings|Leaves)\s*\(\s*(.+?)\s*\)\s*$/i
  );
  return m ? m[1] : String(expr || "");
}

// NOTE: `settings` is a real parameter — it used to be read as a free
// identifier, which is a ReferenceError in the module-format bundle (strict
// mode) and killed every build_adhoc / modify_grid / compare_grid / preset
// call at runtime. Callers must thread their settings through.
function fillPov(settings, cube, rows, columns, povOverrides) {
  const defaults = effectiveCubeDefaults(settings, cube);
  const dims = effectiveCubeDims(settings, cube);
  const placed = new Set();
  rows.forEach(r => placed.add(r.dimension));
  columns.forEach(c => placed.add(c.dimension));

  const pov = {};
  dims.forEach(d => {
    if (placed.has(d)) return;
    if (povOverrides && povOverrides[d]) pov[d] = povOverrides[d];
    else if (defaults[d]) pov[d] = defaults[d];
  });
  Object.keys(povOverrides || {}).forEach(d => {
    if (!placed.has(d) && !(d in pov)) pov[d] = povOverrides[d];
  });
  return pov;
}

// Append a "% of Total" column at the right edge of `grid`. The denominator
// is the sum of `baseCol` across every data row (rows ≥ headerRowCount). If
// `baseCol` is omitted, defaults to the last column at the time of the call.
// `numRowLabelCols` is used only to size the empty cells in the row-label
// region (left edge) of header rows — defaults to 1 (regular build_adhoc).
//
// Header treatment: the LAST header row gets the literal "% of Total" label;
// upper header rows get "" so the column reads cleanly when bolded.
//
// Each data row's value is `row[baseCol] / total` as a fraction (0..1) so the
// taskpane / Excel can apply a "0.00%" number format. Non-numeric or zero
// denominator → "" (blank — no spurious zeros, no #DIV/0!).
function appendPctOfTotal(grid, opts = {}) {
  if (!Array.isArray(grid) || grid.length === 0) return grid;
  const numCols = grid[0].length;
  if (numCols === 0) return grid;
  const numRowLabelCols = opts.numRowLabelCols || 1;
  const baseCol = (opts.baseCol != null) ? opts.baseCol : (numCols - 1);

  // Locate the first row with a numeric cell in baseCol — that's the first
  // data row; everything above is header. Same heuristic as mergeGridsForCompare
  // so the inserted "% of Total" label aligns with the existing last header.
  let headerRowCount = 0;
  for (let r = 0; r < grid.length; r++) {
    if (typeof grid[r][baseCol] === "number") { headerRowCount = r; break; }
    if (r === grid.length - 1) headerRowCount = grid.length;
  }

  let total = 0;
  for (let r = headerRowCount; r < grid.length; r++) {
    const v = grid[r][baseCol];
    if (typeof v === "number") total += v;
  }

  for (let r = 0; r < grid.length; r++) {
    if (r < headerRowCount) {
      grid[r].push(r === headerRowCount - 1 ? "% of Total" : "");
    } else {
      const v = grid[r][baseCol];
      grid[r].push((typeof v === "number" && total !== 0) ? (v / total) : "");
    }
  }
  // Silence unused-var lint in environments that warn on it.
  void numRowLabelCols;
  return grid;
}

// Drop rows whose every non-label cell is 0 / null / empty. Keeps the header
// row and any "Total"/"Others"/subtotal rows even if they roll to zero (bold
// labels would look weird with gaps otherwise). Operates on the 2D grid
// returned by parseSmartViewSlice / mergeGridsForCompare.
function dropZeroRows(grid) {
  if (!Array.isArray(grid) || grid.length <= 1) return grid;
  const totalRe = /^\s*(year\s*total|total|subtotal|grand\s*total|others\s*\(\d+\))\s*$/i;
  const out = [grid[0]];   // header row always kept
  for (let i = 1; i < grid.length; i++) {
    const row = grid[i];
    if (!Array.isArray(row) || row.length <= 1) { out.push(row); continue; }
    const label = String(row[0] || "");
    if (totalRe.test(label)) { out.push(row); continue; }
    const allZero = row.slice(1).every(v => {
      if (v == null || v === "") return true;
      if (typeof v === "number") return v === 0;
      const n = Number(v);
      return !isNaN(n) && n === 0;
    });
    if (!allZero) out.push(row);
  }
  return out;
}

async function runBuildAdhoc(settings, args, opts = {}) {
  // Cube default: the DETECTED main cube, never the legacy hardcoded "Plan"
  // (which doesn't exist on custom tenants and silently pulls Pharmalogic
  // dims into the POV → Oracle errcode 4997 "dimension X is invalid").
  const ac = settings && settings.appConfig;
  const cube = args.cube || (ac && ac.mainCube) || CLIENT_CONFIG.mainCube || "Plan";
  // When we KNOW the tenant's cubes, reject unknown cube names early with
  // the real list — the model self-corrects on the next round instead of
  // dying on Oracle's cryptic invalid-dimension error.
  if (ac && ac.cubeDims && !Array.isArray(ac.cubeDims[cube])) {
    throw new Error(`Cube "${cube}" doesn't exist in this application. Available cubes: ${Object.keys(ac.cubeDims).join(", ")}. Retry with one of those.`);
  }
  const rowArgs = Array.isArray(args.rows) ? args.rows : [];
  const colArgs = Array.isArray(args.columns) ? args.columns : [];
  if (!rowArgs.length) throw new Error("build_adhoc: rows required");
  if (!colArgs.length) throw new Error("build_adhoc: columns required (Period)");

  const pov = fillPov(settings, cube, rowArgs, colArgs, args.pov || {});

  // Seed-only mode: keep only the seed member (e.g. ILvl0Descendants(TL) → TL)
  // and let the user zoom in from Excel. Matches MCP3's default `expand=false`
  // and avoids Cartesian explosions (6 × ILvl0Descendants = 4B+ cells).
  const expandRows = opts.expandRows === true;

  // 1. Build row axis members — either pre-resolve via REST (expandRows=true)
  //    or keep as a 1-member seed (default). SmartView rejects expansion
  //    expressions inline in <dim>, so seeds must be literal member names.
  const rowAxis = [];
  for (const r of rowArgs) {
    // Explicit member lists (form-origin descriptors, modify_grid add/remove/
    // pivot results) bypass seed resolution entirely — they ARE the rendered
    // state.
    if (Array.isArray(r.members) && r.members.length) {
      rowAxis.push({ name: r.dimension, members: r.members.map(String) });
      continue;
    }
    const expr = buildRowMemberExpr(r);
    const members = expandRows
      ? await resolveRowMembers(settings, cube, r.dimension, expr,
          // POV + one member per other axis dim — every cube dim represented.
          Object.assign({}, pov,
            ...colArgs.map(c => ({ [c.dimension]: (c.members || [])[0] })),
            ...rowArgs.filter(x => x !== r).map(x => ({ [x.dimension]: Array.isArray(x.members) ? x.members[0] : x.member }))))
      : [seedFromExpansion(expr)];
    rowAxis.push({ name: r.dimension, members });
  }

  // 2. Col axis = caller's Period columns + every remaining cube dim as a
  //    1-member slice (SmartView requires every cube dim on some axis).
  const axisDims = new Set(
    rowArgs.map(r => r.dimension).concat(colArgs.map(c => c.dimension))
  );
  const colAxis = colArgs.map(c => ({ name: c.dimension, members: c.members }));
  // SmartView requires EVERY cube dim on some axis. If we don't know this
  // cube's dim list, the grid would reach Oracle incomplete and bounce with
  // a cryptic "Grid is Invalid" — fail here with an actionable message.
  const cubeDims = effectiveCubeDims(settings, cube);
  if (!cubeDims.length) {
    throw new Error(
      `The dimensions of cube ${cube} aren't known yet, so the POV can't be auto-filled. ` +
      `Ask the user to open Settings and click 'Load everything' (or 'Detect everything'), then retry.`
    );
  }
  for (const d of cubeDims) {
    if (axisDims.has(d)) continue;
    const m = pov[d];
    if (!m) throw new Error(`build_adhoc: no POV value for dim ${d} on ${cube}`);
    colAxis.push({ name: d, members: [m] });
  }
  console.log("[BUILD_ADHOC]", cube,
              "| dims:", cubeDims.length,
              "| rows:", rowAxis.map(r => `${r.name}(${r.members.length})`).join("×"),
              "| cols:", colAxis.map(c => `${c.name}(${c.members.length})`).join("×"),
              "| pov keys:", Object.keys(pov).join(","));

  // 3. SmartView session + cube activation.
  let sID = await smartViewOpenApp(settings);
  try {
    await smartViewOpenCube(settings, sID, cube);
  } catch (e) {
    if (String(e.message).indexOf("SV_SESSION_EXPIRED") >= 0) {
      sID = await smartViewOpenApp(settings, true);
      await smartViewOpenCube(settings, sID, cube);
    } else throw e;
  }

  // 4. ExecuteGrid with one automatic retry on session expiry.
  const reqXml = buildExecuteGridXml({ cube, sID, colAxis, rowAxis });
  console.log("SV req first 600:", reqXml.slice(0, 600));
  let respXml = await svPost(settings, reqXml);
  if (svSessionExpired(respXml)) {
    sID = await smartViewOpenApp(settings, true);
    await smartViewOpenCube(settings, sID, cube);
    const retryXml = reqXml.replace(/<sID>[\s\S]*?<\/sID>/, `<sID>${svEscape(sID)}</sID>`);
    respXml = await svPost(settings, retryXml);
    if (svSessionExpired(respXml)) {
      throw new Error("SmartView session expired twice — check credentials/host.");
    }
  }

  // Surface Oracle exceptions cleanly instead of parsing garbage.
  const excMatch = respXml.match(/<res_Exception[^>]*errcode="([^"]+)"[^>]*>([\s\S]*?)<\/res_Exception>/);
  if (excMatch) {
    // Tenant-config error worth translating: ad-hoc is disabled app-wide
    // until an admin flips one setting. Without this mapping the chat just
    // apologizes and the user has no idea it's a 30-second admin fix.
    if (/standard\s+ad.?hoc\s+mode\s+is\s+not\s+enabled/i.test(excMatch[2])) {
      throw new Error(
        "This NSPB application has Smart View ad-hoc DISABLED, which blocks all grid queries from this add-in. " +
        "An administrator can enable it in ~30 seconds: NSPB web → Application → Settings → 'Smart View Ad Hoc Behavior' → select 'Standard' → Save. " +
        "No restart needed — retry the query right after."
      );
    }
    throw new Error(`SmartView errcode=${excMatch[1]}: ${excMatch[2].slice(0, 300)}`);
  }

  console.log("SV resp len:", respXml.length,
              "| head:", respXml.slice(0, 400),
              "| tail:", respXml.slice(-400));
  const parsed = parseSmartViewSlice(respXml);
  const sheetName = (args.sheet_name || `${cube} ${pov.Years || ""}`).slice(0, 30);

  // Optional zero-row filter — drops rows whose every numeric cell is 0 or null.
  // `args.removeZeros` is the per-call flag; callers (runModifyGrid, presets,
  // compare, top_drivers) forward it. Header row is always kept.
  let finalGrid = args.removeZeros ? dropZeroRows(parsed.grid) : parsed.grid;

  // Optional "% of Total" column. Computed AFTER removeZeros so the ratios
  // reflect what the user actually sees, not the unfiltered set.
  if (args.pctOfTotal) {
    finalGrid = appendPctOfTotal(finalGrid, { numRowLabelCols: rowArgs.length });
  }

  // ── SmartView-raw presentation ────────────────────────────────────────────
  // The auto-filled POV dims (single-member column dims appended AFTER the
  // caller's columns) render as stacked header rows — 15+ rows of noise on a
  // 16-dim cube. Re-lay them as one POV line each at the top (member in col
  // A), exactly like an opened form / native SV ad-hoc, and ship the sheet
  // as format:"raw" (no styling) so SmartView Connect → Refresh keeps
  // working on it. compare_grid / top_drivers opt out (rawLayout:false) —
  // they merge/post-process grids assuming the original header block.
  // Runs AFTER removeZeros/pctOfTotal: dropZeroRows would eat single-cell
  // POV lines, and the pct label needs relocating from the last (POV)
  // header row to the last REAL header row.
  const rawLayout = opts.rawLayout !== false;
  let outFormat = null;
  if (rawLayout) {
    const K = colArgs.length;      // caller's real column dims (header rows to keep)
    const M = colAxis.length;      // + auto-filled single-member POV dims
    if (M > K && finalGrid.length > M) {
      const width = finalGrid.reduce((w, r) => Math.max(w, (r || []).length), 1);
      // ONE horizontal POV row (native Smart View convention: every POV
      // member side-by-side on row 1) — not a vertical block in column A.
      const povRow = new Array(width).fill("");
      colAxis.slice(K).forEach((c, i) => { if (i < width) povRow[i] = c.members[0]; });
      const headerRows = finalGrid.slice(0, K).map(r => r.slice());
      if (args.pctOfTotal && headerRows.length) {
        const orig = finalGrid[M - 1] || [];
        if (orig[orig.length - 1] === "% of Total") {
          headerRows[headerRows.length - 1][orig.length - 1] = "% of Total";
        }
      }
      finalGrid = [povRow].concat(headerRows, finalGrid.slice(M));
    }
    outFormat = "raw";
  }

  // Data presence — a grid full of blanks LOOKS like success but isn't.
  // The chat uses this to trigger the empty-grid protocol (question the POV,
  // offer dimension totals) instead of announcing a hollow victory.
  let dataCellCount = 0;
  for (const r of finalGrid) for (const v of (r || [])) if (typeof v === "number") dataCellCount++;

  return {
    sheetName,
    grid: finalGrid,
    format: outFormat,
    dataCellCount,
    // gridDescriptor captures the ORIGINAL spec (not the expanded member list)
    // so modify_grid can reason about seeds: zoom_in swaps fn Member→Children,
    // zoom_out walks to parent via the catalog, keep_only narrows to one member.
    gridDescriptor: {
      cube,
      sheetName,
      pov: { ...pov },
      rowAxis: rowArgs.map((r, i) => {
        // Explicit member lists round-trip untouched — that IS the rendered
        // state and modify_grid mutates the list directly.
        if (Array.isArray(r.members) && r.members.length) {
          return { dimension: r.dimension, members: r.members.map(String) };
        }
        return {
          dimension: r.dimension,
          // Mirror the RENDERED state, not the requested intent. When build_adhoc
          // is in seed-only mode (expandRows=false, default), only the seed shows
          // even if `fn` was ILvl0Descendants. Storing `fn:Member` here means the
          // next modify_grid won't surprise-expand this dim when the user pivots
          // a different one. When resolveRowMembers actually expanded, keep the
          // original fn so zoom_out/keep_only still has the seed→tree context.
          fn: (rowAxis[i] && rowAxis[i].members && rowAxis[i].members.length > 1)
            ? normalizeFn(r.fn)
            : "Member",
          member: r.member
        };
      }),
      colAxis: colArgs.map(c => ({
        dimension: c.dimension,
        members: c.members.slice()
      })),
      asOf: Date.now()
    },
    debug: { cube, pov, rows: parsed.rows, cols: parsed.cols }
  };
}

async function runPreset(settings, args) {
  const name = args && args.name;
  const preset = name && (CLIENT_CONFIG.presets || {})[name];
  if (!preset) {
    const available = Object.keys(CLIENT_CONFIG.presets || {}).join(", ") || "(none)";
    throw new Error(`Unknown preset "${name}". Available: ${available}`);
  }
  // Compare presets dispatch to runCompareGrid. The preset shape mirrors the
  // compare_grid tool's args, so it's a thin pass-through.
  if (preset.kind === "compare") {
    return runCompareGrid(settings, {
      cube: preset.cube,
      sheet_name: name,
      rows: preset.rows,
      columns: preset.columns,
      basePov: preset.basePov || preset.pov || {},
      compare: preset.compare,
      removeZeros: !!(args && args.removeZeros)
    });
  }
  return runBuildAdhoc(settings, {
    cube: preset.cube,
    sheet_name: name,
    rows: preset.rows,
    columns: preset.columns,
    pov: preset.pov || {},
    removeZeros: !!(args && args.removeZeros)
  }, { expandRows: preset.expandRows === true });
}

// ── find_member: fuzzy lookup over the catalog ───────────────────────────────
function findMember(catalog, args, tenantKb) {
  // Two member sources, in priority order:
  //  1. the live discovered catalog (client "Dims" buttons) — has parents,
  //  2. tenantKb.dimensions from the LCM export — flat {name, alias, level}
  //     lists, always available once the KB is imported. Without this
  //     fallback, "revenue by month" on a fresh tenant dead-ends with
  //     "no member named revenue" because the catalog is empty.
  const cat = (catalog && typeof catalog === "object") ? catalog : {};
  const kbDims = (tenantKb && tenantKb.dimensions && typeof tenantKb.dimensions === "object")
    ? tenantKb.dimensions : {};
  const dimSource = (d) => {
    const c = Array.isArray(cat[d]) ? cat[d] : [];
    const k = Array.isArray(kbDims[d]) ? kbDims[d] : [];
    if (!k.length) return c;
    if (!c.length) return k;
    // MERGE, don't pick: the discovered catalog is often scoped to ONE cube
    // (e.g. Account discovered from Workforce → only bonus/assumption
    // accounts) while the LCM KB carries the app-wide outline. Catalog
    // entries win on duplicates (they have parent info for zoom_out); the
    // KB fills in everything the catalog is missing.
    const seen = new Set(c.map(m => String(m.name || "").toLowerCase()));
    return c.concat(k.filter(m => !seen.has(String(m.name || "").toLowerCase())));
  };
  const allDims = [...new Set(Object.keys(cat).concat(Object.keys(kbDims)))];
  if (!allDims.length) {
    return { ok: false, error: "No member catalog available. Import the tenant-kb.json (Settings → Load everything) or click Discover dimensions." };
  }
  const query = String((args && args.query) || "").toLowerCase().trim();
  if (!query) return { ok: false, error: "find_member: query required" };
  const dimFilter = args && args.dim;
  const dims = dimFilter ? [dimFilter] : allDims;
  const scored = [];
  for (const d of dims) {
    const list = dimSource(d);
    for (const m of list) {
      const nm = String(m.name || "").toLowerCase();
      const al = String(m.alias || "").toLowerCase();
      let score;
      if (nm === query || al === query) score = 1.0;
      else if (al.startsWith(query) || nm.startsWith(query)) score = 0.85;
      else if (al.includes(query) || nm.includes(query)) score = 0.65;
      else continue;
      // Slightly penalise very long aliases so tighter matches rank first.
      score -= Math.min(0.1, al.length / 2000);
      scored.push({
        dim: d, code: m.name, alias: m.alias, parent: m.parent,
        level: m.level, score: Math.round(score * 100) / 100
      });
    }
  }
  scored.sort((a, b) => b.score - a.score);
  return { ok: true, matches: scored.slice(0, 3) };
}

// ── Contextual navigation chips ──────────────────────────────────────────────
// Computed deterministically from the grid descriptor so the user DISCOVERS
// the SmartView verbs (add year, pivot, zoom, swap) without knowing them.
// Returned as ready "Label → command" strings; the model appends them as
// CHIP: lines after a data grid is written.
function buildNavChips(desc, appConfig) {
  try {
    if (!desc || !desc.cube) return [];
    const chips = [];
    const axisDims = new Set(
      (desc.rowAxis || []).map(r => r.dimension).concat((desc.colAxis || []).map(c => c.dimension))
    );
    // Years: offer the neighbor year not shown yet.
    const yearsEntry = (desc.colAxis || []).find(c => /^years?$/i.test(c.dimension))
                    || (desc.rowAxis || []).find(r => /^years?$/i.test(r.dimension));
    const yearsShown = yearsEntry
      ? (Array.isArray(yearsEntry.members) ? yearsEntry.members : [yearsEntry.member]).filter(Boolean)
      : ((desc.pov && desc.pov.Years) ? [desc.pov.Years] : []);
    const yrNums = yearsShown.map(y => parseInt(String(y).replace(/\D/g, ""), 10)).filter(n => !isNaN(n));
    if (yrNums.length) {
      const known = (appConfig && Array.isArray(appConfig.years)) ? appConfig.years : null;
      const next = "FY" + String(Math.max(...yrNums) + 1).padStart(2, "0");
      const prev = "FY" + String(Math.min(...yrNums) - 1).padStart(2, "0");
      const pick = (!known || known.includes(next)) ? next : ((!known || known.includes(prev)) ? prev : null);
      if (pick && !yearsShown.includes(pick)) chips.push(`➕ Add ${pick} → add year ${pick} to this grid`);
    }
    // First POV dim → pivot suggestion.
    const povDims = Object.keys(desc.pov || {}).filter(d => !axisDims.has(d));
    if (povDims.length) chips.push(`🔄 ${povDims[0]} on columns → pivot ${povDims[0]} to columns`);
    // First row dim → zoom suggestions on its first member (one level and
    // straight to leaves — the two most common form gestures).
    const r0 = (desc.rowAxis || [])[0];
    const seed = r0 && (Array.isArray(r0.members) ? r0.members[0] : r0.member);
    if (r0 && seed) {
      chips.push(`🔍 Zoom ${seed} (${r0.dimension}) → zoom in on ${seed}`);
      chips.push(`⤵️ ${r0.dimension} to leaves → zoom to bottom of ${seed}`);
    }
    chips.push("↔️ Swap rows/columns → swap rows and columns");
    return chips.slice(0, 5);
  } catch (_) { return []; }
}

// ── submit grid: write edited sheet values back to the cube ─────────────────
// Uses Planning REST importdataslice (Basic-Auth friendly) — the same API
// Data Management uses for cell writes. Works on descriptor-backed grids
// with EXPLICIT member lists (opened forms, add/remove/pivot results): the
// descriptor says exactly which member each data row/column is, so the sheet
// only needs to supply the numbers. Write access is enforced by NSPB's own
// security — rejected cells come back counted, never silently dropped.
function cartesianLists(lists) {
  let out = [[]];
  for (const l of lists) {
    const nx = [];
    for (const c of out) for (const m of l) nx.push(c.concat(m));
    out = nx;
  }
  return out;
}

async function runSubmitGrid(settings, desc, activeSheet) {
  if (!desc || !desc.cube) {
    throw new Error("No grid descriptor for this sheet — open a form or build a grid first, or use the SmartView ribbon → Save.");
  }
  const rowsAxes = desc.rowAxis || [], colsAxes = desc.colAxis || [];
  const allExplicit = rowsAxes.length && colsAxes.length &&
    rowsAxes.every(r => Array.isArray(r.members) && r.members.length) &&
    colsAxes.every(c => Array.isArray(c.members) && c.members.length);
  if (!allExplicit) {
    throw new Error("Submit works on form grids and navigated grids (explicit members). Open the form, type the values, then say 'submit data'.");
  }
  const N = rowsAxes.length;
  const rowCombos = cartesianLists(rowsAxes.map(r => r.members));
  const colCombos = cartesianLists(colsAxes.map(c => c.members));
  const values = (activeSheet && activeSheet.values) || [];
  if (values.length < rowCombos.length) {
    throw new Error("The active sheet doesn't match the grid I have for it (row count differs). Rebuild/reopen the grid, edit the cells, then submit.");
  }
  // Data block = the LAST <rowCombos> rows (POV/header rows sit on top),
  // columns N.. — matches exactly how the grid was written.
  const dataRows = values.slice(values.length - rowCombos.length);
  const toCell = (v) => {
    if (typeof v === "number") return String(v);
    if (v == null || v === "") return "";
    const n = Number(String(v).replace(/,/g, ""));
    return isNaN(n) ? "" : String(n);
  };
  const rows = rowCombos.map((combo, i) => ({
    headers: combo,
    data: (dataRows[i] || []).slice(N, N + colCombos.length).map(toCell)
  })).filter(r => r.data.some(v => v !== ""));
  if (!rows.length) {
    throw new Error("No numeric cells found to submit on this sheet — type values into the editable cells first.");
  }
  const payload = {
    aggregateEssbaseData: false,
    dataGrid: {
      pov: Object.values(desc.pov || {}),
      columns: colsAxes.map((c, k) => colCombos.map(combo => combo[k])),
      rows
    }
  };
  const resp = await nspbPost(settings,
    "/plantypes/" + encodeURIComponent(desc.cube) + "/importdataslice", payload);
  const accepted = (resp && (resp.numAcceptedCells != null ? resp.numAcceptedCells : resp.acceptedCells));
  const rejected = (resp && (resp.numRejectedCells != null ? resp.numRejectedCells : resp.rejectedCells)) || 0;
  console.log("[SUBMIT_GRID]", desc.cube, "rows:", rows.length, "accepted:", accepted, "rejected:", rejected);
  return {
    accepted: accepted != null ? accepted : rows.reduce((a, r) => a + r.data.filter(v => v !== "").length, 0),
    rejected,
    cube: desc.cube
  };
}

// ── Grid legend ──────────────────────────────────────────────────────────────
// One line per axis so the user always knows WHICH DIMENSION sits where.
// The client paints the same regions on the sheet: 🟦 row labels (blue),
// 🟩 column headers (green), 🟨 POV (amber).
function buildGridLegend(desc) {
  try {
    if (!desc || !desc.cube) return null;
    const fmtEntry = (e) => Array.isArray(e.members)
      ? `**${e.dimension}** (${e.members.length === 1 ? e.members[0] : e.members.length + " members"})`
      : `**${e.dimension}** (${e.fn && e.fn !== "Member" ? e.fn + " of " : ""}${e.member})`;
    const rows = (desc.rowAxis || []).map(fmtEntry).join(" × ") || "—";
    const cols = (desc.colAxis || []).map(fmtEntry).join(" × ") || "—";
    const povKeys = Object.keys(desc.pov || {});
    const pov = povKeys.slice(0, 6).map(k => `${k}=${desc.pov[k]}`).join(" · ")
      + (povKeys.length > 6 ? ` · +${povKeys.length - 6} more` : "");
    return [
      `🟦 Rows: ${rows}`,
      `🟩 Columns: ${cols}`,
      `🟨 POV: ${pov || "—"}`
    ];
  } catch (_) { return null; }
}

// ── Empty-grid POV suggestions ───────────────────────────────────────────────
// When a grid returns zero data, the usual culprit is the POV pointing at an
// intersection that holds nothing. Offer one chip per POV dim that swaps it
// to the dimension TOTAL (root / first parent) so the user can walk toward
// where the data lives. Roots come from the discovered catalog (entry with
// no parent) or, failing that, the highest-level entry in the LCM KB.
function buildPovTotalChips(desc, catalog, tenantKb) {
  try {
    const chips = [];
    const kbDims = (tenantKb && tenantKb.dimensions && typeof tenantKb.dimensions === "object")
      ? tenantKb.dimensions : {};
    for (const dim of Object.keys(desc.pov || {})) {
      const member = desc.pov[dim];
      let top = null;
      const cat = (catalog && catalog[dim]) || [];
      const root = cat.find(m => m && m.name && !m.parent);
      if (root) top = root.name;
      if (!top && Array.isArray(kbDims[dim]) && kbDims[dim].length) {
        top = kbDims[dim].reduce((a, b) => (((b && b.level) || 0) > (((a && a.level) || 0)) ? b : a)).name;
      }
      if (top && String(top).toLowerCase() !== String(member || "").toLowerCase()) {
        chips.push(`Total ${dim} (${top}) → change POV ${dim} to ${top}`);
      }
      if (chips.length >= 5) break;
    }
    return chips;
  } catch (_) { return []; }
}

// ── modify_grid: full SmartView-style navigation on the last grid ────────────
// Works on descriptors from BOTH origins:
//  - build_adhoc grids: rowAxis entries are SEEDS ({dimension, fn, member})
//  - form-origin grids (open_form synthesizes the descriptor): entries carry
//    EXPLICIT member lists ({dimension, members:[...]})
// Actions: zoom_in / zoom_bottom / zoom_out / keep_only / change_pov (legacy)
//          add_member / remove_member (any axis; member accepts "A, B" lists)
//          pivot (move a dim between rows / columns / pov)
async function runModifyGrid(settings, catalog, lastGrid, args) {
  if (!lastGrid) {
    throw new Error("No current grid to modify. Ask for data first (e.g. 'revenue by month') or open a form.");
  }
  const action = args && args.action;
  const target = (args && args.target) || {};
  if (!action) throw new Error("modify_grid: action required");
  // swap_axes / refresh are whole-grid actions — everything else targets a dim.
  if (!target.dim && action !== "swap_axes" && action !== "refresh") throw new Error("modify_grid: target.dim required");

  const { cube } = lastGrid;
  const rowAxis = (lastGrid.rowAxis || []).map(r => ({
    ...r, members: Array.isArray(r.members) ? r.members.slice() : undefined
  }));
  const colAxis = (lastGrid.colAxis || []).map(c => ({
    dimension: c.dimension, members: (c.members || []).slice()
  }));
  const pov = { ...(lastGrid.pov || {}) };
  const dim = target.dim;
  // The schema keeps target.member a plain string — "FY25, FY26" splits here.
  const memberList = String(target.member || "").split(",").map(s => s.trim()).filter(Boolean);
  const member = memberList[0] || "";

  const rowIdx = () => rowAxis.findIndex(r => r.dimension === dim);
  const colIdx = () => colAxis.findIndex(c => c.dimension === dim);
  const isExplicit = (e) => Array.isArray(e.members) && e.members.length > 0;
  // Resolve an axis entry to its explicit member list — server-side REST
  // expansion for seed+fn entries (pivot / add / remove need real lists).
  // Probe hint for member expansion: the descriptor's POV plus ONE member of
  // every axis dim — Oracle's exportdataslice needs EVERY dim of the cube
  // represented, and axis dims (e.g. Account on columns) are neither in the
  // POV nor guaranteed a config default.
  const probeHint = { ...pov };
  for (const e of rowAxis.concat(colAxis)) {
    if (!probeHint[e.dimension]) {
      const m = Array.isArray(e.members) ? e.members[0] : e.member;
      if (m) probeHint[e.dimension] = m;
    }
  }
  const toExplicit = async (e) => {
    if (isExplicit(e)) return e.members.slice();
    const fn = normalizeFn(e.fn);
    if (fn === "Member") return [e.member];
    return await resolveRowMembers(settings, cube, e.dimension, `${fn}(${e.member})`, probeHint);
  };
  const parentOf = (m) => {
    const dimCatalog = (catalog && catalog[dim]) || [];
    const entry = dimCatalog.find(x => x.name === m);
    return (entry && entry.parent) || null;
  };

  let needsExpand = false;

  if (action === "zoom_in" || action === "zoom_bottom") {
    // zoom_in = one level down (Children); zoom_bottom = leaves (ILvl0).
    const fn = action === "zoom_bottom" ? "ILvl0Descendants" : "Children";
    const idx = rowIdx();
    if (idx < 0) {
      // Dim was in POV or on columns — promote to rows starting at the seed.
      const cIdx = colIdx();
      const seed = member || pov[dim] || (cIdx >= 0 ? colAxis[cIdx].members[0] : "");
      if (!seed) throw new Error(`${action}: no seed for ${dim} (not in rows/columns/pov)`);
      if (cIdx >= 0) {
        if (colAxis.length === 1) throw new Error(`${action}: can't move the last column dimension to rows`);
        colAxis.splice(cIdx, 1);
      }
      delete pov[dim];
      rowAxis.push({ dimension: dim, fn, member: seed });
      needsExpand = true;
    } else if (isExplicit(rowAxis[idx]) && member) {
      // Explicit list (form-origin): inline SmartView-style zoom — replace
      // the member with itself + its children/leaves, keep the rest intact.
      const kids = await resolveRowMembers(settings, cube, dim, `${fn}(${member})`, probeHint);
      const list = rowAxis[idx].members;
      const at = list.findIndex(m => m.toLowerCase() === member.toLowerCase());
      const inline = [member].concat(kids.filter(k => k !== member));
      if (at >= 0) list.splice(at, 1, ...inline);
      else list.push(...inline);
      rowAxis[idx] = { dimension: dim, members: [...new Set(list)] };
    } else {
      rowAxis[idx] = {
        dimension: dim,
        fn,
        member: member || rowAxis[idx].member || (rowAxis[idx].members || [])[0]
      };
      needsExpand = true;
    }
  } else if (action === "zoom_out") {
    const idx = rowIdx();
    if (idx < 0) throw new Error(`zoom_out: ${dim} is not on rows`);
    const e = rowAxis[idx];
    if (isExplicit(e)) {
      // Collapse: replace the member's sibling block with the parent.
      const m = member || e.members[0];
      const parent = parentOf(m);
      if (!parent) throw new Error(`zoom_out: no parent for ${m} in ${dim} — run the Discover buttons so the member catalog loads, or name the parent explicitly`);
      const dimCatalog = (catalog && catalog[dim]) || [];
      const siblings = new Set(dimCatalog.filter(x => x.parent === parent).map(x => x.name));
      const at = e.members.findIndex(x => siblings.has(x) || x === parent);
      const kept = e.members.filter(x => !siblings.has(x) && x !== parent);
      kept.splice(Math.max(0, at), 0, parent);
      rowAxis[idx] = { dimension: dim, members: kept };
    } else {
      const cur = e.member;
      const parent = parentOf(cur);
      if (!parent) throw new Error(`zoom_out: no parent for ${cur} in ${dim} (catalog missing?)`);
      rowAxis[idx] = { dimension: dim, fn: "Member", member: parent };
    }
  } else if (action === "keep_only") {
    if (!member) throw new Error("keep_only: target.member required");
    const idx = rowIdx(), cIdx = colIdx();
    if (idx >= 0)       rowAxis[idx] = { dimension: dim, members: memberList.slice() };
    else if (cIdx >= 0) colAxis[cIdx] = { dimension: dim, members: memberList.slice() };
    else throw new Error(`keep_only: ${dim} is not on rows or columns`);
  } else if (action === "remove_member") {
    if (!member) throw new Error("remove_member: target.member required");
    const idx = rowIdx(), cIdx = colIdx();
    const drop = new Set(memberList.map(m => m.toLowerCase()));
    if (idx >= 0) {
      const list = (await toExplicit(rowAxis[idx])).filter(m => !drop.has(m.toLowerCase()));
      if (!list.length) throw new Error(`remove_member: that would leave ${dim} empty — pivot the dim to POV instead`);
      rowAxis[idx] = { dimension: dim, members: list };
    } else if (cIdx >= 0) {
      const list = colAxis[cIdx].members.filter(m => !drop.has(m.toLowerCase()));
      if (!list.length) throw new Error(`remove_member: that would leave ${dim} empty — pivot the dim to POV instead`);
      colAxis[cIdx] = { dimension: dim, members: list };
    } else throw new Error(`remove_member: ${dim} is not on rows or columns`);
  } else if (action === "add_member") {
    if (!member) throw new Error("add_member: target.member required");
    const idx = rowIdx(), cIdx = colIdx();
    const pushUnique = (list, ms) => {
      for (const m of ms) if (!list.some(x => x.toLowerCase() === m.toLowerCase())) list.push(m);
      return list;
    };
    if (idx >= 0) {
      rowAxis[idx] = { dimension: dim, members: pushUnique(await toExplicit(rowAxis[idx]), memberList) };
    } else if (cIdx >= 0) {
      colAxis[cIdx] = { dimension: dim, members: pushUnique(colAxis[cIdx].members.slice(), memberList) };
    } else if (pov[dim]) {
      // Dim sits in POV — "add FY25" means POV member + the new ones
      // side-by-side: move the dim onto columns.
      const list = pushUnique([pov[dim]], memberList);
      delete pov[dim];
      colAxis.push({ dimension: dim, members: list });
    } else {
      throw new Error(`add_member: ${dim} is not on this grid (rows/columns/pov) — check the dimension name against CURRENT GRID`);
    }
  } else if (action === "pivot") {
    const to = String((args && args.to) || target.to || "").toLowerCase();
    if (to !== "rows" && to !== "columns" && to !== "pov") {
      throw new Error("pivot: `to` must be rows | columns | pov");
    }
    const idx = rowIdx(), cIdx = colIdx();
    let members = null;
    if (idx >= 0) {
      if (rowAxis.length === 1 && to !== "rows") throw new Error("pivot: can't move the last row dimension off the rows");
      members = await toExplicit(rowAxis[idx]);
      rowAxis.splice(idx, 1);
    } else if (cIdx >= 0) {
      if (colAxis.length === 1 && to !== "columns") throw new Error("pivot: can't move the last column dimension off the columns");
      members = colAxis[cIdx].members.slice();
      colAxis.splice(cIdx, 1);
    } else if (pov[dim]) {
      members = [pov[dim]];
      delete pov[dim];
    } else {
      throw new Error(`pivot: ${dim} is not on this grid`);
    }
    // Optional position: where the dim lands on the destination axis
    // ("nest Currency inside Department" = rows position 1). Defaults to end.
    const posRaw = (args && args.position);
    const pos = Number.isFinite(Number(posRaw)) && posRaw !== "" && posRaw !== null && posRaw !== undefined
      ? Math.max(0, Math.trunc(Number(posRaw))) : null;
    const insert = (axis, entry) => {
      if (pos === null || pos >= axis.length) axis.push(entry);
      else axis.splice(pos, 0, entry);
    };
    if (to === "rows")         insert(rowAxis, { dimension: dim, members });
    else if (to === "columns") insert(colAxis, { dimension: dim, members });
    else                       pov[dim] = member || members[0];
  } else if (action === "swap_axes") {
    // Transpose: every row dim goes to columns and vice versa, members intact.
    // ("da vuelta filas y columnas", "transpose", "swap rows and columns")
    const newCols = [];
    for (const r of rowAxis) newCols.push({ dimension: r.dimension, members: await toExplicit(r) });
    const newRows = colAxis.map(c => ({ dimension: c.dimension, members: c.members.slice() }));
    if (!newRows.length || !newCols.length) throw new Error("swap_axes: both axes need at least one dimension");
    rowAxis.length = 0; rowAxis.push(...newRows);
    colAxis.length = 0; colAxis.push(...newCols);
  } else if (action === "change_pov") {
    if (!member) throw new Error("change_pov: target.member required");
    pov[dim] = member;
  } else if (action === "refresh") {
    // Re-execute the descriptor unchanged — "retrieve" / "refresh" after
    // edits elsewhere, or just to re-pull live data.
  } else {
    throw new Error("modify_grid: unknown action " + action);
  }
  // Reuse the original sheet name so modify_grid updates the existing sheet
  // in place instead of spawning "Plan zoom_in", "Plan zoom_bottom", etc.
  // The client side flips on `inPlace` to clear+rewrite rather than add a sheet.
  const out = await runBuildAdhoc(settings, {
    cube,
    sheet_name: lastGrid.sheetName || `${cube} ${action}`,
    rows: rowAxis,
    columns: colAxis,
    pov,
    removeZeros: !!(args && args.removeZeros),
    pctOfTotal:  !!(args && args.pctOfTotal)
  }, { expandRows: needsExpand });
  out.inPlace = true;
  return out;
}

// ── compare_grid: two-sided scenario comparison with variance column ────────
// Runs runBuildAdhoc N times (one POV per side, same row/col shape) and merges
// the resulting grids cell-by-cell. Row labels + column headers come from the
// first grid. Each data column becomes:
//   N=2: <orig> (A) | (B) | Δ | [%Δ]
//   N=3: <orig> (A) | (B) | (C) | Δ(A-B) | Δ(A-C) | [%Δ(A-B)] | [%Δ(A-C)]
async function runCompareGrid(settings, args) {
  const cube = args.cube || "Plan";
  const rows = Array.isArray(args.rows) ? args.rows : [];
  const columns = Array.isArray(args.columns) ? args.columns : [];
  const compare = args.compare || {};
  if (!rows.length)    throw new Error("compare_grid: rows required");
  if (!columns.length) throw new Error("compare_grid: columns required");
  if (!compare.dim || !compare.a || !compare.b) {
    throw new Error("compare_grid: compare.dim / compare.a / compare.b all required");
  }
  const basePov = args.basePov || {};
  const showPct = compare.showPct !== false;  // default true
  const threeWay = !!compare.c;

  // Expand row axis for ALL sides so they align by index. Row expansion is
  // a deterministic function of rows/cube (no scenario dependency), so every
  // side gets the same row list.
  const sides = [
    { label: compare.a, pov: { ...basePov, [compare.dim]: compare.a } },
    { label: compare.b, pov: { ...basePov, [compare.dim]: compare.b } }
  ];
  if (threeWay) {
    sides.push({ label: compare.c, pov: { ...basePov, [compare.dim]: compare.c } });
  }

  const fetched = [];
  for (const side of sides) {
    const out = await runBuildAdhoc(settings, {
      cube, sheet_name: args.sheet_name, rows, columns, pov: side.pov
    }, { expandRows: true, rawLayout: false });   // merge needs the original header block
    fetched.push({ grid: out.grid, label: side.label, debug: out.debug, gridDescriptor: out.gridDescriptor });
  }

  const numRowLabelCols = rows.length;
  const merged = mergeGridsForCompare(fetched, { numRowLabelCols, showPct });

  // Filter zero rows AFTER merge so the variance column is considered too.
  let finalMerged = args.removeZeros ? dropZeroRows(merged) : merged;
  if (args.pctOfTotal) {
    // Anchor % of Total to side A's last data col. perGroup tells us how many
    // sub-cols each period contributes; col 0 of the LAST group is the A value
    // of the last period (typically YearTotal).
    const N = fetched.length;
    const perGroup = N + (N - 1) + (showPct ? (N - 1) : 0);
    const dataCols = (finalMerged[0] || []).length - numRowLabelCols;
    const groups = perGroup > 0 ? Math.floor(dataCols / perGroup) : 0;
    const baseCol = numRowLabelCols + (groups - 1) * perGroup;  // A of last period
    finalMerged = appendPctOfTotal(finalMerged, { numRowLabelCols, baseCol });
  }

  const sheetName = (args.sheet_name ||
                     `${cube} ${compare.a}_vs_${compare.b}${threeWay ? `_vs_${compare.c}` : ""}`).slice(0, 30);
  return {
    sheetName,
    grid: finalMerged,
    gridDescriptor: {
      cube,
      sheetName,
      kind: "compare",
      pov: { ...(fetched[0].gridDescriptor && fetched[0].gridDescriptor.pov) },
      rowAxis: rows.map(r => ({ dimension: r.dimension, fn: r.fn || "Member", member: r.member })),
      colAxis: columns.map(c => ({ dimension: c.dimension, members: c.members.slice() })),
      compare: { dim: compare.dim, a: compare.a, b: compare.b, c: compare.c, showPct },
      asOf: Date.now()
    },
    debug: fetched.map(f => f.debug)
  };
}

// Align N 2D grids of identical shape and emit one wide grid:
//   N=2: A | B | Δ | [%Δ] per period.
//   N=3: A | B | C | Δ(A-B) | Δ(A-C) | [%Δ(A-B) | %Δ(A-C)] per period.
// `grids` = [{grid, label}, ...]. Row labels + header rows come from grids[0].
// Numeric cells cast to Number for arithmetic; text cells survive as strings.
function mergeGridsForCompare(grids, opts) {
  const { numRowLabelCols, showPct } = opts;
  if (!Array.isArray(grids) || grids.length < 2) {
    return grids && grids[0] ? grids[0].grid : [];
  }
  const N = grids.length;
  const gridA = grids[0].grid;
  const labelA = grids[0].label;
  if (!gridA.length) return gridA;

  const numRows = Math.min(...grids.map(g => g.grid.length));
  const numCols = Math.min(...grids.map(g => g.grid[0].length));
  const dataCols = numCols - numRowLabelCols;
  if (dataCols <= 0) return gridA;

  // Detect how many rows are column headers (same heuristic as before).
  let headerRowCount = 0;
  for (let r = 0; r < numRows; r++) {
    let hasNumber = false;
    for (let c = numRowLabelCols; c < numCols; c++) {
      if (typeof gridA[r][c] === "number") { hasNumber = true; break; }
    }
    if (hasNumber) { headerRowCount = r; break; }
    if (r === numRows - 1) headerRowCount = numRows;
  }

  const perGroup = N + (N - 1) + (showPct ? (N - 1) : 0);
  // Slot semantics within each period group:
  //   [0..N-1]                    → original values from each side
  //   [N..N+(N-2)]                → Δ values (A - others), N-1 cells
  //   [N+(N-1)..N+(N-1)+(N-2)]    → %Δ values if showPct
  const out = [];
  for (let r = 0; r < numRows; r++) {
    const row = new Array(numRowLabelCols + dataCols * perGroup);
    for (let c = 0; c < numRowLabelCols; c++) row[c] = gridA[r][c];

    for (let j = 0; j < dataCols; j++) {
      const srcCol = numRowLabelCols + j;
      const cells = grids.map(g => g.grid[r][srcCol]);
      const aCell = cells[0];
      const base  = numRowLabelCols + j * perGroup;

      if (r < headerRowCount) {
        if (r === headerRowCount - 1) {
          // Skip the "null"/empty prefix when source cell has no label —
          // otherwise we'd get "null (Actual)" / "null Δ" in the sub-header.
          const aStr = (aCell == null || aCell === "") ? null : String(aCell);
          // Original-value labels: "<period> (Actual)" or just "Actual".
          for (let i = 0; i < N; i++) {
            const suffix = " (" + grids[i].label + ")";
            row[base + i] = aStr ? aStr + suffix : grids[i].label;
          }
          // Δ labels: 2-way uses simple "Δ"; 3+-way disambiguates "Δ(A-B)".
          for (let i = 1; i < N; i++) {
            const slot = N + (i - 1);
            const tag = (N === 2) ? "\u0394" : `\u0394(${labelA}-${grids[i].label})`;
            row[base + slot] = aStr ? aStr + " " + tag : tag;
          }
          // %Δ labels — same disambiguation rule.
          if (showPct) {
            for (let i = 1; i < N; i++) {
              const slot = N + (N - 1) + (i - 1);
              const tag = (N === 2) ? "%\u0394" : `%\u0394(${labelA}-${grids[i].label})`;
              row[base + slot] = aStr ? aStr + " " + tag : tag;
            }
          }
        } else {
          // Upper header rows — repeat aCell across every slot for visual span.
          for (let i = 0; i < perGroup; i++) row[base + i] = aCell;
        }
      } else {
        // Data rows — coerce each side's value to a Number for arithmetic.
        const nums = cells.map(v => typeof v === "number" ? v : Number(v));
        const oks  = nums.map(n => Number.isFinite(n));
        // Original values
        for (let i = 0; i < N; i++) row[base + i] = oks[i] ? nums[i] : cells[i];
        // Δ(A - others)
        for (let i = 1; i < N; i++) {
          const slot = N + (i - 1);
          row[base + slot] = (oks[0] && oks[i]) ? (nums[0] - nums[i]) : "";
        }
        // %Δ((A - other)/other)
        if (showPct) {
          for (let i = 1; i < N; i++) {
            const slot = N + (N - 1) + (i - 1);
            row[base + slot] = (oks[0] && oks[i] && nums[i] !== 0) ? ((nums[0] - nums[i]) / nums[i]) : "";
          }
        }
      }
    }
    out.push(row);
  }
  return out;
}

// ── top_drivers: rank leaves of one dim, slice top N ─────────────────────────
async function runTopDrivers(settings, args) {
  const cube = args.cube || "Plan";
  const rankDim = args.rankDim;
  const rankSeed = args.rankSeed;
  const columns = Array.isArray(args.columns) ? args.columns : [];
  const topN = Math.max(1, Math.min(100, args.topN || 10));
  const pov = args.pov || {};
  const byVariance = args.byVariance;

  if (!rankDim || !rankSeed) throw new Error("top_drivers: rankDim and rankSeed required");
  if (!columns.length)       throw new Error("top_drivers: columns required (Period)");

  // Single leaf-expanded row.
  const rows = [{ dimension: rankDim, fn: "ILvl0Descendants", member: rankSeed }];

  let grid, numRowLabelCols, descriptorBase;
  if (byVariance && byVariance.dim && byVariance.a && byVariance.b) {
    const cmp = await runCompareGrid(settings, {
      cube,
      sheet_name: args.sheet_name,
      rows, columns,
      basePov: pov,
      compare: { dim: byVariance.dim, a: byVariance.a, b: byVariance.b, showPct: true }
    });
    grid = cmp.grid;
    numRowLabelCols = 1;
    descriptorBase = cmp.gridDescriptor;
  } else {
    const base = await runBuildAdhoc(settings, {
      cube,
      sheet_name: args.sheet_name,
      rows, columns, pov
    }, { expandRows: true, rawLayout: false });   // top_drivers post-processes the original layout
    grid = base.grid;
    numRowLabelCols = 1;
    descriptorBase = base.gridDescriptor;
  }

  // Pick the measure column index. If user passed `measure`, find it in the
  // header row; else use the last column (typically YearTotal).
  const totalCols = grid[0] ? grid[0].length : 0;
  let measureColIdx = totalCols - 1;
  const measureTerm = args.measure;
  if (measureTerm) {
    // Search all header rows for a cell equal (or starting with) the measure.
    outer: for (let r = 0; r < grid.length; r++) {
      for (let c = numRowLabelCols; c < totalCols; c++) {
        const v = String(grid[r][c] || "").trim();
        if (v === measureTerm || v.startsWith(measureTerm + " ") || v.startsWith(measureTerm + "(")) {
          measureColIdx = c;
          break outer;
        }
      }
    }
  }
  // For variance mode, prefer the Δ column (suffix " Δ") of the measure.
  if (byVariance && measureTerm == null) {
    for (let r = 0; r < grid.length; r++) {
      for (let c = numRowLabelCols; c < totalCols; c++) {
        const v = String(grid[r][c] || "");
        if (v.endsWith(" \u0394")) { measureColIdx = c; break; }
      }
    }
  }

  const ranked = rankAndSlice(grid, {
    numRowLabelCols,
    measureColIdx,
    topN,
    absolute: !!byVariance
  });

  // Optional zero-row filter — applied AFTER rank so the Others subtotal is
  // kept (detectTotalRows logic in dropZeroRows treats it as a total row).
  let finalRanked = args.removeZeros ? dropZeroRows(ranked) : ranked;
  if (args.pctOfTotal) {
    // Anchor % of Total to the measure column (what we ranked by) rather than
    // the trailing col, so "top 10 by Q1 revenue + % of total" reads correctly.
    finalRanked = appendPctOfTotal(finalRanked, { numRowLabelCols, baseCol: measureColIdx });
  }

  const sheetName = (args.sheet_name || `Top ${topN} ${rankDim}`).slice(0, 30);
  return {
    sheetName,
    grid: finalRanked,
    gridDescriptor: {
      ...(descriptorBase || {}),
      sheetName,
      kind: "top_drivers",
      rankDim, rankSeed, topN,
      byVariance: byVariance || null,
      asOf: Date.now()
    },
    debug: { measureColIdx, topN, absolute: !!byVariance }
  };
}

// Find the header-row count, sort data rows by `measureColIdx` descending
// (or by |value| if absolute), slice to topN, append a "Subtotal (others)"
// row summing the tail.
function rankAndSlice(grid, opts) {
  const { numRowLabelCols, measureColIdx, topN, absolute } = opts;
  if (!grid.length) return grid;

  // Same header-row detection as mergeGridsForCompare.
  const numCols = grid[0].length;
  let headerRowCount = 0;
  for (let r = 0; r < grid.length; r++) {
    let hasNumber = false;
    for (let c = numRowLabelCols; c < numCols; c++) {
      if (typeof grid[r][c] === "number") { hasNumber = true; break; }
    }
    if (hasNumber) { headerRowCount = r; break; }
    if (r === grid.length - 1) headerRowCount = grid.length;
  }

  const header = grid.slice(0, headerRowCount);
  const data = grid.slice(headerRowCount);

  const scored = data.map(row => {
    const v = row[measureColIdx];
    const n = typeof v === "number" ? v : Number(v);
    return { row, key: Number.isFinite(n) ? (absolute ? Math.abs(n) : n) : -Infinity };
  });
  scored.sort((x, y) => y.key - x.key);

  const top = scored.slice(0, topN).map(s => s.row);
  const tail = scored.slice(topN).map(s => s.row);

  // Build an "Others (subtotal)" row if there's a tail.
  if (tail.length) {
    const otherRow = new Array(numCols).fill("");
    otherRow[0] = `Others (${tail.length})`;
    for (let c = numRowLabelCols; c < numCols; c++) {
      let sum = 0, hit = false;
      for (const row of tail) {
        const v = row[c];
        const n = typeof v === "number" ? v : Number(v);
        if (Number.isFinite(n)) { sum += n; hit = true; }
      }
      otherRow[c] = hit ? sum : "";
    }
    return header.concat(top).concat([otherRow]);
  }
  return header.concat(top);
}

// ── Schema translation: Anthropic-style → Gemini functionDeclarations ────────
// Gemini rejects some JSON-Schema keywords and wants UPPERCASE types.
// Ported from Gemini.gs:207-221.
function normalizeSchemaForGemini(schema) {
  if (!schema || typeof schema !== "object") return { type: "OBJECT", properties: {} };
  const out = {};
  if (schema.type) out.type = String(schema.type).toUpperCase();
  if (schema.description) out.description = schema.description;
  if (schema.enum) out.enum = schema.enum;
  if (schema.items) out.items = normalizeSchemaForGemini(schema.items);
  if (schema.required) out.required = schema.required;
  if (schema.properties) {
    out.properties = {};
    for (const k in schema.properties) {
      out.properties[k] = normalizeSchemaForGemini(schema.properties[k]);
    }
  }
  return out;
}

// ── Gemini tool loop ─────────────────────────────────────────────────────────
// Adapter: same signature/output shape as callGemini, but routes through
// the Claude API. Translates Gemini's `contents` history → Claude `messages`
// (mapping functionCall ↔ tool_use, functionResponse ↔ tool_result by
// invented IDs since Gemini doesn't have them) and Claude's response
// content blocks → Gemini parts. After this returns, runChatTurn can keep
// processing the response in the Gemini shape it already understands.
async function callClaude(apiKey, contents, model, systemPrompt, tools, toolMode, opts) {
  // Walk the conversation, assigning sequential tool_use IDs so each
  // functionResponse can reference the matching call.
  const messages = [];
  const idQueue = []; // FIFO queue of {name, id, used}
  let nextId = 1;

  for (const c of contents) {
    if (c.role === "user") {
      const fnResponses = (c.parts || []).filter(p => p.functionResponse);
      if (fnResponses.length > 0) {
        const content = fnResponses.map(p => {
          // Match by name, oldest unused first
          const slot = idQueue.find(s => s.name === p.functionResponse.name && !s.used);
          const id = slot ? (slot.used = true, slot.id) : ("toolu_" + (nextId++));
          const result = (p.functionResponse.response && p.functionResponse.response.result !== undefined)
            ? p.functionResponse.response.result
            : p.functionResponse.response;
          return {
            type: "tool_result",
            tool_use_id: id,
            content: typeof result === "string" ? result : JSON.stringify(result)
          };
        });
        messages.push({ role: "user", content });
      } else {
        const txt = (c.parts || []).map(p => p.text || "").join("").trim();
        if (txt) messages.push({ role: "user", content: txt });
      }
    } else if (c.role === "model") {
      const content = [];
      // Re-inject thinking blocks from a previous turn so Claude maintains
      // coherence across multi-turn tool-calling loops. They are stored as a
      // synthetic { _thinkingBlocks: [...] } part — invisible to Gemini path.
      const thinkPart = (c.parts || []).find(p => p._thinkingBlocks);
      if (thinkPart) {
        for (const tb of thinkPart._thinkingBlocks) {
          content.push(tb); // {type:"thinking"|"redacted_thinking", ...}
        }
      }
      for (const p of (c.parts || [])) {
        if (p._thinkingBlocks) continue; // synthetic storage part — skip
        if (p.text && p.text.trim()) {
          content.push({ type: "text", text: p.text });
        } else if (p.functionCall) {
          const id = "toolu_" + (nextId++);
          idQueue.push({ name: p.functionCall.name, id, used: false });
          content.push({
            type: "tool_use",
            id,
            name: p.functionCall.name,
            input: p.functionCall.args || {}
          });
        }
      }
      if (content.length > 0) messages.push({ role: "assistant", content });
    }
  }

  // Our TOOLS already use `input_schema` (Claude's native name), so pass
  // through. Gemini's path normalizes them; Claude takes them as-is.
  const claudeTools = (tools || []).map(t => ({
    name: t.name,
    description: t.description,
    input_schema: t.input_schema
  }));

  // Extended thinking — enabled when opts.thinking === true.
  // Requires: budget_tokens < max_tokens, temperature = 1, beta header.
  // Only supported on Sonnet/Opus — never on Haiku.
  const useThinking = !!(opts && opts.thinking);
  const maxTokens = useThinking ? 16000 : ((opts && opts.maxTokens) || GEMINI_MAX_TOKENS);
  const body = {
    model,
    max_tokens: maxTokens,
    temperature: useThinking ? 1 : 0.2,
    system: systemPrompt,
    messages,
    tools: claudeTools
  };
  if (useThinking) {
    body.thinking = { type: "enabled", budget_tokens: 10000 };
  }
  // Gemini "ANY" → force a tool call. Claude equivalent: tool_choice {type:"any"}.
  if (toolMode === "ANY") body.tool_choice = { type: "any" };

  const fetchHeaders = {
    "Content-Type": "application/json",
    "x-api-key": apiKey,
    "anthropic-version": CLAUDE_API_VERSION
  };
  // interleaved-thinking lets extended thinking work alongside tool use.
  if (useThinking) fetchHeaders["anthropic-beta"] = "interleaved-thinking-2025-05-14";

  const resp = await fetch(CLAUDE_API_URL, {
    method: "POST",
    headers: fetchHeaders,
    body: JSON.stringify(body)
  });
  const text = await resp.text();
  if (!resp.ok) throw new Error(`Claude ${resp.status}: ${text.slice(0, 600)}`);
  const j = JSON.parse(text);

  // Translate Claude response → Gemini shape ({candidates:[{content:{parts},finishReason}]})
  // Thinking blocks are collected separately and returned as _thinkingBlocks so
  // runChatTurn can store them in `contents` for the next turn (required by the
  // interleaved-thinking beta — all assistant content blocks must round-trip).
  const parts = [];
  const thinkingBlocks = [];
  for (const block of (j.content || [])) {
    if (block.type === "thinking" || block.type === "redacted_thinking") {
      thinkingBlocks.push(block);
      continue; // don't expose internal reasoning as output text
    }
    if (block.type === "text" && block.text) {
      parts.push({ text: block.text });
    } else if (block.type === "tool_use") {
      parts.push({
        functionCall: { name: block.name, args: block.input || {} }
      });
    }
  }
  let finishReason = "STOP";
  if (j.stop_reason === "max_tokens") finishReason = "MAX_TOKENS";
  return {
    candidates: [{ content: { role: "model", parts }, finishReason }],
    usageMetadata: j.usage || null,
    _thinkingBlocks: thinkingBlocks.length > 0 ? thinkingBlocks : null
  };
}

async function callGemini(apiKey, contents, model, systemPrompt, tools, toolMode, opts) {
  const url = GEMINI_API_BASE + encodeURIComponent(model) +
              ":generateContent?key=" + encodeURIComponent(apiKey);
  const functionDeclarations = (tools || []).map(t => ({
    name: t.name,
    description: t.description,
    parameters: normalizeSchemaForGemini(t.input_schema)
  }));
  // Output cap is the dominant latency factor (Gemini generates token-by-token).
  // For EXPLAIN MODE we cap at 1500 tokens — enough for ~700 words of prose +
  // 4 chips, which is plenty for a tip / FAQ teaching answer. Cuts 8s → ~4s.
  const maxTokens = (opts && opts.maxTokens) || GEMINI_MAX_TOKENS;
  // 2.5 models: THINKING tokens count against maxOutputTokens. Left
  // unbounded, Pro can burn the entire budget reasoning and return EMPTY
  // content (finish=MAX_TOKENS, "no tool invoked", 30+s wasted). Cap the
  // thinking — tool routing doesn't need deep deliberation.
  const isPro = /pro/i.test(String(model));
  const thinkingBudget = (opts && opts.thinkingBudget != null)
    ? opts.thinkingBudget
    : (isPro ? 2048 : 512);
  const payload = {
    systemInstruction: { parts: [{ text: systemPrompt }] },
    contents,
    generationConfig: {
      maxOutputTokens: maxTokens,
      temperature: 0.2,
      thinkingConfig: { thinkingBudget }
    }
  };
  // Only attach tools / toolConfig when we actually have function declarations.
  // EXPLAIN MODE passes tools=[] — Gemini rejects an empty functionDeclarations
  // array with "Function calling config is set without function_declarations."
  if (functionDeclarations.length) {
    payload.tools = [{ functionDeclarations }];
    // "ANY" forces Gemini to pick one of the provided tools on this turn —
    // prevents the "Done." failure where it replies empty prose instead of
    // calling a tool. Used on turn 0 only; follow-up turns (tool responses)
    // use the default "AUTO" so the model can stop when it has an answer.
    if (toolMode) {
      payload.toolConfig = { functionCallingConfig: { mode: toolMode } };
    }
  }
  const resp = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  });
  const text = await resp.text();
  if (!resp.ok) throw new Error(`Gemini ${resp.status}: ${text.slice(0, 600)}`);
  const out = JSON.parse(text);
  // One automatic retry when thinking still ate the whole budget: double the
  // output cap, halve the thinking, so the user never sees a 30s empty turn.
  try {
    const c0 = out.candidates && out.candidates[0];
    const parts0 = c0 && c0.content && c0.content.parts;
    const hasUseful = Array.isArray(parts0) && parts0.some(p => p.functionCall || (p.text && String(p.text).trim()));
    if (c0 && c0.finishReason === "MAX_TOKENS" && !hasUseful && !(opts && opts._maxTokRetry)) {
      console.log("[GEMINI_MAXTOK_RETRY]", model, "budget:", maxTokens, "thinking:", thinkingBudget);
      return await callGemini(apiKey, contents, model, systemPrompt, tools, toolMode, {
        ...(opts || {}),
        maxTokens: Math.max(maxTokens * 2, 8192),
        thinkingBudget: Math.min(thinkingBudget, 1024),
        _maxTokRetry: true
      });
    }
  } catch (_) {}
  return out;
}

function lastUserText(history) {
  for (let i = history.length - 1; i >= 0; i--) {
    if (history[i].role === "user") return history[i].content || "";
  }
  return "";
}

// Cap CHIP: lines to N total in a reply string. Keeps the first N in
// document order and drops the rest. Per user feedback: never surface
// more than ~6 chips at once — past that it's visual noise, not help.
function capChipsInText(text, maxChips) {
  if (!text) return text;
  const max = Math.max(0, maxChips | 0);
  let seen = 0;
  return text.replace(/^\s*CHIP:.*$/gm, (m) => {
    seen++;
    return seen <= max ? m : "";
  }).replace(/\n{3,}/g, "\n\n");
}

async function runChatTurn({ geminiKey, nspbSettings, userMessages, catalog, lastGrid, businessRules = null, forms = null, variables = null, jobs = null, appConfig = null, glossary = null, activeSheet = null, tenantKb = null, debug = false, forceExplain = false, adaptMode = false, language = "en" }) {
  if (!geminiKey) throw new Error("AI API key missing — open Settings in the task pane.");
  const provider = detectProvider(geminiKey);
  if (provider !== "gemini" && provider !== "claude") {
    throw new Error("AI key not recognized — must start with AIza (Gemini) or sk-ant- (Claude).");
  }

  // ── EXPLAIN INTERCEPT (force tool call, bypass Gemini routing) ────
  // User-reported: even with strict system prompts, the AI sometimes
  // skips the explain tool and answers from generic Hyperion knowledge
  // ("I don't have specific information about X..."). Solution: detect
  // 'explain <noun> <name>' messages at the worker entry and invoke
  // runExplain directly. Then we pass the structured result to Gemini
  // and ask ONLY for a short synthesis — no chance to bypass.
  //
  // This is the same anti-hallucination pattern we use for force-call
  // tools elsewhere; for explain it's especially important because the
  // user often types short forms ("explain rule X") that don't carry
  // enough verbal pressure for the AI to recognize as a tool trigger.
  const lastUserMsg = lastUserText(userMessages) || "";

  // ── COPY/SAVE VERSION INTERCEPT (no REST endpoint exists) ────────
  // There is no clean "copy version" REST API in Planning — it's done in
  // the web console (Copy Data / Copy Version) or via a Copy-Data rule.
  // For v1 we guide the user instead of building it. The aggregation
  // afterwards CAN be run from the chat via `run rule <AggRule>`.
  const copyVerMatch = /\b(copy|create|save|new|guardar|crear|nueva|copiar)\s+(a\s+)?(version|versi[oó]n)\b|\bcopy\s+data\s+(version|across)\b|\bguardar\s+(forecast|budget|pron[oó]stico)\b/i.test(lastUserMsg);
  if (copyVerMatch && !adaptMode && !/^\s*explain\b/i.test(lastUserMsg)) {
    const es = (language || "").toLowerCase().startsWith("es");
    const reply = es
      ? "Para **guardar/copiar una versión** de Forecast o Budget no hay un endpoint directo — se hace en la **Web Console de Planning**:\n\n" +
        "1. Andá a **Web Console → Copy Version** (o **Copy Data**).\n" +
        "2. Completá las 3 cosas:\n" +
        "   • **Versión origen** (de dónde copiás)\n" +
        "   • **Versión destino** (a dónde)\n" +
        "   • **Scope / POV** — Scenario + Año (y cualquier dim que quieras acotar).\n" +
        "3. Ejecutá. Después, para consolidar, corré la regla de agregación desde acá: `run rule <AggRule>` (la regla Agg/CALC DIM que existe en tu app).\n\n" +
        "_Cuando confirmes el nombre exacto de tu regla Agg, te la dejo lista para disparar._"
      : "There's no direct REST endpoint to **copy/save a version** of Forecast or Budget — it's done in the **Planning Web Console**:\n\n" +
        "1. Go to **Web Console → Copy Version** (or **Copy Data**).\n" +
        "2. Provide the 3 things:\n" +
        "   • **Source version** (copy from)\n" +
        "   • **Target version** (copy to)\n" +
        "   • **Scope / POV** — Scenario + Year (plus any dimension you want to limit).\n" +
        "3. Run it. Then, to consolidate, run the aggregation rule from here: `run rule <AggRule>` (the Agg / CALC DIM rule that exists in your app).\n\n" +
        "_Once you confirm your exact Agg rule name, I'll wire it up so you can fire it directly._";
    return {
      reply,
      grids: [],
      actions: [],
      model: "intercept:copy-version",
      gridDescriptor: null,
      trace: debug ? { intercept: "copy-version" } : null,
    };
  }

  const explainMatch = lastUserMsg.match(/^\s*explain\s+(rule|form|account|variable|var|sub\s*var)\s+(.+?)(\s+—\s+walk\s+me\s+through.*)?$/i);
  // Intercept fires regardless of forceExplain: this regex matches a very
  // specific 'explain <noun> <name>' pattern that always wants the tool.
  // The client sets forceExplain=true for any message starting with 'explain',
  // which was overriding the intercept and letting Gemini hallucinate.
  if (explainMatch && !adaptMode) {
    const rawNoun = explainMatch[1].toLowerCase().replace(/\s+/g, "");
    const targetMap = { rule: "rule", form: "form", account: "account", variable: "variable", var: "variable", subvar: "variable" };
    const target = targetMap[rawNoun];
    const nameRaw = explainMatch[2].trim();
    const includeBody = !!explainMatch[3];
    // Strip a stray leading article/noun ("a rule", "the form")
    const name = nameRaw.replace(/^\s*(?:a|an|the|my|this|that|el|la|los|las)\s+(?:rule|form|account|variable|var)?\s*/i, "").trim();
    if (target && name) {
      const explainOut = runExplain({ target, name, includeBody }, { tenantKb, forms, appConfig });
      const fullContent = explainOut.content || "(no content)";
      // Split: structured (visible part above the '---') vs hidden context
      // (rule body + AI synthesis instructions). The structured half is
      // what the user must see; the hidden half is what Gemini reads to
      // generate the plain-English summary.
      const splitMatch = fullContent.match(/^([\s\S]*?)\n+---\s*\n+\*\*(?:AI synthesis instructions|Internal context for AI synthesis)[\s\S]*$/i);
      // structured = everything before the '---' separator if present
      // (that's where the hidden AI-synthesis context lives), otherwise
      // the whole content. We used to strip ALL code blocks in the
      // fallback path as a safety against the hidden body leaking, but
      // that also ate legitimate code blocks (dynamic calc formulas,
      // script bodies) emitted by runExplain itself. The splitMatch
      // already isolates the hidden context, so no extra stripping
      // needed.
      const structured = splitMatch ? splitMatch[1].trim() : fullContent.trim();
      const hiddenCtx = splitMatch ? fullContent.slice(splitMatch[1].length) : "";
      // CHIPs we need to surface = ones that lived inside the (now stripped)
      // hidden block. When aiSummary is cached, runExplain emits chips at
      // the top level (already inside `structured`) so we MUST NOT extract
      // them again — that's what caused the duplicate-chip bug.
      const chipLines = ((hiddenCtx || "").match(/^\s*CHIP:.*$/gmi) || []).map(l => l.trim());
      // If there's a hidden synthesis block and we have a Gemini key, call
      // Gemini ONCE with a strict prompt to synthesize what the rule/form
      // actually DOES. Ground 100% in the structured + hidden data; never
      // invent. Without this pass the user only sees metadata, not the
      // 'what does it actually do' answer they asked for.
      // Detect 'liveOnly' forms (found via live discovery but absent from
      // the LCM-parsed KB). For these the structured response itself
      // already carries an italic note explaining what's missing, AND we
      // have no rule bodies / dim metadata to ground a synthesis on —
      // running it anyway just produces speculation ('no variables
      // mentioned'). Skip synthesis entirely; the user gets the basic
      // metadata + the limitation note.
      // Detect liveOnly forms by the italic note we emit in runExplain.
      // Keep this regex in sync with the message text in the form branch.
      const isLiveOnly = /Live form \(not in the LCM parse\)|This form exists in the live tenant but was not in the LCM export/i.test(structured);
      let synthesis = "";
      if (hiddenCtx && geminiKey && !isLiveOnly) {
        try {
          const synthSystem = [
            "You are explaining a Hyperion Planning / NSPB " + target + " to a finance user.",
            "Use ONLY the data in the user message below. Never invent member names, cubes, behaviors, or rules that are not explicitly mentioned.",
            language === "es"
              ? "RESPONDE SIEMPRE EN ESPAÑOL. Mantené nombres técnicos (cube, member, rule, dim names) tal cual."
              : "Respond in the same language as the user's original question (Spanish if they wrote Spanish, English otherwise).",
            "Output ONLY a plain-English summary section (no headers like '### Rule:' — that's already shown above). Follow the format in the 'AI synthesis instructions' block inside the context.",
            "Be concise (under 200 words). Do NOT echo the raw script. Do NOT emit CHIP: lines (already shown above).",
            "If the context says 'do NOT echo this raw, summarize instead' — follow that.",
          ].join("\n");
          const synthMsg = [
            "User asked: " + lastUserMsg,
            "",
            "Structured data (already shown to user):",
            "```",
            structured,
            "```",
            "",
            "Hidden context (rule body + synthesis instructions):",
            hiddenCtx,
          ].join("\n");
          const synthProvider = detectProvider(geminiKey);
          const synthCallFn = synthProvider === "claude" ? callClaude : callGemini;
          const synthModels = getModelPair(synthProvider);
          const synthResp = await synthCallFn(
            geminiKey,
            [{ role: "user", parts: [{ text: synthMsg }] }],
            synthModels.fast,
            synthSystem,
            [],
            null,
            { maxTokens: 1500 }
          );
          const cand = synthResp && synthResp.candidates && synthResp.candidates[0];
          const parts = cand && cand.content && cand.content.parts;
          if (Array.isArray(parts)) {
            synthesis = parts.filter(p => p && typeof p.text === "string").map(p => p.text).join("").trim();
          }
        } catch (e) {
          console.log("[INTERCEPT_SYNTH_ERR]", String(e && e.message || e));
        }
      }
      // Compose the final reply: structured metadata on top, AI synthesis
      // in the middle (under a clear heading so the user knows what it is),
      // chips at the bottom.
      let reply = structured;
      if (synthesis) {
        // Strip any CHIP: lines Gemini emitted despite being told not to
        const cleanSynth = synthesis.replace(/^\s*CHIP:.*$/gmi, "").trim();
        if (cleanSynth) {
          reply += "\n\n**🧠 What this " + target + " does**\n\n" + cleanSynth;
        }
      }
      if (chipLines.length) {
        reply += "\n\n" + chipLines.join("\n");
      }
      // Final safety net: cap chips to 6 across the entire reply. Sources
      // (runExplain branches, synthesis fallback, etc.) each cap themselves,
      // but a global limit guarantees the user never sees more than 6.
      reply = capChipsInText(reply, 6);
      return {
        reply: reply.trim(),
        grids: [],
        actions: [],
        model: "intercept:explain" + (synthesis ? "+synth" : ""),
        gridDescriptor: null,
        trace: debug ? { intercept: "explain", target, name, includeBody } : null,
      };
    }
  }
  // callFn has the same signature for both providers: (apiKey, contents,
  // model, systemPrompt, tools, toolMode) → {candidates:[{content:{parts},finishReason}]}.
  const callFn = provider === "claude" ? callClaude : callGemini;
  const MODELS = getModelPair(provider);
  // Pass the user's last question so buildSystemPrompt can pull only the
  // most relevant KB sections (instead of the whole 157 KB markdown).
  let system = buildSystemPrompt(lastGrid, catalog, {
    lastUserText: lastUserText(userMessages),
    helpUrl: nspbSettings && nspbSettings.helpUrl,
    businessRules,
    forms,
    variables,
    jobs,
    appConfig,
    glossary,
    activeSheet,
    tenantKb
  });
  // Language directive — minimum-code i18n. Single line prepended to the
  // system prompt tells the model to always reply in Spanish (or whichever
  // language the user picked in Settings). UI labels stay English; only
  // AI-generated narrative + synthesis flips.
  if (language === "es") {
    system = "RESPONDE SIEMPRE EN ESPAÑOL. Toda la prosa, explicaciones, comentarios, descripciones y mensajes al usuario deben estar en español. Mantené los nombres técnicos (cube names, member names, rule names, dimension names, código en bloques `code`) tal cual aparecen en el tenant — NO los traduzcas. Solo traducí el texto narrativo.\n\n" + system;
  }
  // EXPLAIN MODE — triggered by the "Try it" button on tip/FAQ chips.
  // The user wants an EXPLANATION first, never a tool execution. We force
  // tools off and prepend a strict directive to the system prompt.
  if (forceExplain) {
    // EXPLAIN MODE uses a SLIM system prompt: KB.md + a TENANT FACTS
    // block (cubes, dim names, real variable names, sample form/rule
    // names). Tenant facts are tiny (~1-2 KB) but critical so the AI
    // doesn't suggest non-existent objects ("Plan cube", "LastClosedMonth"
    // when this tenant has NSP_NFS + NSP_PER_RptCurrMo). Without it, chips
    // hallucinate names and clicking them fails.
    const kbText = (typeof EMBED_KB !== "undefined" && EMBED_KB) ? EMBED_KB : "";
    // Build the tenant facts block from whatever's available — appConfig
    // (catalog of cubes+dims), tenantKb (forms/rules/vars), variables.
    const tenantFacts = (() => {
      const lines = [];
      const ac = appConfig || null;
      if (ac && Array.isArray(ac.cubes) && ac.cubes.length) {
        lines.push("### Cubes in this tenant");
        for (const c of ac.cubes) {
          const dims = (ac.cubeDims && ac.cubeDims[c]) || [];
          lines.push(`- **${c}** (dims: ${dims.join(", ") || "?"})`);
        }
        if (ac.mainCube) lines.push(`Main cube: **${ac.mainCube}**.`);
        if (Array.isArray(ac.scenarios) && ac.scenarios.length) {
          lines.push(`**Scenarios that EXIST:** ${ac.scenarios.join(", ")}. Do NOT mention any other scenario names.`);
        }
        if (Array.isArray(ac.versions) && ac.versions.length) {
          lines.push(`**Versions that EXIST:** ${ac.versions.join(", ")}. Do NOT invent "Base" / "Final" / "Working" if they're not listed here.`);
        }
        if (Array.isArray(ac.years) && ac.years.length) {
          lines.push(`**Years populated:** ${ac.years.slice(0, 12).join(", ")}. Do NOT mention FY30, FY33, etc. if not listed.`);
        }
        if (ac.client || ac.tenantName) {
          lines.push(`Client: ${ac.client || ac.tenantName}. Do NOT mention other clients, states, or regions in examples.`);
        }
        lines.push("");
      }
      const vars = (variables && variables.length) ? variables : ((tenantKb && tenantKb.substitutionVariables) || []);
      if (vars && vars.length) {
        const names = vars.map(v => v.name || v).filter(Boolean).slice(0, 30);
        lines.push("### Substitution variables in this tenant (real names)");
        lines.push(names.map(n => `\`${n}\``).join(", "));
        lines.push("");
      }
      const tkbForms = (tenantKb && Array.isArray(tenantKb.forms)) ? tenantKb.forms : [];
      if (tkbForms.length) {
        // Group by module so the AI can pick a topically-relevant form for chips.
        // Module prefix in the name (NFS_OpEx, NFS_Workforce, etc.) is the
        // strongest signal in NSPB-shaped tenants. Fall back to flat list.
        const byModule = new Map();
        for (const f of tkbForms) {
          if (!f.name) continue;
          const mod = (f.module || (f.name.match(/^NFS_(\w+)/i) || ["",""])[1] || "Other").trim();
          if (!byModule.has(mod)) byModule.set(mod, []);
          byModule.get(mod).push(f.name);
        }
        lines.push("### Sample forms by module (USE THESE EXACT NAMES — never invent)");
        const sortedMods = [...byModule.keys()].sort();
        for (const mod of sortedMods) {
          const names = byModule.get(mod).slice(0, 6);
          lines.push(`- **${mod}**: ${names.map(n => `\`${n}\``).join(", ")}`);
        }
        lines.push("");
        lines.push(`Total forms available: ${tkbForms.length}. To open one in chat: \`open form <ExactName>\`.`);
        lines.push("");
      }
      const tkbRules = (tenantKb && Array.isArray(tenantKb.rules)) ? tenantKb.rules : [];
      if (tkbRules.length) {
        const names = tkbRules.map(r => r.name).filter(Boolean).slice(0, 10);
        lines.push("### Sample business rules");
        lines.push(names.map(n => `\`${n}\``).join(", "));
        lines.push("");
      }
      return lines.join("\n");
    })();
    system = `**EXPLAIN MODE — STRICT.** The user clicked a "Try it" chip on a FAQ / tip card. They want you to TEACH them about this NSPB topic, not execute anything. You MUST:

1. NEVER call any tool. Do not run, execute, or open anything. Pure prose only.
2. **BE CONCISE.** Aim for 300–500 words MAX. Users read this in a tiny side panel — long walls of text get skipped. If a topic needs more depth, end with a chip suggesting the user ask a follow-up. Never repeat what you already said.
3. Start with a one-line echo of what they're asking ("You're asking about <topic>.").
4. Explain the concept clearly: what it is, why it matters, how it works in NSPB. Use short paragraphs (2–3 sentences each). Use bullet lists for steps. NO headings unless the answer truly needs them. NO sub-bullets — flatten.
5. If the topic is about an ADD-IN feature (set variable, open form, run rule, etc.), give a short step-by-step on HOW to do it from this chat (typing the command, what happens after).
6. ALWAYS close with **4–5 CHIP lines**. Three types allowed — pick based on whether the question is GENERIC (concept) or IMPLEMENTATION-specific:

   **(a) Teaching chips** — trigger another explain. Right-side MUST start with: "How to ...", "How do I ...", "What is ...", "When should I ...". Use these for concept follow-ups.

   **(b) Open form chips** — for forms that EXIST in TENANT FACTS and are relevant. Right-side MUST be exactly: \`open form <ExactFormName>\`. The form name MUST appear verbatim in the TENANT FACTS form list — never invent.

   **(c) Run rule chips** — for rules that EXIST in TENANT FACTS and are relevant. Right-side MUST be exactly: \`run rule <ExactRuleName>\`. Verbatim from TENANT FACTS rule list — never invent.

   **Question type → chip mix rule:**
   - GENERIC question (what is X, why is Y, pure concept, no tenant action implied)
     → 4-5 chips, ALL type (a) teaching follow-ups. NO open-form / run-rule chips.
   - IMPLEMENTATION question (how do I do X in this tenant, create / add / run something)
     → MIX: 2 type (a) teaching chips + 2-3 type (b)/(c) action chips with REAL names.
     E.g. for "How do I copy data between scenarios", emit:
       CHIP: Refresh DB → How do I refresh the database
       CHIP: What is DATACOPY → What is the DATACOPY function
       CHIP: Run NFS_Copy_Forecast → run rule NFS_Copy_Forecast       (only if it exists)
       CHIP: Open Forecast Setup → open form NFS_Forecast_Setup       (only if it exists)

Format strictly:

CHIP: <short label> → <command or question>
CHIP: <short label> → <command or question>
CHIP: <short label> → <command or question>
CHIP: <short label> → <command or question>

   Bad (don't do this):
   CHIP: Set CurrentMonth=TP5 → set variable CurrentMonth = TP5     ← would EXECUTE
   CHIP: Add sibling → add sibling to Total Expenses                ← feature not built
   CHIP: Open Plan IS form → open form Plan_IS                      ← INVENTED form name
   CHIP: Run rule X → run rule X                                    ← would EXECUTE without context

   Good (mix of teaching + open form, all using REAL names):
   CHIP: Open OpEx by Department → open form OpEx by Department.
   CHIP: Refresh database after change → How do I refresh the database after changing a dimension
   CHIP: Difference sibling/child → What is the difference between sibling and child in NSPB
   CHIP: Substitution variables → What is a substitution variable

   DO NOT use \`<chip>...</chip>\` HTML tags. ONLY \`CHIP: label → command\` line format.
7. Stay in English. Stay grounded in NSPB only. Refuse off-topic questions briefly.
8. **CRITICAL — USE REAL NAMES, ZERO HALLUCINATION.** Use ONLY names that appear verbatim in the TENANT FACTS section below.
   - **Cubes:** if facts say NSP_NFS, say NSP_NFS — never "Plan" generic.
   - **Variables:** if facts say NSP_PER_RptCurrMo, say that — never "CurrentMonth", "LastClosedMonth", "FcstStartMonth".
   - **Scenarios:** use ONLY the listed scenarios — never invent "Forecast0", "Forecast1", "Working".
   - **Versions:** use ONLY listed versions — never assume "Base"/"Final" exist.
   - **Years:** use only listed years (e.g. FY24/FY25/FY26) — never FY30, FY33, etc.
   - **Forms / rules:** only names in the lists below.
   - **NEVER** invent client/region examples like "Louisiana fund balance", "Florida reporting", "California rollup". The tenant has its OWN client name and dimensions — if user asks about regional/state setup, say "I don't see state-specific hierarchies in the inventory" and stop.
   - When in doubt, prefer LESS specific over MORE specific. Don't invent details to sound thorough — admit you'd need the user to clarify.

---

## TENANT FACTS — your tenant's actual cubes, dims, variables, forms, rules

Ground all examples and chip suggestions in THESE names. They're the truth for this NSPB instance.

${tenantFacts || "(no tenant inventory loaded — answer generically and suggest the user run 'Detect everything' in Settings)"}

---

## NSPB KNOWLEDGE BASE (generic)

Use this for concept explanations. If something isn't covered, say so briefly — don't invent.

${kbText}
`;
  }

  // ── ADAPT MODE — propose a column-by-column mapping from the active sheet
  //                  to a target tenant form. v1 = preview (no write). The
  //                  user reviews the mapping and clicks an Apply chip in
  //                  a later turn (v2).
  if (adaptMode) {
    const tkbForms = (tenantKb && Array.isArray(tenantKb.forms)) ? tenantKb.forms : [];
    const formsList = tkbForms.slice(0, 80).map(f => {
      const mod = f.module || (f.name && f.name.match(/^NFS_(\w+)/i) || ["",""])[1] || "Other";
      return `- \`${f.name}\` (module: ${mod}${f.cube ? `, cube: ${f.cube}` : ""}${f.isInput ? ", INPUT" : ", REVIEW"})`;
    }).join("\n");

    const sheetSnippet = activeSheet ? JSON.stringify(activeSheet).slice(0, 4000) : "(no active sheet attached)";

    system = `**ADAPT MODE — CONVERSATIONAL.** The user has an arbitrary spreadsheet (a client's payroll roster, OpEx worksheet, budget template, etc.) and wants to map it onto NSPB. Your job is to PROPOSE the mapping AND ASK FOR CONFIRMATION before any write happens. Be fail-safe: if you're unsure, say so explicitly and ask the user to confirm or correct.

There are TWO target paths — figure out which one the user wants from their phrasing:

**PATH A — "adapt to <form>" / "adapt to roster" / "adapt to OpEx forecast"**
  → Map onto an EXISTING form in the tenant. The form's dimensions become the target shape. Pick the form from the TENANT FORMS list verbatim. If the user said "to a form" without naming one, pick the closest match by topic (and SAY which one you picked, so they can correct).

**PATH B — "adapt to ad-hoc input" / "to adhoc"**
  → Build a SmartView ad-hoc pivot at LEVEL ZERO (leaf members only — never parent/aggregate members for input). The pivot is dimension-by-dimension based on what you can detect in the sheet. The user will paste it into SmartView and Refresh to push values.

The flow you MUST follow on this preview turn:

1. **Read the ACTIVE SHEET below.** Detect:
   - What data this is (payroll / opex / revenue / balance / headcount).
   - The implicit row dimension (employees? accounts? departments?).
   - What each column represents (specific accounts? months? scenarios?).
   - The implicit POV (any single value column suggests POV defaults).

2. **Identify the target.** If Path A, pick a form name VERBATIM from TENANT FORMS. If Path B, decide which cube + dims the ad-hoc will use, based on what you detected.

3. **Propose the dimension mapping** in a markdown table — be EXPLICIT about what you're sure of vs guessing:

   | Source (col / row) | NSPB dimension | Confidence | Notes |
   |---|---|---|---|
   | Col A "Name" | Employee | high | per-row resolution needed |
   | Col B "Salary" | Account | high | maps to NSP_Salaries |
   | Col C "Bonus" | Account | high | maps to NSP_Bonus |
   | Col D "Healthcare" | Account | medium | might be NSP_Healthcare_Benefits — verify |
   | Col E "Department" | Department | high | per-row, names match dim aliases |
   | (missing) | Scenario | — | **NEED USER**: Actual / Forecast / Budget? |
   | (missing) | Year | — | **NEED USER**: FY24 / FY25? |
   | (missing) | Subsidiary | — | **NEED USER**: which? (list the tenant's subsidiaries) |

4. **Sample 3-5 rows** to show what per-row member resolution will look like:
   - "John Doe" → I'd look up in Employee dim. **If not found, this is a NEW MEMBER → dim import needed first.**
   - "Salary $120,000" → NSP_Salaries cell value
   - etc.

5. **For Path B ad-hoc**, ALWAYS specify:
   - Cube name (verbatim from tenant)
   - Each dim explicitly labeled "leaf-level (level 0)" so the user knows it's input-ready
   - POV defaults you'll fill in (and call out which the user MUST confirm)

6. **End with 4-5 CHIP follow-ups** for the user to confirm or correct. Format strictly:

   CHIP: ✓ Mapping looks good — proceed → adapt apply
   CHIP: Wrong target form — pick a different one → adapt this sheet to <SUGGEST ANOTHER REAL FORM>
   CHIP: Edit Col B mapping → adapt this sheet — Col B should map to <DIM NAME>
   CHIP: Show me <DIM NAME> dimension to verify → show me the <DIM NAME> dimension
   CHIP: Switch to ad-hoc input mode → adapt this sheet to adhoc input

   IMPORTANT — chips MUST use real names from TENANT FACTS, never invented.

7. **Be honest about uncertainty.** If you can't tell whether a column is Account vs Department (e.g. "Marketing" could be either), present both options and let the user pick.

8. **Do NOT call any tool. Do NOT write any sheet yet.** This is the proposal turn. The actual write happens on the next turn after the user clicks "Apply".

9. **Use REAL names only.** Verbatim from TENANT FACTS / TENANT FORMS / TENANT DIMS below. Do NOT invent member codes — if you suspect "NSP_Salaries" exists but it's not in your facts, say "best guess — verify against Account dim".

---

## ACTIVE SHEET (the client's data)

\`\`\`
${sheetSnippet}
\`\`\`

---

## TENANT FORMS (use only names from this list)

${formsList || "(no tenant inventory loaded — answer generically and tell the user to run Load everything in Settings)"}

---

## TENANT FACTS (cubes / dims / scenarios)

${(() => {
  const ac = appConfig || null;
  const lines = [];
  if (ac && Array.isArray(ac.cubes)) {
    lines.push(`Cubes: ${ac.cubes.join(", ")}`);
    if (ac.mainCube) lines.push(`Main cube: ${ac.mainCube}`);
    if (ac.scenarios) lines.push(`Scenarios: ${ac.scenarios.join(", ")}`);
    if (ac.years) lines.push(`Years: ${ac.years.slice(0,8).join(", ")}`);
  }
  return lines.join("\n") || "(no appConfig)";
})()}

---

`;
  }

  const produced = [];
  const actions = [];     // client-side actions (format_active_sheet, …)
  const transcript = [];
  const trace = debug ? [] : null;
  // lastGrid evolves across turns (a zoom_in then a change_pov uses the fresh descriptor).
  let currentGrid = lastGrid || null;
  let latestDescriptor = null;

  // Translate the chat history into Gemini "contents" format.
  const contents = userMessages.map(m => ({
    role: m.role === "assistant" ? "model" : "user",
    parts: [{ text: String(m.content || "") }]
  }));

  // EXPLAIN MODE: pick model based on whether the question is GENERIC vs
  // IMPLEMENTATION-specific.
  //   Generic ("what is a substitution variable", pure concept)
  //     → Flash + KB only. Fast (~5s). No tenant facts needed.
  //   Implementation ("how do I X in this tenant", "create a Y step by step")
  //     → Pro + KB + TENANT FACTS. Slower (~15s) but grounded in real names,
  //        emits action chips referencing real forms/rules.
  // Heuristic: action verbs ("how do I create / add / run / set up", "step
  // by step") OR explicit "this tenant" / "my forms" → implementation.
  // Anything else → generic.
  const lastQ = lastUserText(userMessages);
  const isImplementationQuestion = forceExplain && (
    /\b(how\s+(do|to|can|should)\s+(i|we|you)|step\s+by\s+step|walk\s+me\s+through|create\s+a|add\s+a|set\s+up|configure|implement|build\s+a|run\s+(a|the)|run\s+rule|open\s+form|in\s+(this|my|our)\s+tenant|my\s+(forms?|rules?|variables?|cubes?))\b/i.test(lastQ)
  );
  const model = (forceExplain || adaptMode)
    ? MODELS.reasoning   // Adapt + complex explain → Pro for grounded mapping
    : (provider === "claude"
       ? pickClaudeModel(lastQ)
       : pickGeminiModel(lastQ));
  // Override: simple concept explain on Flash (legacy fast path)
  let _model = model;
  if (forceExplain && !adaptMode && !isImplementationQuestion) _model = MODELS.fast;
  const MAX_TURNS = 6;
  // Adapt mode disables all tools (preview only — no writes/tool calls).
  const TOOLS = (forceExplain || adaptMode) ? [] : [BUILD_ADHOC_TOOL, RUN_PRESET_TOOL, FIND_MEMBER_TOOL,
                 MODIFY_GRID_TOOL, COMPARE_GRID_TOOL, TOP_DRIVERS_TOOL,
                 FORMAT_SHEET_TOOL, CLEAN_SHEET_TOOL, SHOW_HELP_TOOL,
                 SHOW_INVENTORY_TOOL, OPEN_FORM_TOOL, SHOW_DM_DETAILS_TOOL,
                 SHOW_INTEGRATION_DETAIL_TOOL, SHOW_MAPPING_TOOL,
                 SHOW_PIPELINE_TOOL, SHOW_FILEBROWSER_TOOL,
                 ANALYZE_SHEET_TOOL, EDIT_SHEET_TOOL, CLOSE_REPORT_TOOL, NAVIGATE_TOOL, EXPLAIN_TOOL, ANALYZE_RULES_TOOL, MAP_SHEET_TOOL,
                 SHOW_DIMENSION_TOOL, UPDATE_DIMENSION_TOOL, RENAME_MEMBER_ALIAS_TOOL,
                 TRANSFORM_TO_SMARTVIEW_TOOL, CREATE_SNAPSHOT_TOOL, LIST_SNAPSHOTS_TOOL, SHOW_FILES_TOOL,
                 ANALYZE_INPLACE_TOOL, NAVIGATE_FORM_TOOL];

  let activeModel = _model;
  for (let i = 0; i < MAX_TURNS; i++) {
    const t0 = Date.now();
    // On the first turn, flash uses AUTO (keeps it fast — ANY + complex
    // build_adhoc schema = MALFORMED_FUNCTION_CALL ~every time). Pro uses
    // ANY because it handles it reliably and we want a hard guarantee of
    // a tool call to avoid the "Done." prose fallback.
    let toolMode;
    if (i === 0) {
      toolMode = activeModel === MODELS.fast ? undefined : "ANY";
    } else {
      toolMode = undefined;
    }
    // Extended thinking for Claude Sonnet turns (not explain mode — that caps
    // at 1500 tokens which conflicts with the 10k thinking budget).
    const useThinkingThisTurn = provider === "claude" &&
                                activeModel === MODELS.reasoning &&
                                !forceExplain;
    // Lower output cap when in EXPLAIN MODE — short, focused teaching reply.
    const callOpts = forceExplain ? { maxTokens: 1500 }
                   : useThinkingThisTurn ? { thinking: true }
                   : undefined;
    let resp = await callFn(geminiKey, contents, activeModel, system, TOOLS, toolMode, callOpts);
    let candidate = (resp.candidates && resp.candidates[0]) || {};
    let parts = (candidate.content && candidate.content.parts) || [];
    let finishReason = candidate.finishReason || null;
    let retried = false;

    // Known flash failure modes — auto-retry with pro:
    //   (a) MALFORMED_FUNCTION_CALL on complex schemas (build_adhoc unions).
    //   (b) First turn & flash returned zero tool calls & no useful prose.
    //       That's the old "Done." bug — flash sometimes just gives up. Pro
    //       with toolMode=ANY always calls a tool.
    const emptyRound =
      i === 0 &&
      activeModel === MODELS.fast &&
      parts.filter(p => p.functionCall).length === 0 &&
      !parts.some(p => p.text && p.text.trim().length > 20);

    if ((finishReason === "MALFORMED_FUNCTION_CALL" || emptyRound) &&
        activeModel !== MODELS.reasoning) {
      activeModel = MODELS.reasoning;
      retried = true;
      // Reasoning model always gets ANY so it commits to a tool.
      // Also enable thinking for Claude on this escalated retry.
      const retryOpts = provider === "claude" && !forceExplain ? { thinking: true } : undefined;
      resp = await callFn(geminiKey, contents, activeModel, system, TOOLS, "ANY", retryOpts);
      candidate = (resp.candidates && resp.candidates[0]) || {};
      parts = (candidate.content && candidate.content.parts) || [];
      finishReason = candidate.finishReason || null;
    }

    const funcCalls = parts.filter(p => p.functionCall);
    const textParts = parts.filter(p => p.text).map(p => p.text);

    if (debug) {
      trace.push({
        model: activeModel,
        retried,
        roundMs: Date.now() - t0,
        toolMode: toolMode || "AUTO",
        finishReason,
        hideZeros: !!(nspbSettings && nspbSettings.hideZeros),
        prose: textParts.length ? truncateForTrace(textParts.join("\n"), 240) : null,
        toolCalls: []
      });
    }

    // Echo the model turn back into the conversation.
    // Thinking blocks must round-trip in subsequent turns (interleaved-thinking
    // beta requirement). Store them as a synthetic _thinkingBlocks part so
    // callClaude can re-inject them; Gemini path ignores this field.
    const modelParts = resp._thinkingBlocks
      ? [...parts, { _thinkingBlocks: resp._thinkingBlocks }]
      : parts;
    contents.push({ role: "model", parts: modelParts });

    if (funcCalls.length === 0) {
      if (textParts.length) transcript.push(textParts.join("\n").trim());
      break;
    }

    // Any prose emitted alongside tool calls — surface it to the user.
    if (textParts.length) {
      const txt = textParts.join("\n").trim();
      if (txt) transcript.push(txt);
    }

    const responseParts = [];
    // Global "Hide zero rows" setting (checkbox in the task pane). When on,
    // it OR's into every data tool's removeZeros arg, so the user doesn't
    // have to type "remove zeros" every turn. Per-call args still win when
    // the user explicitly passes false, but Gemini rarely volunteers false.
    const globalHideZeros = !!(nspbSettings && nspbSettings.hideZeros);

    for (const p of funcCalls) {
      const name = p.functionCall.name;
      const args = p.functionCall.args || {};
      if (globalHideZeros &&
          (name === "build_adhoc" || name === "compare_grid" ||
           name === "top_drivers" || name === "modify_grid" || name === "run_preset")) {
        if (args.removeZeros !== false) args.removeZeros = true;
      }
      const tStart = Date.now();
      let result;
      try {
        let out;
        if (name === "build_adhoc")              out = await runBuildAdhoc(nspbSettings, args);
        else if (name === "run_preset")          out = await runPreset(nspbSettings, args);
        else if (name === "find_member")         out = findMember(catalog, args, tenantKb);
        else if (name === "modify_grid")         out = await runModifyGrid(nspbSettings, catalog, currentGrid, args);
        else if (name === "compare_grid")        out = await runCompareGrid(nspbSettings, args);
        else if (name === "top_drivers")         out = await runTopDrivers(nspbSettings, args);
        else if (name === "format_active_sheet") out = runFormatSheet(currentGrid, args);
        else if (name === "clean_active_sheet")  out = runCleanSheet(args);
        else if (name === "transform_to_smartview") out = runTransformToSmartview(args);
        else if (name === "show_help")           out = runShowHelp(nspbSettings);
        else if (name === "show_inventory") {
          // Per-kind fresh-fetch for fast-changing or not-yet-buttoned kinds.
          // Jobs / integrations / pipelines / navigation / periodmappings all
          // refresh on every render so the user doesn't need an explicit
          // Discover button — saying "show me X" is enough.
          const k = args && args.kind;
          let freshJobs = jobs || [], freshIntegrations = [],
              freshPipelines = [], freshNavigation = [],
              freshPeriodMappings = [], freshSavedQueries = [],
              freshLocations = [], freshJobtypes = [],
              freshSchedules = [], freshSchedulesError = null;
          // Variables change the moment someone runs `set variable`, so read
          // them live like jobs/integrations. Rendering the client's cached
          // copy made every write look like a no-op until the next Discover.
          let freshVariables = variables || [];
          let freshVariablesAt = variablesLoadedAt || null;
          if (k === "variables") {
            try {
              const r = await runDiscoverVariables(nspbSettings);
              if (r && Array.isArray(r.variables) && r.variables.length) {
                freshVariables = r.variables;
                freshVariablesAt = r.loadedAt || Date.now();
              }
            } catch (_) { /* keep the shipped cache */ }
          }
          if (k === "jobs") {
            const r = await runDiscoverJobs(nspbSettings);
            freshJobs = r.jobs || [];
          } else if (k === "integrations" || k === "pipelines") {
            const r = await runDiscoverIntegrations(nspbSettings);
            freshIntegrations = r.integrations || [];
            freshPipelines = r.pipelines || [];
          } else if (k === "navigation") {
            const r = await runDiscoverNavigation(nspbSettings);
            freshNavigation = r.nodes || [];
          } else if (k === "periodmappings") {
            const r = await runDiscoverPeriodMappings(nspbSettings);
            freshPeriodMappings = r.mappings || [];
          }
          let freshApps = [], freshSrc = [];
          if (k === "applications") {
            const r = await runDiscoverApplications(nspbSettings);
            freshApps = r.applications || [];
            freshSrc  = r.sourceSystems || [];
          } else if (k === "savedqueries") {
            const r = await runDiscoverSavedQueries(nspbSettings);
            freshSavedQueries = r.queries || [];
          } else if (k === "locations") {
            const r = await runDiscoverLocations(nspbSettings);
            freshLocations = r.locations || [];
          } else if (k === "jobtypes") {
            const r = await runDiscoverJobtypes(nspbSettings);
            freshJobtypes = r.jobtypes || [];
          } else if (k === "schedules") {
            const r = await runDiscoverSchedules(nspbSettings);
            freshSchedules = r.schedules || [];
            freshSchedulesError = r.error || null;
          } else if (k === "environment") {
            // Environment dashboard: fan-out fetch jobs + integrations + pipelines
            // so the summary is live, not stale.
            try { const r = await runDiscoverJobs(nspbSettings); freshJobs = r.jobs || []; } catch (_) {}
            try { const r = await runDiscoverIntegrations(nspbSettings); freshIntegrations = r.integrations || []; freshPipelines = r.pipelines || []; } catch (_) {}
          }
          out = runShowInventory(args, {
            settings: nspbSettings,
            businessRules, forms, tenantKb,
            variables:         freshVariables,
            variablesLoadedAt: freshVariablesAt,
            jobs:           freshJobs,
            integrations:   freshIntegrations,
            pipelines:      freshPipelines,
            navigation:     freshNavigation,
            periodMappings: freshPeriodMappings,
            applications:   freshApps,
            sourceSystems:  freshSrc,
            savedQueries:   freshSavedQueries,
            locations:      freshLocations,
            jobtypes:       freshJobtypes,
            schedules:      freshSchedules,
            schedulesError: freshSchedulesError
          });
        }
        else if (name === "show_integration_detail") out = await runShowIntegrationDetail(nspbSettings, args);
        else if (name === "show_mapping")            out = await runShowMapping(nspbSettings, args);
        else if (name === "show_pipeline")           out = await runShowPipeline(nspbSettings, args);
        else if (name === "show_filebrowser")        out = await runShowFilebrowser(nspbSettings, args);
        else if (name === "analyze_active_sheet")    out = runAnalyzeSheet(args, activeSheet);
        else if (name === "edit_active_sheet")       out = runEditSheet(args, activeSheet);
        else if (name === "generate_close_report")   out = runCloseReport(args, activeSheet);
        else if (name === "navigate_grid")           out = await runNavigateGrid(args, activeSheet, nspbSettings, appConfig, currentGrid);
        else if (name === "explain")                 out = runExplain(args, { tenantKb, forms, appConfig });
        else if (name === "analyze_rules")           out = runAnalyzeRules(args, { tenantKb });
        else if (name === "map_sheet_to_adhoc")      out = runMapSheetToAdhoc(args, activeSheet);
        else if (name === "show_dimension")      out = await runShowDimension(nspbSettings, args.dim, args.cube);
        else if (name === "update_dimension")    out = await runUpdateDimension(nspbSettings, args.dim, args.cube, activeSheet, args.dryRun || false);
        else if (name === "rename_member_alias") out = await runRenameMemberAlias(nspbSettings, args.cube, args.dim, args.member, args.alias, args.aliasTable);
        else if (name === "open_form")           out = await runOpenForm(nspbSettings, args, { forms, tenantKb, appConfig });
        else if (name === "show_dm_details")     out = await runShowDmDetails(nspbSettings, args);
        else if (name === "create_snapshot")     out = await runCreateSnapshot(nspbSettings, args);
        else if (name === "list_snapshots")      out = await runListSnapshots(nspbSettings);
        else if (name === "show_files")          out = await runListInteropFiles(nspbSettings);
        else if (name === "analyze_inplace")     out = runAnalyzeInplace(args, { activeSheet });
        else if (name === "navigate_form")       out = runNavigateForm(args);
        else throw new Error("Unknown tool: " + name);

        if (out && out.grid) {
          produced.push({
            sheetName: out.sheetName,
            grid: out.grid,
            types: out.types || null,
            statuses: out.statuses || null,
            gridDescriptor: out.gridDescriptor || null,
            inPlace: !!out.inPlace,
            format: out.format || null,
            sectionRows: out.sectionRows || null,
            sectionColors: out.sectionColors || null,
            bulletRows: out.bulletRows || null,
            kpiRows: out.kpiRows || null,
            tableHeaderRows: out.tableHeaderRows || null,
            tableDataRows: out.tableDataRows || null,
            htmlReport: out.htmlReport || null,
            rowFills: out.rowFills || null,
            rowFillSpans: out.rowFillSpans || null
          });
          if (out.gridDescriptor) {
            currentGrid = out.gridDescriptor;
            latestDescriptor = out.gridDescriptor;
          }
          result = {
            ok: true,
            sheet: out.sheetName,
            rows: out.grid.length - 1,
            columns: out.grid[0].length > 0 ? out.grid[0].length - 1 : 0,
            // open_form extras — shown in chat by Gemini, not in the sheet
            ...(out.instructions  != null ? { instructions: out.instructions } : {}),
            ...(out.rules         != null ? { rules: out.rules, rulesSource: out.rulesSource } : {}),
            ...(out.formCategory  != null ? { formCategory: out.formCategory } : {}),
            // show_inventory variables extras — Gemini uses these to comment
            ...(out.staleCount    != null ? { staleCount: out.staleCount, rollCount: out.rollCount, okCount: out.okCount, totalCount: out.totalCount, analysisLines: out.analysisLines } : {}),
            // show_inventory navigation extras — chips for openable forms in the flow
            ...(Array.isArray(out.navChips) ? { navChips: out.navChips, matchedFormCount: out.matchedFormCount || 0 } : {}),
            // show_inventory environment extras — quick-action chips + summary
            ...(Array.isArray(out.envChips) ? { envChips: out.envChips, envSummary: out.envSummary || {} } : {}),
            // analyze_rules extras — the AI answers the question from this
            ...(out.scanSummary != null ? { scanSummary: out.scanSummary } : {}),
            // Navigation chips — computed from the descriptor so every data
            // grid teaches the user what they can do next.
            ...(out.gridDescriptor ? { gridChips: buildNavChips(out.gridDescriptor, appConfig) } : {}),
            // Axis legend — which dimension sits on rows/columns/POV.
            ...(out.gridDescriptor ? { gridLegend: buildGridLegend(out.gridDescriptor) } : {}),
            // Empty-grid protocol — the sheet wrote but every cell is blank:
            // the AI must question the POV and offer dimension-total chips.
            ...(out.gridDescriptor && out.dataCellCount === 0 ? {
              emptyGrid: true,
              povChips: buildPovTotalChips(out.gridDescriptor, catalog, tenantKb)
            } : {}),
            debug: out.debug
          };
        } else if (out && out.sheetName && out.grid === null) {
          // open_form on a dashboard/no-access form — no sheet written, but
          // rules/instructions are still returned for Gemini to show in chat.
          result = {
            ok: true,
            sheet: null,
            note: "Form is a dashboard or cannot be rendered as a data grid — no sheet written.",
            ...(out.instructions != null ? { instructions: out.instructions } : {}),
            ...(out.rules        != null ? { rules: out.rules, rulesSource: out.rulesSource } : {}),
            debug: out.debug
          };
        } else if (out && out.action) {
          // Client-side action (e.g. format_active_sheet). Queue it for the
          // task pane to execute; the tool returned no data.
          actions.push(out.action);
          result = {
            ok: true,
            action: out.action.type,
            message: out.message || "Queued for the task pane."
          };
        } else {
          // Non-grid tool (find_member) — pass through its own shape.
          result = out;
        }
      } catch (e) {
        result = { ok: false, error: String(e.message || e) };
      }
      if (debug) {
        trace[trace.length - 1].toolCalls.push({
          name,
          args: truncateForTrace(args, 400),
          ok: !!(result && result.ok),
          sheet: result && result.sheet ? result.sheet : null,
          hits: result && Array.isArray(result.hits) ? result.hits.length : null,
          error: result && result.ok === false ? result.error : null,
          ms: Date.now() - tStart
        });
      }
      responseParts.push({
        functionResponse: { name, response: { result } }
      });
    }
    contents.push({ role: "user", parts: responseParts });

    // Short-circuit: if any tool call produced a grid or queued a client
    // action this turn, skip the follow-up — the user wants the sheet or
    // the format applied, not more prose. find_member on its own should
    // NOT short-circuit; let the loop continue so Gemini can chain
    // find_member → modify_grid or build_adhoc.
    const wroteGridThisTurn = responseParts.some(rp => {
      const r = rp.functionResponse.response.result;
      // These tools must NOT short-circuit — the AI needs the follow-up turn
      // to write narrative prose + chips that depend on the result:
      //   • open_form        → explains form purpose, lists rules
      //   • analyze_active_sheet → narrates findings + offers chips for
      //     the next reports in the incremental analyze flow
      const noShortCircuit = ["open_form", "analyze_active_sheet", "generate_close_report"];
      if (noShortCircuit.includes(rp.functionResponse.name)) return false;
      return r && r.ok === true && typeof r.sheet === "string";
    });
    const queuedActionThisTurn = responseParts.some(rp => {
      const r = rp.functionResponse.response.result;
      return r && r.ok === true && typeof r.action === "string";
    });
    if (wroteGridThisTurn) {
      const last = produced[produced.length - 1];
      transcript.push("✓ Grid written to **" + last.sheetName + "** (" +
                      (last.grid.length - 1) + " rows × " +
                      (last.grid[0].length - 1) + " cols).");
      // If any tool returned analysisLines (e.g. show_inventory variables
      // surfaces summary + CHIP: lines for stale-var fixes), append them so
      // they render in the chat. Without this, the short-circuit silences
      // them — the user only sees "Grid written".
      for (const rp of responseParts) {
        const r = rp.functionResponse.response.result;
        if (r && Array.isArray(r.analysisLines) && r.analysisLines.length) {
          transcript.push(r.analysisLines.join("\n"));
        }
      }
      break;
    }
    if (queuedActionThisTurn) {
      const last = actions[actions.length - 1];
      if (last && last.type === "format_active_sheet") {
        transcript.push("✓ Formatted the active sheet as a " +
                        (last.style || "executive") + " report.");
      } else if (last && last.type === "clean_active_sheet") {
        transcript.push("✓ Removed zero rows from the active sheet.");
      } else if (last && last.type === "transform_to_smartview") {
        transcript.push("✓ Transformed the active sheet to SmartView format → **NSPB_SmartView**.");
      }
      break;
    }
  }

  const reply = transcript.join("\n\n") ||
    "I couldn't decide which tool to call for that request. Try rephrasing — " +
    "e.g. \"revenue by month FY25 forecast\" or \"run RevenueByMonth\". " +
    "Turn on Debug in Settings to see what the model returned.";
  return {
    reply,
    grids: produced,
    actions,
    model,
    gridDescriptor: latestDescriptor,
    trace
  };
}

// format_active_sheet has no NSPB side-effects — it just packages an action
// for the task pane to execute. Runs inside the tool dispatch so Gemini
// sees a normal tool result and stops its loop.
function runFormatSheet(currentGrid, args) {
  const style = (args && args.style) || "executive";
  return {
    ok: true,
    action: {
      type: "format_active_sheet",
      style,
      // Pass the in-flight descriptor so the task pane can build a correct
      // title / subtitle block without re-reading storage.
      descriptor: currentGrid || null
    },
    message: "Queued a " + style + " report format for the active sheet."
  };
}

// clean_active_sheet — drop zero rows from whatever sheet is currently
// active. Like format_active_sheet, this is a client-side action.
function runCleanSheet(args) {
  const mode = (args && args.mode) || "zeros";
  return {
    ok: true,
    action: {
      type: "clean_active_sheet",
      mode
    },
    message: "Queued zero-row cleanup on the active sheet."
  };
}

// transform_to_smartview — re-shape a BR data export (wide TP1..TP12) into a
// SmartView-style ad-hoc grid. All work happens client-side in the task pane
// because the data lives in Excel; the worker only queues the action.
function runTransformToSmartview(_args) {
  return {
    ok: true,
    action: { type: "transform_to_smartview" },
    message: "Queued SmartView transformation on the active sheet."
  };
}

// ── Navigation Flow discovery ─────────────────────────────────────────────────
// Planning REST v3 exposes navigation flows (the Navigator menu structure) at:
//   GET /applications/{app}/navflows                 → list of flows
//   GET /applications/{app}/navflows/{id}            → flow detail
//   GET /applications/{app}/navflows/{id}/clusters   → groups/cards in the flow
//   GET /applications/{app}/navflows/{id}/clusters/{cid}/artifacts → items in each card
//
// These are Basic-Auth endpoints (unlike /efsvbuirest/... which needs session cookies).
// If they work, we get the full Navigator structure: which forms/task lists/reports
// are visible, in which card, in which flow — enough to build a user manual.
async function runDiscoverNavflows(settings) {
  const out = { navflows: [], nodes: [], errors: {}, note: "" };
  // 1. List flows
  let flows = [];
  try {
    const data = await nspbGet(settings, "/navflows");
    flows = data.items || data.navFlows || data.navflows || [];
    if (!flows.length && data.name) flows = [data]; // single object returned
  } catch (e) {
    out.errors.navflows = String(e.message || e);
    out.note = "navflows endpoint returned error — may not be available on this tenant";
    return out;
  }

  out.navflows = flows.map(f => ({
    id:      f.id   || f.navFlowId   || "",
    name:    f.name || f.navFlowName || "",
    status:  f.status || f.state || "",
    default: !!f.isDefault
  }));

  // 2. For each flow fetch clusters (nav cards / groups)
  for (const flow of out.navflows) {
    if (!flow.id) continue;
    let clusters = [];
    try {
      const cd = await nspbGet(settings, `/navflows/${encodeURIComponent(flow.id)}/clusters`);
      clusters = cd.items || cd.clusters || [];
    } catch (e) {
      out.errors[`clusters/${flow.id}`] = String(e.message || e);
    }

    for (const cl of clusters) {
      const clusterId = cl.id || cl.clusterId || "";
      const clusterName = cl.name || cl.clusterName || cl.displayName || "";
      let artifacts = [];

      // 3. For each cluster fetch artifacts (forms, task lists, reports, etc.)
      if (clusterId) {
        try {
          const ad = await nspbGet(settings,
            `/navflows/${encodeURIComponent(flow.id)}/clusters/${encodeURIComponent(clusterId)}/artifacts`);
          artifacts = ad.items || ad.artifacts || [];
        } catch (e) {
          out.errors[`artifacts/${flow.id}/${clusterId}`] = String(e.message || e);
        }
      }

      // Flatten cluster + its artifacts into node rows
      out.nodes.push({
        flow:     flow.name,
        flowId:   flow.id,
        cluster:  clusterName,
        artifact: "",
        type:     "card",
        formName: "",
        order:    cl.order != null ? cl.order : ""
      });

      for (const a of artifacts) {
        out.nodes.push({
          flow:     flow.name,
          flowId:   flow.id,
          cluster:  clusterName,
          artifact: a.name || a.artifactName || a.displayName || "",
          type:     a.artifactType || a.type || a.objectType || "",
          formName: a.formName || a.artifact || a.name || "",
          order:    a.order != null ? a.order : ""
        });
      }
    }
  }

  if (!out.navflows.length) {
    out.note = "No navigation flows found — endpoint may require a published flow or elevated permissions.";
  } else if (!out.nodes.length) {
    out.note = `${out.navflows.length} flow(s) found but clusters/artifacts returned empty — check permissions or flow publication status.`;
  }
  return out;
}

// ── Dimension Import / Export / Alias Rename ──────────────────────────────────

// Flatten a recursive Planning member tree into an array of plain objects.
// Planning REST v3 returns `{ memberName, parentMemberName, aliases:[{aliasTable,value}],
// dataStorage, twoPassCalc, consolidationType, children:[] }` recursively.
function flattenMembers(node, result = []) {
  if (!node) return result;
  result.push({
    member:      node.memberName        || "",
    parent:      node.parentMemberName  || "",
    alias:       ((node.aliases || []).find(a => (a.aliasTable || "").toLowerCase() === "default") || {}).value || "",
    dataStorage: node.dataStorage       || "",
    twoPassCalc: node.twoPassCalc       != null ? String(node.twoPassCalc) : "",
    consolidation: node.consolidationType || ""
  });
  for (const child of (node.children || [])) flattenMembers(child, result);
  return result;
}

async function runShowDimension(settings, dim, cube) {
  if (!cube) throw new Error("show_dimension: cube is required.");
  if (!dim)  throw new Error("show_dimension: dim is required.");
  const encodedDim = encodeURIComponent(dim);
  const encodedCube = encodeURIComponent(cube);
  const data = await nspbGet(settings,
    `/plantypes/${encodedCube}/dimensions/${encodedDim}/members/${encodedDim}?descendants=All`);
  const members = flattenMembers(data);
  if (!members.length) throw new Error(`No members found for ${dim} in cube ${cube}.`);

  const grid = [];
  grid.push([`Dimension Export: ${dim}  ·  Cube: ${cube}  ·  ${new Date().toISOString().slice(0,10)}`, "", "", "", "", ""]);
  grid.push(["Member", "Parent", "Alias:Default", "Data Storage", "Two Pass Calc", "Consolidation"]);
  for (const m of members) {
    grid.push([m.member, m.parent, m.alias, m.dataStorage, m.twoPassCalc, m.consolidation]);
  }
  return {
    grid,
    sheetName: `DIM_${dim}`,
    ok: true,
    message: `Exported ${members.length} members from ${dim} (${cube}).`
  };
}

async function runUpdateDimension(settings, dim, cube, activeSheet, dryRun) {
  if (!cube) throw new Error("update_dimension: cube is required.");
  if (!dim)  throw new Error("update_dimension: dim is required.");
  if (!activeSheet || !activeSheet.values || !activeSheet.values.length)
    throw new Error("update_dimension: no active sheet attached. Open the dimension sheet first.");

  const rows = activeSheet.values;
  // Find header row — first row containing "Member" (case-insensitive)
  let headerIdx = rows.findIndex(r => r.some(c => String(c||"").trim().toLowerCase() === "member"));
  if (headerIdx < 0) throw new Error("update_dimension: no 'Member' column found in the active sheet.");
  const headers = rows[headerIdx].map(c => String(c||"").trim().toLowerCase());
  const col = name => headers.indexOf(name);
  const memberCol = col("member");
  const aliasCol  = headers.findIndex(h => h.startsWith("alias"));
  const parentCol = col("parent");
  const dsCol     = col("data storage");
  const tpCol     = col("two pass calc");
  const consCol   = col("consolidation");

  const dataRows = rows.slice(headerIdx + 1).filter(r => r[memberCol] && String(r[memberCol]).trim());
  if (!dataRows.length) throw new Error("update_dimension: no data rows found below the header.");

  const encodedCube = encodeURIComponent(cube);
  const encodedDim  = encodeURIComponent(dim);
  const base = apiBase(settings);
  const auth = basicAuth(settings.username, settings.password);

  let updated = 0, skipped = 0, errors = [];
  for (const row of dataRows) {
    const memberName = String(row[memberCol] || "").trim();
    if (!memberName) continue;
    const body = {};
    if (aliasCol >= 0 && row[aliasCol] != null) {
      body.aliases = [{ aliasTable: "Default", value: String(row[aliasCol]) }];
    }
    if (parentCol >= 0 && row[parentCol]) body.parentMemberName = String(row[parentCol]);
    if (dsCol >= 0 && row[dsCol])         body.dataStorage       = String(row[dsCol]);
    if (tpCol >= 0 && row[tpCol] != null) body.twoPassCalc       = String(row[tpCol]).toLowerCase() === "true";
    if (consCol >= 0 && row[consCol])     body.consolidationType  = String(row[consCol]);

    if (!Object.keys(body).length) { skipped++; continue; }
    if (dryRun) { updated++; continue; }

    try {
      const url = `${base}/plantypes/${encodedCube}/dimensions/${encodedDim}/members/${encodeURIComponent(memberName)}`;
      const resp = await fetch(url, {
        method: "PATCH",
        headers: { "Authorization": auth, "Content-Type": "application/json", "Accept": "application/json" },
        body: JSON.stringify(body)
      });
      if (!resp.ok) {
        const txt = await resp.text();
        errors.push(`${memberName}: ${resp.status} ${txt.slice(0,120)}`);
      } else {
        updated++;
      }
    } catch (e) {
      errors.push(`${memberName}: ${e.message}`);
    }
  }

  const summary = dryRun
    ? `Dry-run: ${updated} members would be updated, ${skipped} skipped (no changes).`
    : `Updated ${updated} member(s), ${skipped} skipped${errors.length ? `, ${errors.length} error(s)` : ""}.`;

  const grid = [];
  grid.push([`Dimension Import: ${dim}  ·  Cube: ${cube}  ·  ${new Date().toISOString().slice(0,10)}  ${dryRun ? "(DRY RUN)" : ""}`, "", ""]);
  grid.push(["Status", "Member", "Detail"]);
  grid.push([summary, "", ""]);
  if (errors.length) {
    for (const e of errors) grid.push(["ERROR", e.split(":")[0] || "", e]);
  }
  return {
    grid,
    sheetName: `DIM_Import_${dim}`,
    ok: errors.length === 0,
    message: summary
  };
}

async function runRenameMemberAlias(settings, cube, dim, member, alias, aliasTable) {
  if (!cube || !dim || !member) throw new Error("rename_member_alias: cube, dim, and member are required.");
  const table = aliasTable || "Default";
  const body  = { aliases: [{ aliasTable: table, value: alias || "" }] };
  const url   = `${apiBase(settings)}/plantypes/${encodeURIComponent(cube)}/dimensions/${encodeURIComponent(dim)}/members/${encodeURIComponent(member)}`;
  const resp  = await fetch(url, {
    method: "PATCH",
    headers: {
      "Authorization": basicAuth(settings.username, settings.password),
      "Content-Type": "application/json",
      "Accept": "application/json"
    },
    body: JSON.stringify(body)
  });
  if (!resp.ok) {
    const txt = await resp.text();
    throw new Error(`rename_member_alias PATCH failed ${resp.status}: ${txt.slice(0,200)}`);
  }
  return {
    ok: true,
    message: `Alias for "${member}" in ${dim} (${cube}) updated to "${alias}" [table: ${table}].`
  };
}

// Heuristic descriptions for substitution variables. Match by name pattern
// (case-insensitive) — most NSPB tenants follow Oracle conventions like CURYR,
// CURSCEN, CURPER, BEGYEAR, etc. If a variable name doesn't match anything
// known, we leave description blank so the user can fill it in. Returns
// { description, updateWhen }.
function describeVariable(name, value) {
  const n = String(name || "").toLowerCase();
  // Each entry: [regex, description, updateWhen, cadence]
  // cadence ∈ "monthly" | "annually" | "rare" | "static" | "unknown"
  // It drives the per-row Status + color in runShowInventory.
  const checks = [
    // ── NSP_PER_* — Oracle NetSuite Planning period/year convention ────
    [/nsp_per_act.*mo$/,        "Current actual month (last closed period).",                      "EVERY MONTH at close.",          "monthly"],
    [/nsp_per_rpt.*prior.*mo/,  "Prior month for reporting comparisons.",                          "Monthly at close.",              "monthly"],
    [/nsp_per_rpt.*mo$/,        "Current reporting month.",                                        "Monthly at close.",              "monthly"],
    [/nsp_per_fcst.*mo$/,       "Current forecast month (open forecast period).",                  "Monthly at close.",              "monthly"],
    [/nsp_per_sync.*end.*mo/,   "End month of the DM/FDMEE sync window.",                          "Monthly when sync window shifts.","monthly"],
    [/nsp_per_sync.*start.*mo/, "Start month of the DM/FDMEE sync window.",                        "Rarely — only if history window changes.", "monthly"],
    [/nsp_per_act.*yr$/,        "Current actual fiscal year.",                                     "At year-end rollover.",          "annually"],
    [/nsp_per_fcst.*next.*yr/,  "Next fiscal year for forward-looking forecast.",                  "At year-end rollover.",          "annually"],
    [/nsp_per_fcst.*yr$/,       "Current forecast fiscal year.",                                   "At year-end rollover.",          "annually"],
    [/nsp_per_rpt.*prior.*yr/,  "Prior fiscal year for YoY reporting.",                            "At year-end rollover.",          "annually"],
    [/nsp_per_rpt.*yr$/,        "Current reporting fiscal year.",                                  "At year-end rollover.",          "annually"],
    [/nsp_per_prior.*yr\d*$/,   "Prior fiscal year reference (YoY comparisons).",                  "At year-end rollover.",          "annually"],
    [/nsp_per_sync.*end.*yr/,   "End year of the DM/FDMEE sync window.",                           "At year-end rollover.",          "annually"],
    [/nsp_per_sync.*start.*yr/, "Start year of the DM/FDMEE sync window.",                         "Rarely — only if history changes.","rare"],

    // ── NSP_SYS_* — system-level settings ─────────────────────────────
    [/nsp_sys_current.*scen/,   "Current default scenario (e.g. NSP_Forecast). Used by rules and forms.", "When planning cycle changes.", "rare"],
    [/nsp_sys_current.*ver/,    "Current default version (e.g. NSP_Base).",                        "Per planning cycle.",             "rare"],
    [/nsp_sys_log/,             "System log level (1=error, 2=info, 3=debug). Internal setting.",  "Only when debugging.",           "static"],
    [/nsp_sys_bso/,             "Oldest year of BSO cube history. Historical anchor.",              "NEVER — set once at implementation.", "static"],
    [/nsp_sys_base.*curr/,      "Base/functional currency. Structural constant.",                   "Never (currency policy change only).", "static"],
    [/nsp_sys_excl/,            "Exclusion set for FX or consolidation. Structural constant.",      "Rarely.",                        "static"],
    [/nsp_sys_no.*inter/,       "No-Intersection utility tuple used by rules/forms.",               "Never (data structure only).",   "static"],
    [/nsp_sys_rpt.*curr/,       "Reporting currency (e.g. USD_Reporting). Structural constant.",    "Rarely.",                        "static"],

    // ── NSP_FIN_* — financial account/member aliases ───────────────────
    [/nsp_fin_/,                "Financial account or member alias. Structural constant used by rules and reports.", "Never (account structure only).", "static"],

    // ── WF_* — workforce utility tuples ───────────────────────────────
    [/^wf_/,                    "Workforce utility tuple / alias used by workforce rules and forms.", "Never (data structure only).", "static"],

    // ── monthly (HIGH criticality — close-cycle gates) ────────────────
    [/^last.?closed.?(month|per|m)$/,       "Last closed period. CRITICAL — gates actual vs forecast cutoff.",     "EVERY MONTH at close.",                     "monthly"],
    [/^last.?closed.?y(ea)?r$/,             "Last closed year.",                                                    "Annually at year-end.",                     "annually"],
    [/^fcst.?start.?month.?wf$/,            "First period in WORKFORCE forecast. CRITICAL — close-cycle gate.",     "EVERY MONTH at close.",                     "monthly"],
    [/^fcst.?start.?(month|per|m)$/,        "First period included in forecast. Critical actual/forecast boundary.","EVERY MONTH at close.",                     "monthly"],
    [/^fcst.?end.?(month|per|m)?$/,         "Last period included in forecast.",                                    "Monthly during forecast window.",           "monthly"],
    [/^(act|actual).?end.?(month|per|m)?$/, "Last actual period — boundary between actual and forecast.",           "Monthly at close.",                         "monthly"],
    [/^wf.?data.?push.?month/,              "Workforce data-push month boundary.",                                  "Monthly when WF push runs.",                "monthly"],

    // ── monthly (current-period family) ────────────────────────────────
    [/^(cur|current).*per/,                 "Current period (month).",                                              "Monthly at close.",                         "monthly"],
    [/^(cur|current).*month/,               "Current month.",                                                       "Monthly at close.",                         "monthly"],
    [/^(cur|current).*qt?r/,                "Current quarter.",                                                     "Quarterly.",                                "monthly"],
    [/^(wrk|work|working).*qt?r/,           "Working quarter.",                                                     "Quarterly.",                                "monthly"],
    [/^(wrk|work|working).*per/,            "Working period.",                                                      "Per cycle.",                                "monthly"],
    [/^(beg|first|start).*per/,             "First period in the active scenario range.",                           "When the period range shifts.",             "monthly"],
    [/^(end|last).*per/,                    "Last period in the active scenario range.",                            "When the period range shifts.",             "monthly"],

    // ── annual (HIGH criticality — year-end gates) ─────────────────────
    [/^(cur|current).*y(ea)?r$/,            "Current fiscal year used by forms, rules and reports.",                "At year-end rollover (annual).",            "annually"],
    [/^(prior|prev|last).*y(ea)?r$/,        "Prior fiscal year — for YoY comparisons.",                             "At year-end rollover.",                     "annually"],
    [/^(next|fwd).*y(ea)?r$/,               "Next fiscal year — forward-looking views.",                            "At year-end rollover.",                     "annually"],
    [/^(wrk|work|working).*y(ea)?r/,        "Working year.",                                                        "Annually.",                                 "annually"],

    // ── static (NEVER change — historical / structural anchors) ────────
    [/^bs.?oldest.?y(ea)?r$/,               "Oldest year of balance-sheet history. Historical anchor.",             "NEVER — set once at implementation.",       "static"],
    [/^bs.?starting.?balance.?y(ea)?r$/,    "Year used as the starting balance sheet. Historical anchor.",          "NEVER — set once at implementation.",       "static"],
    [/^beg.?balance/,                       "Reference to the BegBalance member.",                                  "Never.",                                    "static"],
    [/^no.?year$/,                          "Utility tuple — non-time data routed to BegBalance / No Year.",        "Never.",                                    "static"],
    [/^no.?(intersection|currency|entity|department|location|employee|account|class|relationship)/,
                                            "Utility tuple — 'No X' fallback intersection used by rules and forms.","Never (only if data structure changes).",   "static"],
    [/^undef|^un_/,                         "Utility tuple — Undefined intersection placeholder.",                  "Never.",                                    "static"],
    [/^cogs|^retained.?earnings|^totalcash|^totalcogs/,
                                            "Account-name alias mapping. Utility constant.",                        "Never.",                                    "static"],
    [/^(cur|current).*scen/,                "Current scenario for default views.",                                  "When planning cycle changes.",              "rare"],
    [/^(cur|current).*ver/,                 "Current version.",                                                     "Per planning cycle.",                       "rare"],
    [/^(curr|currency)$/,                   "Default currency for reports.",                                        "Rarely — currency policy change.",          "rare"],
    [/^(entity|cost.?ctr|costcenter|dept|department)$/,
                                            "Default entity / cost center for views.",                              "Rarely.",                                   "rare"],

    // ── plan-horizon boundaries (rare changes) ─────────────────────────
    [/^(beg|first|start).*y(ea)?r$/,        "First year of the planning horizon.",                                  "When the horizon shifts (rare).",           "rare"],
    [/^(end|last).*y(ea)?r$/,               "Last year of the planning horizon.",                                   "When the horizon shifts (rare).",           "rare"],
    [/^fcst.?yr\d+/,                        "Forecast-year reference (custom). Plan-horizon anchor.",               "Annually if horizon rolls.",                "rare"],
    [/^plan.?yr|^budget.?yr/,               "Plan / budget year reference.",                                        "Annually.",                                 "annually"]
  ];
  for (const [re, desc, when, cadence] of checks) {
    if (re.test(n)) return { description: desc, updateWhen: when, cadence };
  }
  // Value-shape fallbacks. Strip surrounding quotes before testing period/year
  // shapes — NSPB stores values like "TP9" or "FY24" with literal quotes.
  const rawVal = typeof value === "string" ? value.replace(/^"|"$/g, "").trim() : String(value || "");
  if (/^FY\d{2,4}$/i.test(rawVal))  return { description: "Fiscal year reference.", updateWhen: "At year-end rollover.",       cadence: "annually" };
  if (/^TP\d+$/i.test(rawVal))      return { description: "Period (month) reference.", updateWhen: "Monthly at close.",        cadence: "monthly"  };
  // Cross-dim tuples (with ->) are always structural utility constants.
  if (typeof value === "string" && value.includes("->")) {
    return { description: "Utility tuple used by rules and forms.", updateWhen: "Never (data structure only).", cadence: "static" };
  }
  return { description: "", updateWhen: "", cadence: "unknown" };
}

// Compute today-relative status + cell-fill color for a substitution variable.
// Returns { status, color }. Color is null when we have no opinion (the row
// renders with default styling). Used by runShowInventory(variables).
//
// Heuristics (worker time = UTC; close to user calendar for FY=Jan-Dec):
//   - cadence:"static"   → yellow "Static — don't change"
//   - cadence:"monthly"  → green if value matches current TP / month name,
//                          orange if it lags by 1, red if lags ≥2 (or other),
//                          unknown otherwise.
//   - cadence:"annually" → green if value === current FY, orange if 1 year off,
//                          red if ≥2 years off, yellow if a future year (plan
//                          horizon).
//   - cadence:"rare"     → grey "Rarely changes" (informational).
function statusForVariable(name, value, cadence, now) {
  const month = now.getUTCMonth() + 1;       // 1..12
  const year  = now.getUTCFullYear();
  // Last closed month = current month - 1 (typical: close runs mid-month after prior close)
  const lastClosedMonth = month === 1 ? 12 : month - 1;
  const curTp   = `TP${month}`;
  const actTp   = `TP${lastClosedMonth}`;    // actual = last closed
  const priorTp = `TP${month === 1 ? 12 : month - 1}`;
  const nextTp  = `TP${month === 12 ? 1 : month + 1}`;
  const curFy   = `FY${String(year).slice(-2)}`;
  const monthNames = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  // Strip surrounding quotes — NSPB stores values like "TP9" or "FY24" with literal quotes.
  const v = String(value || "").replace(/^"|"$/g, "").trim();
  const n = String(name || "").toLowerCase();

  // Static FIRST — these are utility tuples / aliases that don't track time;
  // they get no color and sort to the bottom of the sheet.
  if (cadence === "static") {
    return { status: "Static — don't change", color: null };       // no fill
  }

  // Determine the EXPECTED value for this specific variable based on its name semantics.
  // e.g. NSP_PER_ActCurrMo should be last-closed month, NSP_PER_FcstCurrMo = current month, etc.
  const expectedTp = (() => {
    if (/act.*mo$|rpt.*prior.*mo|sync.*end.*mo/.test(n)) return actTp;   // last closed
    if (/fcst.*mo$|rpt.*mo$|cur.*(per|month)/.test(n))  return curTp;   // current open month
    return curTp; // default
  })();
  const expectedFy = (() => {
    const cy = parseInt(curFy.slice(2), 10);
    if (/prior.*yr1$/.test(n))   return `FY${String(cy - 2).padStart(2,"0")}`;
    if (/prior.*yr/.test(n))     return `FY${String(cy - 1).padStart(2,"0")}`;
    if (/next.*yr|fcst.*next/.test(n)) return `FY${String(cy + 1).padStart(2,"0")}`;
    return curFy; // current year
  })();

  // Helpers: decide month/year status from the value's shape.
  const monthStatus = () => {
    if (/^&/.test(v)) return { status: "Formula reference (delegates)", color: "#e0e7ff" };
    if (v === expectedTp || v.toLowerCase() === monthNames[parseInt(expectedTp.slice(2),10) - 1].toLowerCase()) {
      return { status: "OK — current month", color: "#d1fae5" };
    }
    if (v === nextTp) {
      return { status: "Roll forward — close cycle?", color: "#fed7aa" };
    }
    if (/^TP\d+$/i.test(v) || monthNames.some(m => v.toLowerCase() === m.toLowerCase())) {
      const tpNum = parseInt(v.replace(/^TP/i,""), 10);
      const expNum = parseInt(expectedTp.slice(2), 10);
      const lag = expNum - tpNum;
      if (lag === 1) return { status: "Roll forward — 1 month behind", color: "#fed7aa" };
      return { status: `STALE — ${Math.abs(lag)} month(s) behind`, color: "#fee2e2" };
    }
    return null;
  };
  const annualStatus = () => {
    if (v === expectedFy) return { status: "OK — current FY", color: "#d1fae5" };
    const m2 = v.match(/^FY(\d{2,4})$/i);
    if (m2) {
      const yy = parseInt(m2[1].length === 2 ? "20"+m2[1] : m2[1], 10);
      const exp = parseInt(expectedFy.length === 4 ? expectedFy.slice(2) : expectedFy.slice(2), 10);
      const expFull = 2000 + exp;
      const lag = expFull - yy;
      if (lag === 1) return { status: "Roll forward at year-end", color: "#fed7aa" };
      if (lag >= 2)  return { status: `STALE — ${lag} year(s) behind`, color: "#fee2e2" };
      if (lag < 0)   return { status: `Future year (plan horizon, +${-lag})`, color: "#fef3c7" };
    }
    return null;
  };

  if (cadence === "monthly") {
    return monthStatus() || { status: "Review", color: null };
  }
  if (cadence === "annually") {
    return annualStatus() || { status: "Review", color: null };
  }
  if (cadence === "rare") {
    return annualStatus() || monthStatus() || { status: "Rarely changes", color: null };
  }
  return { status: "", color: null };
}

// Suggest a value for a variable that's not OK, with a one-line reason.
// Returns { suggested, reason } or null. Triggered by show_inventory when
// status indicates STALE / Roll / Future, so the user sees what to set.
function suggestVariable(name, value, cadence, status, now) {
  if (!status) return null;
  if (status.startsWith("OK") || status.startsWith("Static")) return null;
  if (status.startsWith("Rarely")) return null;

  const month = now.getUTCMonth() + 1;
  const year  = now.getUTCFullYear();
  const yy    = String(year).slice(-2);
  const n     = String(name || "").toLowerCase();
  const lastClosed = month === 1 ? 12 : month - 1;

  // ── NSP_PER_* naming convention (specific rules first) ────────────────────
  // Actual/Report vars = last closed month. Forecast = current open month.
  if (/nsp_per_act.*mo/.test(n))           return { suggested: `TP${lastClosed}`,               reason: `last closed month (today is month ${month}, so TP${lastClosed} = last closed).` };
  if (/nsp_per_rpt.*prior.*mo/.test(n))    return { suggested: `TP${lastClosed}`,               reason: "prior reporting month = last closed month." };
  if (/nsp_per_rpt.*mo/.test(n))           return { suggested: `TP${lastClosed}`,               reason: "report current month = last closed month." };
  if (/nsp_per_sync.*end.*mo/.test(n))     return { suggested: `TP${lastClosed}`,               reason: "sync end month = last closed month." };
  if (/nsp_per_fcst.*mo/.test(n))          return { suggested: `TP${month}`,                    reason: `current open forecast month (today = month ${month}).` };
  if (/nsp_per_sync.*start.*mo/.test(n))   return { suggested: null,                            reason: "start of sync window — usually TP1 or a fixed historical anchor, verify before changing." };

  if (/nsp_per_act.*yr/.test(n))           return { suggested: `FY${yy}`,                       reason: `current fiscal year (today = ${year}).` };
  if (/nsp_per_fcst.*next.*yr/.test(n))    return { suggested: `FY${String(year+1).slice(-2)}`, reason: "next fiscal year = current + 1." };
  if (/nsp_per_fcst.*yr/.test(n))          return { suggested: `FY${yy}`,                       reason: "current forecast year." };
  if (/nsp_per_prior.*yr1/.test(n))        return { suggested: `FY${String(year-2).slice(-2)}`, reason: "prior year -2 (two years ago)." };
  if (/nsp_per_prior.*yr/.test(n))         return { suggested: `FY${String(year-1).slice(-2)}`, reason: "prior fiscal year = current - 1." };
  if (/nsp_per_rpt.*prior.*yr/.test(n))    return { suggested: `FY${String(year-1).slice(-2)}`, reason: "prior reporting year = current FY - 1." };
  if (/nsp_per_rpt.*yr.*prior.*mo/.test(n)) return { suggested: `FY${yy}`,                      reason: "year of the prior month — same FY unless January (then prior year)." };
  if (/nsp_per_rpt.*yr/.test(n))           return { suggested: `FY${yy}`,                       reason: "current reporting year." };
  if (/nsp_per_sync.*end.*yr/.test(n))     return { suggested: `FY${yy}`,                       reason: "sync end year = current FY." };
  if (/nsp_per_sync.*start.*yr/.test(n))   return { suggested: null,                            reason: "start year of sync window — historical anchor, verify before changing." };

  // ── Generic year-flavored vars ────────────────────────────────────────────
  if (status.includes("FY") || status.includes("year") || status.includes("Year")) {
    if (/^last.?closed.?y(ea)?r$/.test(n))      return { suggested: `FY${yy}`,                       reason: "today's fiscal year." };
    if (/^(prior|prev|last).*yr2?$/.test(n))     return { suggested: `FY${String(year-1).slice(-2)}`, reason: "current FY minus 1." };
    if (/^(next|fwd).*y(ea)?r$/.test(n))         return { suggested: `FY${String(year+1).slice(-2)}`, reason: "current FY plus 1." };
    if (/^fcst.?yr1/.test(n))                    return { suggested: `FY${yy}`,                       reason: "first forecast year = current FY." };
    if (/^fcst.?yr2/.test(n))                    return { suggested: `FY${String(year+1).slice(-2)}`, reason: "current FY + 1." };
    if (/^fcst.?yr3/.test(n))                    return { suggested: `FY${String(year+2).slice(-2)}`, reason: "current FY + 2." };
    if (/^(cur|current).*y(ea)?r$/.test(n))      return { suggested: `FY${yy}`,                       reason: "today's fiscal year." };
    return { suggested: `FY${yy}`, reason: "today's fiscal year." };
  }

  // ── Generic month-flavored vars ───────────────────────────────────────────
  if (status.includes("month") || status.includes("STALE") || status.startsWith("Roll")) {
    if (/^last.?closed.?(month|per|m)$/.test(n))  return { suggested: `TP${lastClosed}`, reason: "last closed month." };
    if (/^fcst.?start.?month.?wf$/.test(n))        return { suggested: `TP${month}`,     reason: "Workforce forecast starts at current month." };
    if (/^fcst.?start.?(month|per|m)$/.test(n))    return { suggested: `TP${month}`,     reason: "forecast starts at current month." };
    if (/^(act|actual).?end/.test(n))              return { suggested: `TP${lastClosed}`, reason: "last actual month = last closed." };
    if (/^(cur|current).*(per|month)/.test(n))     return { suggested: `TP${month}`,     reason: "today's calendar month." };
    return { suggested: `TP${month}`, reason: "today's calendar month." };
  }
  return null;
}

// Render a formatted sheet for the requested inventory kind. The task pane
// applies format:"help" styling (title row + dark header + bold first col +
// wrap text + fixed widths). Each kind has its own sheet so users can keep
// multiple open side-by-side.
function runShowInventory(args, opts) {
  const kind = args && args.kind;
  if (!kind) throw new Error("show_inventory: kind required (variables | rules | forms | jobs)");
  const helpUrl = (opts.settings && opts.settings.helpUrl) || "https://nspb-kb.web.app/";
  const today = new Date().toISOString().slice(0, 10);

  if (kind === "variables") {
    const vars = Array.isArray(opts.variables) ? opts.variables : [];
    const now = new Date();
    // Date the values were actually READ, not the date we happen to render
    // them. Stamping "today" on a month-old cache is how a stale inventory
    // passed for a live one.
    const readAt = opts.variablesLoadedAt ? new Date(opts.variablesLoadedAt) : null;
    const readAtLabel = readAt && !isNaN(readAt)
      ? readAt.toISOString().slice(0, 10) + (readAt.toISOString().slice(0, 10) === today ? "" : "  ⚠ cached — run `update variables` for live values")
      : today;
    const grid = [
      ["Substitution Variables — discovered inventory", "", "", ""],
      ["Variables referenced by business rules and forms with the &VAR syntax. They control which fiscal year/month the system treats as 'current' for actuals, forecast, and reporting. Roll them at month-end / year-end so reports point to the right period.", "", "", ""],
      [`Last refreshed: ${readAtLabel}  ·  ${vars.length} variables`, "", "", ""],
      ["Variable", "Value", "Suggested Value", "Explanation"]
    ];
    const sectionRows = [];
    const rowFills = {};
    const rowFillSpans = {};   // limit fill to first N cols (so descriptions stay white)
    let staleCount = 0, rollCount = 0, okCount = 0;
    let sorted = [];   // hoisted so chip-builder below can reuse it
    if (!vars.length) {
      grid.push(["(none discovered yet)", "", "", "Open Settings → click 'Detect everything' to populate this list."]);
    } else {
      // Sort priority: STALE first (red), Roll (orange), OK (green), Future,
      // Review, Rarely, then Static at the very bottom (no color).
      sorted = vars.slice().map(v => {
        const { description, updateWhen, cadence } = describeVariable(v.name, v.value);
        const { status, color } = statusForVariable(v.name, v.value, cadence, now);
        const sugg = suggestVariable(v.name, v.value, cadence, status, now);
        return { v, description, updateWhen, cadence, status, color, sugg };
      });
      const order = (s) => {
        if (!s) return 8;
        if (s.startsWith("STALE")) return 0;
        if (s.startsWith("Roll")) return 1;
        if (s.startsWith("OK")) return 2;
        if (s.startsWith("Future")) return 3;
        if (s.startsWith("Formula")) return 4;
        if (s.startsWith("Review")) return 5;
        if (s.startsWith("Rarely")) return 6;
        if (s.startsWith("Static")) return 9;   // bottom
        return 7;
      };
      sorted.sort((a, b) => order(a.status) - order(b.status));
      for (const item of sorted) {
        if (item.status.startsWith("STALE")) staleCount++;
        else if (item.status.startsWith("Roll")) rollCount++;
        else if (item.status.startsWith("OK")) okCount++;
        const rowIdx = grid.length;
        // Suggested Value column: just the suggested value (or "—" if none).
        // Status info goes inline in the Explanation column so users still
        // see "STALE — 4 months behind" without a dedicated column.
        const suggestedValue = item.sugg ? item.sugg.suggested : "—";
        // Build the Explanation: status badge + reason + base description.
        // Cadence-driven label is appended so users still see "Monthly /
        // Annually" cadence info without a dedicated column.
        const cadenceLabel = (() => {
          const c = item.cadence;
          if (c === "monthly")  return "🗓️ monthly";
          if (c === "annually") return "📅 annually";
          if (c === "rare")     return "🔁 per cycle";
          if (c === "static")   return "🔒 static";
          return "";
        })();
        const parts = [];
        if (item.status) parts.push(item.status);
        if (item.sugg && item.sugg.reason) parts.push(item.sugg.reason);
        if (item.description) parts.push(item.description);
        if (cadenceLabel) parts.push("(" + cadenceLabel + ")");
        const explanation = parts.join(" — ");
        grid.push([
          item.v.name || "",
          item.v.value != null ? String(item.v.value) : "",
          suggestedValue,
          explanation
        ]);
        if (item.color) {
          rowFills[rowIdx] = item.color;
          rowFillSpans[rowIdx] = 3;   // paint Variable | Value | Suggested Value
        }
      }
    }
    if (staleCount + rollCount > 0) {
      grid[2] = [`⚠ ${staleCount} stale  ·  ${rollCount} need rolling  ·  ${okCount} OK  ·  ${vars.length} total`, "", "", ""];
      rowFills[2] = staleCount > 0 ? "#fee2e2" : "#fed7aa";
      rowFillSpans[2] = 3;
    }
    // Build analysisLines + nudge to /update variables to fix stale ones.
    const analysisLines = [];
    if (staleCount > 0 || rollCount > 0) {
      analysisLines.push(`${staleCount} STALE 🔴, ${rollCount} need rolling 🟠, ${okCount} OK 🟢 out of ${vars.length} variables. Click any chip below to apply a suggested value, or run \`update variables\` for the bulk editor.`);
    } else if (vars.length) {
      analysisLines.push(`✓ All ${vars.length} variables look up-to-date. To edit any value, run \`update variables\` for the live editor.`);
    }
    // Suggested-update chips — one per stale/roll var that has a concrete
    // suggestion. Preserve the original quoting (NSPB stores some vars with
    // literal "double quotes" around the value, others without — we mirror
    // whatever the source had so the round-trip stays consistent).
    const suggestedChips = [];
    for (const item of sorted) {
      if (!item.sugg || !item.sugg.suggested) continue;
      if (!(item.status && (item.status.startsWith("STALE") || item.status.startsWith("Roll")))) continue;
      const origVal = String(item.v.value == null ? "" : item.v.value);
      const wasQuoted = /^".*"$/.test(origVal.trim());
      const newVal = wasQuoted ? `"${item.sugg.suggested}"` : item.sugg.suggested;
      suggestedChips.push(`Set ${item.v.name} = ${newVal} → set variable ${item.v.name} = ${newVal}`);
    }
    // Inject as CHIP: lines into analysisLines so Gemini renders them as
    // clickable buttons (the chat renderer turns "CHIP: Label → command"
    // into a button that pastes `command` into the input on click).
    for (const c of suggestedChips) {
      analysisLines.push("CHIP: " + c);
    }
    return {
      sheetName: "NSPB_Variables",
      grid,
      gridDescriptor: null,
      inPlace: true,
      format: "help",
      sectionRows,
      rowFills,
      rowFillSpans,
      staleCount,
      rollCount,
      okCount,
      totalCount: vars.length,
      analysisLines
    };
  }

  if (kind === "rules") {
    const rules = Array.isArray(opts.businessRules) ? opts.businessRules : [];
    const grid = [
      ["Business Rules — discovered inventory", "", "", ""],
      ["", "", "", ""],
      [`Last refreshed: ${today}  ·  ${rules.length} rules  ·  Click 'Rules' in Settings to refresh`, "", "", ""],
      ["", "", "", ""],
      ["Name", "Cube", "Type", "Description"]
    ];
    if (!rules.length) {
      grid.push(["(none discovered yet)", "", "", "Open Settings → click 'Rules' to populate this list."]);
    } else {
      for (const r of rules) {
        grid.push([
          r.name || r.jobDefinitionName || "",
          r.cube || "",
          r.jobType || "RULES",
          r.description || ""
        ]);
      }
    }
    return { sheetName: "NSPB_Rules", grid, gridDescriptor: null, inPlace: true, format: "help" };
  }

  if (kind === "forms") {
    const forms = Array.isArray(opts.forms) ? opts.forms : [];
    const tkb = opts.tenantKb || null;
    const kbForms = (tkb && Array.isArray(tkb.forms)) ? tkb.forms : [];
    const kbByName = new Map(kbForms.map(f => [String(f.name || "").trim().toLowerCase(), f]));
    const formatRules = (arr) => (arr || [])
      .map(r => (r.name || "") + (r.runOnSave ? "(onSave)" : ""))
      .filter(Boolean)
      .join(", ");
    const inputCount = forms.filter(f => f.category === "input").length;
    const reviewCount = forms.filter(f => f.category === "review").length;
    const unknownCount = forms.filter(f => f.category !== "input" && f.category !== "review").length;
    const grid = [
      ["Forms — discovered inventory", "", "", "", "", "", ""],
      ["", "", "", "", "", "", ""],
      [`Last refreshed: ${today}  ·  ${forms.length} forms  ·  ${inputCount} input · ${reviewCount} review · ${unknownCount} unknown  ·  Click 'Forms' in Settings to refresh`, "", "", "", "", "", ""],
      ["", "", "", "", "", "", ""],
      ["Tip: 'open form X' renders the form into a new sheet WITH attached business rules + their descriptions. Category is heuristic (name + type 8/40 + keywords).", "", "", "", "", "", ""],
      ["", "", "", "", "", "", ""],
      ["Name", "Category", "Cube", "Path", "Description", "Attached Rules", "Form ID"]
    ];
    const rowFills = {};
    if (!forms.length) {
      grid.push(["(none discovered yet)", "", "", "", "Click 'Forms' in Settings.", "", ""]);
    } else {
      // Sort: input forms first (most common workflow), then review, then unknown.
      const order = { input: 0, review: 1, unknown: 2 };
      const sorted = forms.slice().sort((a, b) => {
        const oa = order[a.category] != null ? order[a.category] : 2;
        const ob = order[b.category] != null ? order[b.category] : 2;
        if (oa !== ob) return oa - ob;
        return (a.path || "").localeCompare(b.path || "") || (a.name || "").localeCompare(b.name || "");
      });
      for (const f of sorted) {
        const rowIdx = grid.length;
        const kbHit = kbByName.get(String(f.name || "").trim().toLowerCase());
        const rulesText = formatRules(kbHit && kbHit.attachedRules);
        const description = f.description || (kbHit && kbHit.description) || "";
        grid.push([
          f.name || "",
          f.category || "unknown",
          f.cube || "",
          f.path || "",
          description,
          rulesText,
          f.formId || ""
        ]);
        if (f.category === "input")  rowFills[rowIdx] = "#dbeafe";   // blue-100
        else if (f.category === "review") rowFills[rowIdx] = "#f3e8ff";  // purple-100
      }
    }
    return {
      sheetName: "NSPB_Forms",
      grid,
      gridDescriptor: null,
      inPlace: true,
      format: "help",
      rowFills
    };
  }

  if (kind === "jobs" || kind === "alljobs" || kind === "dmjobs") {
    const rawJobs = Array.isArray(opts.jobs) ? opts.jobs : [];
    // Default kind=jobs = Planning rule runs ONLY (rule executions). User
    // feedback: the mixed Planning+DM list was confusing — DM jobs belong
    // to the DM/integrations area, rule runs belong to 'jobs'. Use kind=
    // 'dmjobs' for DM-only and kind='alljobs' to get both.
    const jobs = kind === "alljobs"
      ? rawJobs
      : kind === "dmjobs"
        ? rawJobs.filter(j => j.source === "dm")
        : rawJobs.filter(j => j.source === "planning" || !j.source);
    const now = new Date();
    const cutoff24h = now.getTime() - 24 * 60 * 60 * 1000;
    const cutoff7d  = now.getTime() - 7 * 24 * 60 * 60 * 1000;
    const last24h = jobs.filter(j => j.startTime && new Date(j.startTime).getTime() >= cutoff24h).length;
    const last7d  = jobs.filter(j => j.startTime && new Date(j.startTime).getTime() >= cutoff7d).length;
    const planningCount = jobs.filter(j => j.source === "planning").length;
    const dmCount       = jobs.filter(j => j.source === "dm").length;
    const errCount      = jobs.filter(j => /error|fail/i.test(j.status || "")).length;
    const title = kind === "alljobs" ? "Recent Jobs — Planning + Data Management"
                : kind === "dmjobs"  ? "Recent Jobs — Data Management only"
                                     : "Recent Jobs — Planning rule runs";
    const summaryParts = [
      `Last refreshed: ${today}`,
      `${jobs.length} jobs`,
      `${last24h} in last 24h`,
      `${last7d} in last 7 days`,
    ];
    if (kind === "alljobs") summaryParts.push(`${planningCount} planning · ${dmCount} DM`);
    summaryParts.push(`${errCount} errors`);
    const grid = [
      [title, "", "", "", "", "", ""],
      ["", "", "", "", "", "", ""],
      [summaryParts.join("  ·  "), "", "", "", "", "", ""],
      ["", "", "", "", "", "", ""],
      ["Started", "Source", "Type", "Name", "Status", "User", "Notes"]
    ];
    const rowFills = {};
    const rowFillSpans = {};
    if (!jobs.length) {
      grid.push(["(none discovered yet)", "", "", "Click 'Jobs' in Settings to populate.", "", "", ""]);
    } else {
      for (const j of jobs) {
        const startMs = j.startTime ? new Date(j.startTime).getTime() : 0;
        const when = startMs ? new Date(startMs).toISOString().replace("T", " ").slice(0, 16) : (j.startTime || "");
        const note = j.errorMessage || j.period || j.cube || "";
        const rowIdx = grid.length;
        grid.push([
          when,
          j.source === "planning" ? "Planning" : j.source === "dm" ? "Data Mgmt" : (j.source || ""),
          j.jobTypeLabel || j.jobType || "",
          j.name || "",
          j.status || "",
          j.userName || "",
          note
        ]);
        // Color: errors red, in-progress orange, last 24h green, older neutral.
        const st = String(j.status || "").toLowerCase();
        const stCode = String(j.statusCode || "").toLowerCase();
        if (/error|fail/.test(st) || /error/.test(stCode)) {
          rowFills[rowIdx] = "#fee2e2";
        } else if (/processing|pending|running/.test(st) || /processing|pending/.test(stCode)) {
          rowFills[rowIdx] = "#fed7aa";
        } else if (startMs >= cutoff24h) {
          rowFills[rowIdx] = "#d1fae5";   // green — recent successful run
        }
        if (rowFills[rowIdx]) rowFillSpans[rowIdx] = 5;   // don't paint user/notes cols
      }
    }
    // (Tips/legend removed — colors carry the meaning visually.)
    return {
      sheetName: "NSPB_Jobs",
      grid,
      gridDescriptor: null,
      inPlace: true,
      format: "help",
      sectionRows: [],
      rowFills,
      rowFillSpans
    };
  }

  if (kind === "integrations") {
    const integrations = Array.isArray(opts.integrations) ? opts.integrations : [];
    const grid = [
      ["NetSuite ↔ NSPB (Data Management) Integrations — discovered inventory", "", "", "", "", ""],
      ["", "", "", "", "", ""],
      [`Last refreshed: ${today}  ·  ${integrations.length} data rules  ·  Click 'Integ' in Settings to refresh`, "", "", "", "", ""],
      ["", "", "", "", "", ""],
      ["Name", "Source", "Target", "Category", "Status", "Description"]
    ];
    if (!integrations.length) {
      grid.push(["(none discovered yet)", "", "", "", "", "Click 'Integ' in Settings to populate."]);
    } else {
      for (const i of integrations) {
        grid.push([i.name, i.sourceApp, i.targetApp, i.category, i.status, i.description]);
      }
    }
    return { sheetName: "NSPB_Integrations", grid, gridDescriptor: null, inPlace: true, format: "help" };
  }

  if (kind === "pipelines") {
    const pipelines = Array.isArray(opts.pipelines) ? opts.pipelines : [];
    const grid = [
      ["Data Management Pipelines — discovered inventory", "", "", "", ""],
      ["", "", "", "", ""],
      [`Last refreshed: ${today}  ·  ${pipelines.length} pipelines  ·  Click 'Integ' in Settings to refresh`, "", "", "", ""],
      ["", "", "", "", ""],
      ["Name", "Stages", "Last Run", "Status", "Description"]
    ];
    if (!pipelines.length) {
      grid.push(["(none discovered yet)", "", "", "", "Click 'Integ' in Settings."]);
    } else {
      for (const p of pipelines) {
        grid.push([p.name, p.stageCount, p.lastRun, p.status, p.description]);
      }
    }
    return { sheetName: "NSPB_Pipelines", grid, gridDescriptor: null, inPlace: true, format: "help" };
  }

  if (kind === "environment") {
    const vars = Array.isArray(opts.variables) ? opts.variables : [];
    const rules = Array.isArray(opts.businessRules) ? opts.businessRules : [];
    const forms = Array.isArray(opts.forms) ? opts.forms : [];
    const jobs = Array.isArray(opts.jobs) ? opts.jobs : [];
    const integrations = Array.isArray(opts.integrations) ? opts.integrations : [];
    const pipelines = Array.isArray(opts.pipelines) ? opts.pipelines : [];
    const tkb = opts.tenantKb || null;
    const kbForms = (tkb && Array.isArray(tkb.forms)) ? tkb.forms : [];
    const lcmFlows = (tkb && Array.isArray(tkb.navigationFlows)) ? tkb.navigationFlows : [];
    const settings = opts.settings || {};
    const now = new Date();

    // Variable health summary
    let varStale = 0, varRoll = 0, varOk = 0, varStatic = 0, varOther = 0;
    const staleList = [];
    for (const v of vars) {
      const { cadence } = describeVariable(v.name, v.value);
      const { status } = statusForVariable(v.name, v.value, cadence, now);
      if (!status) { varOther++; continue; }
      if (status.startsWith("STALE")) { varStale++; staleList.push({ name: v.name, value: v.value, status }); }
      else if (status.startsWith("Roll")) { varRoll++; staleList.push({ name: v.name, value: v.value, status }); }
      else if (status.startsWith("OK")) varOk++;
      else if (status === "Static") varStatic++;
      else varOther++;
    }

    // Job stats — last 10, error count
    const recentJobs = jobs.slice(0, 10);
    const failedJobs = jobs.filter(j => /error|fail/i.test(String(j.status || ""))).slice(0, 5);

    // Forms by category from tenantKb (LCM-only counts)
    const formsBySource = {
      live: forms.length,
      lcm: kbForms.length,
      input: kbForms.filter(f => f.isInput).length,
      review: kbForms.filter(f => !f.isInput).length
    };

    const grid = [
      ["NSPB Environment — tenant health dashboard", "", "", ""],
      ["", "", "", ""],
      [`Last refreshed: ${now.toISOString().slice(0,16).replace("T"," ")} UTC  ·  Tenant: ${settings.planningUrl || "(unset)"}`, "", "", ""],
      ["", "", "", ""]
    ];
    const sectionRows = [];

    // 1) Inventory counts
    grid.push(["Inventory counts", "", "", ""]); sectionRows.push(grid.length - 1);
    grid.push(["Object", "Live (API)", "LCM (KB)", "Notes"]);
    grid.push(["Forms", forms.length, kbForms.length, `${formsBySource.input} input · ${formsBySource.review} review`]);
    grid.push(["Dashboards", "", (tkb && Array.isArray(tkb.dashboards)) ? tkb.dashboards.length : 0, "Read-only, NSPB web UI only"]);
    grid.push(["Business rules", rules.length, (tkb && Array.isArray(tkb.rules)) ? tkb.rules.length : 0, ""]);
    grid.push(["Substitution variables", vars.length, (tkb && Array.isArray(tkb.substitutionVariables)) ? tkb.substitutionVariables.length : 0, ""]);
    grid.push(["DM integrations", integrations.length, "", "Data rules"]);
    grid.push(["DM pipelines", pipelines.length, "", "Orchestrated job sequences"]);
    grid.push(["Navigation flows", "", lcmFlows.length, lcmFlows.map(f => f.name).join(", ")]);

    // 2) Variable health
    grid.push(["", "", "", ""]);
    grid.push(["Variable health", "", "", ""]); sectionRows.push(grid.length - 1);
    grid.push(["Status", "Count", "Meaning", ""]);
    grid.push(["🔴 STALE", varStale, "Behind expected period — needs roll", ""]);
    grid.push(["🟠 Roll", varRoll, "1 month/year behind — roll at next close", ""]);
    grid.push(["🟢 OK", varOk, "Aligned to current period", ""]);
    grid.push(["🟡 Static", varStatic, "No cadence (account codes, fixed values)", ""]);
    if (varOther) grid.push(["⚪ Other", varOther, "Unknown cadence / review needed", ""]);
    if (staleList.length) {
      grid.push(["", "", "", ""]);
      grid.push(["Variables needing attention", "", "", ""]); sectionRows.push(grid.length - 1);
      grid.push(["Name", "Current value", "Status", ""]);
      for (const s of staleList.slice(0, 20)) {
        grid.push([s.name, s.value, s.status, ""]);
      }
    }

    // 3) Recent jobs / failures
    grid.push(["", "", "", ""]);
    grid.push(["Recent Data Management jobs", "", "", ""]); sectionRows.push(grid.length - 1);
    if (!recentJobs.length) {
      grid.push(["(no jobs cached — say 'show me recent jobs' to fetch)", "", "", ""]);
    } else {
      grid.push(["Process ID", "Status", "Type", "Started"]);
      for (const j of recentJobs) {
        grid.push([j.processId || j.id || "", j.status || "", j.processType || j.type || "", j.startTime || j.scheduledTime || ""]);
      }
    }
    if (failedJobs.length) {
      grid.push(["", "", "", ""]);
      grid.push(["⚠ Failed jobs", "", "", ""]); sectionRows.push(grid.length - 1);
      grid.push(["Process ID", "Status", "Type", "Started"]);
      for (const j of failedJobs) {
        grid.push([j.processId || j.id || "", j.status || "", j.processType || j.type || "", j.startTime || j.scheduledTime || ""]);
      }
    }

    // 4) Quick links / next actions
    grid.push(["", "", "", ""]);
    grid.push(["Quick actions (type these in chat)", "", "", ""]); sectionRows.push(grid.length - 1);
    grid.push(["Command", "What it does", "", ""]);
    grid.push(["show me the variables", "Full variable health sheet with roll suggestions", "", ""]);
    grid.push(["show navigation flow", "Menu tree with Open chips for every form", "", ""]);
    grid.push(["show me recent jobs", "Newest-first DM job history", "", ""]);
    grid.push(["show me the rules", "All business rules with descriptions", "", ""]);
    grid.push(["help", "Full command reference with example chips", "", ""]);

    // Chips for chat
    const envChips = [
      "Show variables → show me the variables",
      "Show navigation → show navigation flow",
      "Recent jobs → show me recent jobs",
      "Show rules → show me the rules",
      "Help → help"
    ];

    return {
      sheetName: "NSPB_Environment",
      grid,
      gridDescriptor: null,
      inPlace: true,
      format: "help",
      sectionRows,
      envChips,
      envSummary: { varStale, varRoll, varOk, varStatic, formsLive: forms.length, formsLcm: kbForms.length, rules: rules.length, jobs: jobs.length, failedJobs: failedJobs.length }
    };
  }

  if (kind === "navigation") {
    const nodes = Array.isArray(opts.navigation) ? opts.navigation : [];
    const tkb = opts.tenantKb || null;
    const lcmFlows = (tkb && Array.isArray(tkb.navigationFlows)) ? tkb.navigationFlows : [];
    const kbForms = (tkb && Array.isArray(tkb.forms)) ? tkb.forms : [];
    const formByName = new Map(kbForms.map(f => [String(f.name||"").trim().toLowerCase(), f]));
    const kbDashboards = (tkb && Array.isArray(tkb.dashboards)) ? tkb.dashboards : [];
    const dashByName = new Map(kbDashboards.map(d => [String(d.name||"").trim().toLowerCase(), d]));
    const kbReports = (tkb && Array.isArray(tkb.financialReports)) ? tkb.financialReports : [];
    const reportByName = new Map(kbReports.map(r => [String(r.name||"").trim().toLowerCase(), r]));
    const variantsOfName = (name) => {
      const k = String(name||"").trim().toLowerCase();
      if (!k) return [];
      const stripReport = k.replace(/\s+report(s)?\s*$/, "");
      const stripDash = k.replace(/\s+dashboard\s*$/, "");
      const out = new Set();
      for (const base of [k, stripReport, stripDash]) {
        out.add(base);
        out.add(base.replace(/^nfs_/, ""));
        out.add(base.replace(/\.$/, ""));
        out.add(base.replace(/^nfs_/, "").replace(/\.$/, ""));
        out.add("nfs_" + base);
        out.add("nfs_" + base + ".");
        out.add(base + ".");
      }
      return [...out];
    };
    const findFormFuzzy = (name) => {
      for (const v of variantsOfName(name)) if (formByName.has(v)) return formByName.get(v);
      return null;
    };
    const findDashFuzzy = (name) => {
      for (const v of variantsOfName(name)) if (dashByName.has(v)) return dashByName.get(v);
      return null;
    };
    const findReportFuzzy = (name) => {
      for (const v of variantsOfName(name)) if (reportByName.has(v)) return reportByName.get(v);
      return null;
    };

    const grid = [
      ["Navigation Flow — NSPB menu tree", "", "", "", "", "", "", "", ""],
      ["", "", "", "", "", "", "", "", ""],
      [`Last refreshed: ${today}  ·  ${lcmFlows.length} LCM flows  ·  ${nodes.length} live nodes  ·  Click 'Nav' in Settings to refresh`, "", "", "", "", "", "", "", ""],
      ["Status legend: 🟢 form (input) · 🔵 form (review) · 🟣 dashboard · ⚫ navigation card · 🟡 form description · 🟦 rules + rule descriptions · ⚡ runs on save · FR reports hidden", "", "", "", "", "", "", "", ""],
      ["", "", "", "", "", "", "", "", ""]
    ];
    const sectionRows = [];
    const matchedForms = new Map(); // name -> form (for chip emission)

    // Build a rule-name → description lookup so we can inline rule purposes.
    const kbRules = (tkb && Array.isArray(tkb.rules)) ? tkb.rules : [];
    const ruleDescByName = new Map();
    for (const r of kbRules) {
      const nm = (r.name || "").trim();
      if (nm) ruleDescByName.set(nm.toLowerCase(), r.description || "");
    }

    // 1) LCM-derived flows. One row PER TAB so we can mark which tabs are forms.
    if (lcmFlows.length) {
      grid.push(["LCM navigation flows (Flow → Module → Form/Tab)", "", "", "", "", "", "", "", ""]);
      sectionRows.push(grid.length - 1);
      grid.push(["Flow", "Module / Card", "Form / Tab Name", "Type", "Form Cube", "Form Description", "Attached Rules", "Rule Descriptions", "Form ID"]);
      for (const flow of lcmFlows) {
        const flowName = flow.name || flow.id || "(unnamed)";
        const mods = Array.isArray(flow.modules) ? flow.modules : [];
        if (!mods.length) {
          grid.push([flowName, "(no modules)", "", "", "", "", "", "", ""]);
          continue;
        }
        let firstFlowRow = true;
        for (const m of mods) {
          const tabs = Array.isArray(m.tabs) ? m.tabs : [];
          if (!tabs.length) {
            grid.push([firstFlowRow ? flowName : "", m.module || "", "(no tabs)", "", "", "", "", "", ""]);
            firstFlowRow = false;
            continue;
          }
          let firstModRow = true;
          let emittedAnyForThisModule = false;
          // Schema v4+: prefer tabsDetail (explicit type + artifactName from LCM nav XML).
          // Fall back to plain tabs[] for older KBs.
          const detailedTabs = Array.isArray(m.tabsDetail) && m.tabsDetail.length
            ? m.tabsDetail
            : (m.tabs || []).map(label => ({ label, artifactName: "", type: "" }));
          for (const td of detailedTabs) {
            const tabLabel = td.label || td;
            const aname = td.artifactName || tabLabel;
            const navType = td.type || "";   // 'form' / 'dashboard' / 'report' / ''
            // Use type from nav flow as authoritative when present.
            const f = findFormFuzzy(aname) || findFormFuzzy(tabLabel);
            if (navType === "form" || (!navType && f)) {
              if (f) {
                const kindLabel = (f.kind === "review" || (!f.kind && f.isInput === false))
                  ? "form (review)" : "form (input)";
                const ruleNames = Array.isArray(f.attachedRules)
                  ? f.attachedRules.map(r => (r.runOnSave ? "⚡ " : "") + (r.name||"")).filter(Boolean).join("\n")
                  : "";
                const ruleDescs = Array.isArray(f.attachedRules)
                  ? f.attachedRules.map(r => ruleDescByName.get((r.name||"").toLowerCase()) || r.description || "—").join("\n")
                  : "";
                grid.push([
                  firstFlowRow ? flowName : "",
                  firstModRow ? (m.module || "") : "",
                  tabLabel, kindLabel, f.cube || "", f.description || "",
                  ruleNames, ruleDescs, f.formId || ""
                ]);
                matchedForms.set(f.name, f);
              } else {
                // Form referenced by nav but not in kb.forms (Oracle OOTB)
                grid.push([
                  firstFlowRow ? flowName : "",
                  firstModRow ? (m.module || "") : "",
                  tabLabel, "form (input) · OOTB", "(live)", `OOTB form — artifact: ${aname}`,
                  "", "", ""
                ]);
              }
              firstFlowRow = false; firstModRow = false; emittedAnyForThisModule = true;
              continue;
            }
            if (navType === "dashboard") {
              const d = findDashFuzzy(aname) || findDashFuzzy(tabLabel);
              const refs = d && d.referencedForms ? d.referencedForms.map(r => r.name).join(", ") : "";
              grid.push([
                firstFlowRow ? flowName : "",
                firstModRow ? (m.module || "") : "",
                tabLabel, "📊 dashboard (read-only, NSPB web only)",
                d ? (d.cube || "(global)") : "(OOTB)",
                d ? (d.description || d.title || "") : `OOTB dashboard — artifact: ${aname}`,
                refs ? `references: ${refs}` : "",
                "", ""
              ]);
              firstFlowRow = false; firstModRow = false; emittedAnyForThisModule = true;
              continue;
            }
            if (navType === "report") continue; // FR reports hidden as requested
            // Legacy fallback (no navType from nav flow XML — old schema)
            const dLegacy = findDashFuzzy(tabLabel);
            if (dLegacy) {
              const refs = (dLegacy.referencedForms || []).map(r => r.name).join(", ");
              grid.push([
                firstFlowRow ? flowName : "",
                firstModRow ? (m.module || "") : "",
                tabLabel, "📊 dashboard (read-only, NSPB web only)",
                dLegacy.cube || "(global)", dLegacy.description || dLegacy.title || "",
                refs ? `references: ${refs}` : "",
                "", ""
              ]);
              firstFlowRow = false; firstModRow = false; emittedAnyForThisModule = true;
              continue;
            }
            if (findReportFuzzy(tabLabel)) continue; // FR hidden
            // Composite navigation page
            grid.push([
              firstFlowRow ? flowName : "",
              firstModRow ? (m.module || "") : "",
              tabLabel, "🧭 navigation card (composite page, NSPB web only)",
              "", "Composite page combining multiple forms/charts at runtime — not a single artifact in LCM.", "", "", ""
            ]);
            firstFlowRow = false; firstModRow = false; emittedAnyForThisModule = true;
          }
        }
        grid.push(["", "", "", "", "", "", "", "", ""]);
      }
    }

    // 2) Live-discovered tree (raw nav API). Optional.
    if (nodes.length) {
      grid.push(["Live-discovered nodes (from /api/discover-navigation)", "", "", "", "", "", "", "", ""]);
      sectionRows.push(grid.length - 1);
      grid.push(["Name (indented by depth)", "Type", "ID", "Object", "Parent", "", "", "", ""]);
      const sorted = nodes.slice().sort((a, b) => (a.fqId || "").localeCompare(b.fqId || ""));
      for (const n of sorted) {
        const indent = "  ".repeat(n.depth || 0);
        grid.push([indent + (n.name || n.id), n.type || "", n.id, n.leafObjectType ? `${n.leafObjectType}:${n.leafObjectId}` : "", n.parentFqId || "(root)", "", "", "", ""]);
      }
    } else if (!lcmFlows.length) {
      grid.push(["(none discovered yet)", "", "", "", "Click 'Nav' in Settings.", "", "", "", ""]);
    }

    grid.push(["", "", "", "", "", "", "", "", ""]);
    grid.push(["Tip", "Forms are openable — click a chip below the chat or type 'open <name>'. The 'Form Description' and 'Attached Rules' columns include each rule's purpose for context.", "", "", "", "", "", "", ""]);
    sectionRows.push(grid.length - 1);

    // Chips — one Open chip per unique form found across all flows.
    const navChips = [...matchedForms.keys()].slice(0, 30).map(n => `Open ${n} → open ${n}`);

    return {
      sheetName: "NSPB_Navigation",
      grid,
      gridDescriptor: null,
      inPlace: true,
      format: "help",
      sectionRows,
      navChips,
      matchedFormCount: matchedForms.size
    };
  }

  if (kind === "applications") {
    const applications = Array.isArray(opts.applications) ? opts.applications : [];
    const sourceSystems = Array.isArray(opts.sourceSystems) ? opts.sourceSystems : [];
    const grid = [
      ["DM Applications & Source Systems — discovered inventory", "", "", "", ""],
      ["", "", "", "", ""],
      [`Last refreshed: ${today}  ·  ${applications.length} apps  ·  ${sourceSystems.length} source systems`, "", "", "", ""],
      ["", "", "", "", ""],
      ["Applications (registered in DM)", "", "", "", ""]
    ];
    const sectionRows = [grid.length - 1];
    grid.push(["Name", "Type", "Category", "Target Class", "Description"]);
    if (!applications.length) {
      grid.push(["(none discovered)", "", "", "", ""]);
    } else {
      for (const a of applications) {
        grid.push([a.name, a.type, a.category, a.targetClass, a.description]);
      }
    }
    grid.push(["", "", "", "", ""]);
    grid.push(["Source Systems", "", "", "", ""]);
    sectionRows.push(grid.length - 1);
    grid.push(["Name", "Type", "Description", "", ""]);
    if (!sourceSystems.length) {
      grid.push(["(none discovered)", "", "", "", ""]);
    } else {
      for (const s of sourceSystems) grid.push([s.name, s.type, s.description, "", ""]);
    }
    grid.push(["", "", "", "", ""]);
    grid.push(["Tip", "Apps describe WHERE data goes (NSPB, GL files, ERP). Integrations (= 'show me integrations') describe HOW data moves between them.", "", "", ""]);
    sectionRows.push(grid.length - 1);
    return { sheetName: "NSPB_Applications", grid, gridDescriptor: null, inPlace: true, format: "help", sectionRows };
  }

  if (kind === "periodmappings") {
    const mappings = Array.isArray(opts.periodMappings) ? opts.periodMappings : [];
    const grid = [
      ["Period Mappings — DM ↔ EPM bridge", "", "", ""],
      ["", "", "", ""],
      [`Last refreshed: ${today}  ·  ${mappings.length} mappings  ·  Click 'PMap' in Settings to refresh`, "", "", ""],
      ["", "", "", ""],
      ["Source Period", "Target Period", "Year", "Period Key"]
    ];
    if (!mappings.length) {
      grid.push(["(none discovered yet)", "", "", "Click 'PMap' in Settings."]);
    } else {
      for (const m of mappings) grid.push([m.sourcePeriod, m.targetPeriod, m.year, m.periodKey]);
    }
    grid.push(["", "", "", ""]);
    grid.push(["Tip", "Used by Data Management to translate source-system periods (e.g. Jan-2026) to EPM periods (TP1.FY26).", "", ""]);
    const sectionRows = [grid.length - 1];
    return { sheetName: "NSPB_PeriodMappings", grid, gridDescriptor: null, inPlace: true, format: "help", sectionRows };
  }

  if (kind === "savedqueries") {
    const queries = Array.isArray(opts.savedQueries) ? opts.savedQueries : [];
    const grouped = { Data: [], Metadata: [], Export: [], Other: [] };
    for (const q of queries) (grouped[q.targetObject] || grouped.Other).push(q);
    const grid = [
      ["NSPB Data Sources / Saved Searches — registered DATASOURCE apps", "", "", ""],
      ["", "", "", ""],
      [`Last refreshed: ${today}  ·  ${queries.length} sources (Data: ${grouped.Data.length} · Metadata: ${grouped.Metadata.length} · Export: ${grouped.Export.length})`, "", "", ""],
      ["", "", "", ""]
    ];
    const sectionRows = [];
    const pushGroup = (label, items) => {
      if (!items.length) return;
      grid.push([label, "", "", ""]);
      sectionRows.push(grid.length - 1);
      grid.push(["Name", "Subtype", "Description", ""]);
      for (const q of items) grid.push([q.name, q.type, q.description, ""]);
      grid.push(["", "", "", ""]);
    };
    pushGroup(`Data sources (${grouped.Data.length})`, grouped.Data);
    pushGroup(`Metadata sources (${grouped.Metadata.length})`, grouped.Metadata);
    pushGroup(`Export targets (${grouped.Export.length})`, grouped.Export);
    if (grouped.Other.length) pushGroup(`Other (${grouped.Other.length})`, grouped.Other);

    grid.push(["Tip", "Data sources are NSPB-side wrappers around NetSuite saved searches. The full NetSuite saved-search ID isn't exposed via Basic Auth — only the NSPB application name. To see the actual NS query, open Data Exchange → Data Source in the NSPB UI.", "", ""]);
    sectionRows.push(grid.length - 1);
    return { sheetName: "NSPB_SavedQueries", grid, gridDescriptor: null, inPlace: true, format: "help", sectionRows };
  }

  if (kind === "locations") {
    const locations = Array.isArray(opts.locations) ? opts.locations : [];
    const grid = [
      ["Data Management Locations", "", "", "", ""],
      ["", "", "", "", ""],
      [`Last refreshed: ${today}  ·  ${locations.length} locations`, "", "", "", ""],
      ["", "", "", "", ""],
      ["Name", "Source App", "Target App", "Parent", "Description"]
    ];
    if (!locations.length) grid.push(["(none discovered)", "", "", "", ""]);
    else for (const l of locations) grid.push([l.name, l.sourceApp, l.targetApp, l.parent, l.description]);

    grid.push(["", "", "", "", ""]);
    grid.push(["Tip", "Locations group data rules. Each location has a target Planning app and optional source app. Parent locations form a hierarchy.", "", "", ""]);
    const sectionRows = [grid.length - 1];
    return { sheetName: "NSPB_Locations", grid, gridDescriptor: null, inPlace: true, format: "help", sectionRows };
  }

  if (kind === "jobtypes") {
    const jobtypes = Array.isArray(opts.jobtypes) ? opts.jobtypes : [];
    const grid = [
      ["Schedulable Job Types — Pipeline catalog", "", "", "", ""],
      ["", "", "", "", ""],
      [`Last refreshed: ${today}  ·  ${jobtypes.length} job types available for scheduling`, "", "", "", ""],
      ["", "", "", "", ""],
      ["Name", "Type ID", "Category", "Connection", "Description"]
    ];
    if (!jobtypes.length) grid.push(["(none discovered)", "", "", "", ""]);
    else for (const j of jobtypes) grid.push([j.name, j.id, j.category, j.connection, j.description]);

    grid.push(["", "", "", "", ""]);
    grid.push(["Tip", "Job types are the building blocks of pipelines (Schedule Jobs view in NSPB). Pipelines chain these together.", "", "", ""]);
    const sectionRows = [grid.length - 1];
    return { sheetName: "NSPB_JobTypes", grid, gridDescriptor: null, inPlace: true, format: "help", sectionRows };
  }

  if (kind === "schedules") {
    const schedules = Array.isArray(opts.schedules) ? opts.schedules : [];
    // Group by job type so Clear Cube / Export Data / Rules read as sections.
    const byType = new Map();
    for (const s of schedules) {
      const t = s.type || "OTHER";
      if (!byType.has(t)) byType.set(t, []);
      byType.get(t).push(s);
    }
    const grid = [
      ["Scheduled Jobs — saved job definitions", "", "", ""],
      ["", "", "", ""],
      [`Last refreshed: ${today}  ·  ${schedules.length} job definitions`, "", "", ""],
      ["", "", "", ""]
    ];
    const sectionRows = [];
    if (!schedules.length) {
      grid.push([opts.schedulesError
        ? `⚠ Could not fetch job definitions: ${String(opts.schedulesError).slice(0, 180)}`
        : "(no saved job definitions found)", "", "", ""]);
    } else {
      for (const [t, items] of byType) {
        grid.push([`${t} (${items.length})`, "", "", ""]);
        sectionRows.push(grid.length - 1);
        grid.push(["Job name", "Type", "", ""]);
        for (const s of items) grid.push([s.name, s.type, "", ""]);
        grid.push(["", "", "", ""]);
      }
    }
    grid.push(["Tip", "These are the saved jobs the NSPB scheduler runs. Cron timing / next-run isn't exposed via REST — see Application → Jobs → Scheduled Jobs in the NSPB UI for the calendar. Say 'show me recent jobs' for what actually ran.", "", ""]);
    sectionRows.push(grid.length - 1);
    return { sheetName: "NSPB_ScheduledJobs", grid, gridDescriptor: null, inPlace: true, format: "help", sectionRows };
  }

  throw new Error(`show_inventory: unsupported kind "${kind}"`);
}

// Per-DM-job detail renderer. Uses /aif/rest/V1/jobs/{id} (Basic-Auth REST
// API). Earlier versions used /aif/ui/model/job/process/detail/{id} but that
// endpoint requires a session cookie which Basic Auth from a Worker can't
// produce — it returns 401. The REST endpoint works but exposes fewer fields
// (no per-line error log, no transformations table). What we DO get: jobId,
// jobStatus, logFileName, outputFileName, processType, executedBy, etc.
async function runShowDmDetails(settings, args) {
  const processId = args && (args.processId || args.process_id || args.id);
  if (!processId) throw new Error("show_dm_details: processId required");
  const host = String(settings.host).replace(/\/+$/, "");
  const auth = basicAuth(settings.username, settings.password);
  const url = `${host}/aif/rest/V1/jobs/${encodeURIComponent(processId)}`;
  let data;
  try {
    const r = await fetch(url, {
      method: "GET",
      headers: { "Authorization": auth, "Accept": "application/json" }
    });
    const t = await r.text();
    if (!r.ok) throw new Error(`${r.status}: ${t.slice(0, 100)}`);
    data = t ? JSON.parse(t) : {};
  } catch (e) {
    throw new Error(`show_dm_details: fetch failed for processId ${processId} — ${e.message || e}`);
  }

  // /aif/rest/V1/jobs/{id} returns a flat object: jobId, jobStatus,
  // logFileName, outputFileName, processType, executedBy. No errors[] /
  // transformations[] arrays — those would require the session-auth UI API.
  // Field-aliases below cover both REST V1 shape and the legacy UI shape so
  // tenants that DO expose the UI endpoint via Basic Auth still work.
  const overview = {
    processId:   data.jobId || data.processId || processId,
    jobName:     data.jobName || data.processName || data.integrationName || data.processType || "",
    status:      data.jobStatus || data.processStatus || data.status || "",
    sourceApp:   data.sourceApplication || data.sourceApp || "",
    targetApp:   data.targetApplication || data.targetApp || "",
    period:      data.period || "",
    startTime:   data.startTime || data.executionStart || "",
    endTime:     data.endTime || data.executionEnd || "",
    user:        data.executedBy || data.userName || data.submittedBy || "",
    sourceRows:  data.sourceRowCount || data.totalSourceRows || "",
    targetRows:  data.targetRowCount || data.totalTargetRows || "",
    errorCount:  data.errorCount || 0,
    logFile:     data.logFileName || data.logFile || "",
    outputFile:  data.outputFileName || data.outputFile || "",
    processType: data.processType || ""
  };
  const errors = Array.isArray(data.errors) ? data.errors :
                 Array.isArray(data.errorList) ? data.errorList :
                 Array.isArray(data.details) ? data.details : [];
  const transforms = Array.isArray(data.transformations) ? data.transformations :
                     Array.isArray(data.mappings) ? data.mappings : [];

  const grid = [
    [`DM Process Detail — ${overview.jobName || processId}`, "", "", ""],
    ["", "", "", ""],
    ["Process ID", overview.processId, "Status", overview.status],
    ["Process Type", overview.processType, "User", overview.user],
    ["Source App", overview.sourceApp, "Target App", overview.targetApp],
    ["Period", overview.period, "Errors", overview.errorCount],
    ["Started", overview.startTime, "Ended", overview.endTime],
    ["Log file", overview.logFile, "Output file", overview.outputFile],
    ["", "", "", ""]
  ];
  const sectionRows = [];
  if (errors.length) {
    grid.push([`Errors (${errors.length})`, "", "", ""]);
    sectionRows.push(grid.length - 1);
    grid.push(["Line/Step", "Severity", "Message", "Detail"]);
    for (const e of errors.slice(0, 100)) {
      grid.push([e.line || e.step || "", e.severity || e.level || "", e.message || e.msg || "", e.detail || ""]);
    }
    grid.push(["", "", "", ""]);
  }
  if (transforms.length) {
    grid.push([`Transformations (${transforms.length})`, "", "", ""]);
    sectionRows.push(grid.length - 1);
    grid.push(["Step", "Source Value", "Target Value", "Note"]);
    for (const t of transforms.slice(0, 100)) {
      grid.push([t.step || t.name || "", t.sourceValue || "", t.targetValue || "", t.note || ""]);
    }
    grid.push(["", "", "", ""]);
  }
  if (!errors.length && !transforms.length) {
    grid.push(["(no errors or transformations returned)", "", "", ""]);
  }
  return {
    sheetName:      `DM_Job_${processId}`.slice(0, 30),
    grid,
    gridDescriptor: null,
    inPlace:        true,
    format:         "help",
    sectionRows
  };
}

// ── Generic AIF GET helper ─────────────────────────────────────────────────
// Most /aif/ui/model/* endpoints share the same auth + JSON-decode boilerplate.
// Centralizes the host-trim + Basic auth + non-ok throw so each new fetcher
// is a one-liner. NOT for SmartView XML — those go through nspbXmlPost.
async function aifGet(settings, urlPath) {
  const host = String(settings.host).replace(/\/+$/, "");
  const auth = basicAuth(settings.username, settings.password);
  const r = await fetch(host + urlPath, {
    method: "GET",
    headers: { "Authorization": auth, "Accept": "application/json" }
  });
  const t = await r.text();
  if (!r.ok) throw new Error(`${r.status} ${urlPath}: ${t.slice(0, 100)}`);
  return t ? JSON.parse(t) : {};
}

// ── Saved queries / Locations / Job types ──────────────────────────────────
// These all live exclusively under /aif/ui/model/* which requires NSPB session
// auth — Basic Auth from a Worker returns 401 for every variant. None have a
// /aif/rest/V1/* equivalent. We return empty + a note so the inventory sheets
// render with a clear "view in NSPB UI" message instead of crashing.
async function runDiscoverSavedQueries(settings) {
  // Saved searches in NSPB live as DATASOURCE applications (subType=NETSUITE
  // for NetSuite-backed saved searches, DATAEXPORT for NSPB-side exports).
  // The /aif/ui/model/query endpoint requires session auth and returns 401,
  // but /aif/rest/V1/applications accepts Basic Auth and exposes the same
  // info via the apps list. Naming convention: "NSPB (Data) PF <name>" or
  // "NSPB (Metadata) PF <name>".
  try {
    const data = await aifGet(settings, "/aif/rest/V1/applications");
    const items = data.items || [];
    const queries = items
      .filter(a => /DATASOURCE/i.test(a.applicationType || ""))
      .map(a => {
        const name = a.applicationName || "";
        // Extract category from name prefix (Data vs Metadata vs Export).
        let category = "Other";
        if (/NSPB\s*\(Data\)/i.test(name))     category = "Data";
        else if (/NSPB\s*\(Metadata\)/i.test(name)) category = "Metadata";
        else if (a.applicationSubType === "DATAEXPORT") category = "Export";
        else if (a.applicationSubType === "NETSUITE") category = "NetSuite";
        return {
          name,
          displayName:  name,
          type:         a.applicationSubType || "DATASOURCE",  // NETSUITE / DATAEXPORT / FILE
          targetObject: category,
          description:  `App ID ${a.applicationId || "?"}`,
          custom:       false
        };
      });
    return { loadedAt: Date.now(), queries };
  } catch (e) {
    return { loadedAt: Date.now(), queries: [], error: String(e.message || e) };
  }
}
async function runDiscoverLocations(settings) {
  return {
    loadedAt: Date.now(),
    locations: [],
    error: "endpoint requires NSPB session auth (Basic Auth gives 401) — view in NSPB UI: Application → Data Exchange → Locations"
  };
}
async function runDiscoverJobtypes(settings) {
  return {
    loadedAt: Date.now(),
    jobtypes: [],
    error: "endpoint requires NSPB session auth (Basic Auth gives 401) — view in NSPB UI: Application → Data Exchange → Schedule Jobs"
  };
}
// Scheduled jobs = saved job definitions in Planning. The Planning v3
// `jobdefinitions` resource accepts Basic Auth and lists every saved job
// (Clear Cube / Export Data / Refresh / Rules…) — the objects the scheduler
// runs. Cron expressions / next-run times are NOT exposed via any Basic-Auth
// REST endpoint (probeScheduleEndpoints confirmed all candidates 401/404),
// so the sheet says where to see timing in the UI.
async function runDiscoverSchedules(settings) {
  try {
    const data = await nspbGet(settings, "/jobdefinitions");
    const items = Array.isArray(data && data.items) ? data.items : [];
    const schedules = items.map(j => ({
      name: j.jobName || j.name || "",
      type: j.jobType || j.type || "",
    }));
    return { loadedAt: Date.now(), schedules };
  } catch (e) {
    return { loadedAt: Date.now(), schedules: [], error: String(e.message || e) };
  }
}

// ── Per-integration deep detail ────────────────────────────────────────────
// All required endpoints (/aif/ui/model/integration/datarule/{id},
// /aif/ui/model/rules/{name}/options, /aif/ui/model/businessrules?...) require
// NSPB session auth — Basic Auth from a Worker returns 401. Render an
// explanatory sheet instead of crashing so the user knows the limitation.
async function runShowIntegrationDetail(settings, args) {
  const wanted = String((args && (args.integrationName || args.name || args.rule)) || "").trim();
  if (!wanted) throw new Error("show_integration_detail: integrationName required");

  const today = new Date().toISOString().slice(0, 10);
  const grid = [
    [`Integration Detail — ${wanted}`, "", "", ""],
    ["", "", "", ""],
    [`Last refreshed: ${today}  ·  feature unavailable in this build`, "", "", ""],
    ["", "", "", ""],
    ["⚠ Endpoint requires NSPB session authentication", "", "", ""],
    ["", "", "", ""],
    ["The deep-detail tool needs four NSPB UI endpoints to fan out:", "", "", ""],
    ["  • /aif/ui/model/integration/datarule/{id}  (overview)", "", "", ""],
    ["  • /aif/ui/model/rules/{name}/options?type=sourceFilters", "", "", ""],
    ["  • /aif/ui/model/rules/{name}/options?type=targetOptions", "", "", ""],
    ["  • /aif/ui/model/businessrules?scriptEntityScope=DATARULE&...  (attached BR)", "", "", ""],
    ["", "", "", ""],
    ["All four require an Oracle session cookie (JSESSIONID), which", "", "", ""],
    ["only the NSPB browser UI can establish. The worker uses Basic Auth", "", "", ""],
    ["which Oracle accepts only on the Planning REST + /aif/rest/V1/* APIs.", "", "", ""],
    ["", "", "", ""],
    ["Workaround", "Open the NSPB UI: Application → Data Exchange → click the integration → Edit", "", ""],
    ["See", `'show me integrations' (kind='integrations') gives partial info from /aif/rest/V1/jobs?type=DATARULE`, "", ""]
  ];
  const sectionRows = [4, 16];
  return {
    sheetName: `Integ_${wanted.slice(0, 22)}`,
    grid,
    gridDescriptor: null,
    inPlace: true,
    format: "help",
    sectionRows
  };
}
