// Legacy implementation below — kept for reference, unreachable.
async function _runShowMappingLegacy(settings, args) {
  const rule = String((args && (args.rule || args.ruleName)) || "").trim();
  if (!rule) throw new Error("show_mapping: rule required");
  const dim = args && args.dim ? String(args.dim).trim() : "";

  const grid = [];
  const sectionRows = [];
  const today = new Date().toISOString().slice(0, 10);

  if (!dim) {
    // SUMMARY mode
    let header;
    try { header = await aifGet(settings, `/aif/ui/model/mapping/rule/${encodeURIComponent(rule)}`); }
    catch (e) { throw new Error(`show_mapping: rule "${rule}" not found — ${e.message || e}`); }

    const dims = header.dimensions || header.dims || [];
    grid.push([`Mapping Summary — ${rule}`, "", "", ""]);
    grid.push(["", "", "", ""]);
    grid.push([`Last refreshed: ${today}  ·  ${dims.length} dimensions  ·  Type: ${header.ruleType || header.type || "DATASOURCE"}`, "", "", ""]);
    grid.push(["", "", "", ""]);
    grid.push(["Rule Header", "", "", ""]);
    sectionRows.push(grid.length - 1);
    grid.push(["Field", "Value", "", ""]);
    grid.push(["Rule Name",     header.ruleName || rule, "", ""]);
    grid.push(["Rule Type",     header.ruleType || "", "", ""]);
    grid.push(["Source App",    header.sourceApplicationName || "", "", ""]);
    grid.push(["Target App",    header.targetApplicationName || "", "", ""]);
    grid.push(["Location",      header.locationName || "", "", ""]);
    grid.push(["Import Format", header.importFormatName || "", "", ""]);

    grid.push(["", "", "", ""]);
    grid.push(["Dimensions in this rule", "", "", ""]);
    sectionRows.push(grid.length - 1);
    grid.push(["Source Dim", "Target Dim", "Type", "Notes"]);
    if (!dims.length) grid.push(["(no dimensions)", "", "", ""]);
    else for (const d of dims) grid.push([d.sourceDimensionName || d.sourceDim || "", d.targetDimensionName || d.targetDim || d.dimensionName || "", d.dimensionType || d.type || "", d.description || ""]);

    grid.push(["", "", "", ""]);
    grid.push(["Tip", `To see the full mapping rows for one dim, ask: 'show mapping for ${rule} <dim>' (e.g. ACCOUNT, ENTITY).`, "", ""]);
    sectionRows.push(grid.length - 1);

    return {
      sheetName: `Mapping_${rule.slice(0, 22)}`,
      grid,
      gridDescriptor: null,
      inPlace: true,
      format: "help",
      sectionRows
    };
  }

  // DETAIL mode — paginate membermapping
  const PAGE = 100;
  const MAX_PAGES = 50;
  const MAX_ROWS = 5000;
  const dimUp = dim.toUpperCase();
  const all = [];
  let truncated = false, lastError = null;
  for (let p = 0; p < MAX_PAGES; p++) {
    const offset = p * PAGE;
    let data;
    try {
      data = await aifGet(settings,
        `/aif/ui/model/mapping/membermapping/${encodeURIComponent(rule)}/${encodeURIComponent(dimUp)}?limit=${PAGE}&offset=${offset}&povMapType=NONE`);
    } catch (e) { lastError = String(e.message || e); break; }
    const items = data.items || data.mappings || data.list || (Array.isArray(data) ? data : []);
    if (!items.length) break;
    for (const m of items) {
      all.push({
        source:    m.sourceMember || m.sourceValue || m.source || "",
        target:    m.targetMember || m.targetValue || m.target || "",
        rule:      m.rule || m.ruleType || m.mappingRuleType || "",
        order:     m.processOrder || m.order || "",
        description: m.description || ""
      });
      if (all.length >= MAX_ROWS) { truncated = true; break; }
    }
    if (truncated || items.length < PAGE) break;
  }

  grid.push([`Mapping — ${rule} / ${dimUp}`, "", "", "", ""]);
  grid.push(["", "", "", "", ""]);
  const note = truncated
    ? `Last refreshed: ${today}  ·  ${all.length}+ rows (capped at ${MAX_ROWS})`
    : `Last refreshed: ${today}  ·  ${all.length} mapping rows`;
  grid.push([note, "", "", "", ""]);
  if (lastError) grid.push([`⚠ Partial result: ${lastError}`, "", "", "", ""]);
  grid.push(["", "", "", "", ""]);
  grid.push(["Source Member", "Target Member", "Rule Type", "Order", "Description"]);
  if (!all.length) grid.push(["(no mappings found)", "", "", "", ""]);
  else for (const m of all) grid.push([m.source, m.target, m.rule, m.order, m.description]);

  grid.push(["", "", "", "", ""]);
  grid.push(["Tip", "Rule types: EXPLICIT (1:1), BETWEEN (range), IN (list), MULTI (regex), LIKE (wildcard). Lower 'Order' wins ties.", "", "", ""]);
  const sectionRowsOut = [grid.length - 1];

  return {
    sheetName: `Map_${rule.slice(0, 12)}_${dimUp.slice(0, 12)}`,
    grid,
    gridDescriptor: null,
    inPlace: true,
    format: "help",
    sectionRows: sectionRowsOut
  };
}

// ── Per-pipeline detail ────────────────────────────────────────────────────
async function runShowPipeline(settings, args) {
  const wanted = String((args && (args.pipelineName || args.name)) || "").trim();
  if (!wanted) throw new Error("show_pipeline: pipelineName required");

  // /aif/rest/V1/pipeline accepts Basic Auth and returns ALL pipelines wrapped
  // in {response:[...]}. The ?name= query param is ignored server-side, so we
  // filter client-side. The session-auth UI variant (/aif/ui/model/V1/pipeline?
  // pipelineName=X) returns 401 from a Worker.
  let detail;
  try {
    detail = await aifGet(settings, "/aif/rest/V1/pipeline");
  } catch (e) {
    throw new Error("show_pipeline: " + (e.message || e));
  }
  const all = detail && (detail.response || detail.items || detail.pipelines) || (Array.isArray(detail) ? detail : []);
  const lower = wanted.toLowerCase();
  const pipe = all.find(p => String(p.name || p.pipelineName || "").toLowerCase() === lower) ||
               all.find(p => String(p.displayName || "").toLowerCase() === lower) ||
               all.find(p => String(p.name || "").toLowerCase().includes(lower));
  if (!pipe) {
    throw new Error(`show_pipeline: "${wanted}" not found among ${all.length} pipelines`);
  }

  const grid = [];
  const sectionRows = [];
  const today = new Date().toISOString().slice(0, 10);
  grid.push([`Pipeline Detail — ${pipe.name || wanted}`, "", "", ""]);
  grid.push(["", "", "", ""]);
  grid.push([`Last refreshed: ${today}  ·  pipeline ID ${pipe.pipelineId || pipe.id || "(unknown)"}`, "", "", ""]);
  grid.push(["", "", "", ""]);

  grid.push(["Overview", "", "", ""]);
  sectionRows.push(grid.length - 1);
  grid.push(["Field", "Value", "Field", "Value"]);
  const kv = [
    ["Name",         pipe.name || wanted],
    ["Description",  pipe.description || ""],
    ["Owner",        pipe.owner || pipe.createdBy || ""],
    ["Last Run",     pipe.lastRun || pipe.lastRunTime || ""],
    ["Status",       pipe.status || pipe.lastStatus || ""],
    ["Schedule",     pipe.schedule || pipe.cronExpression || ""]
  ];
  for (let i = 0; i < kv.length; i += 2) {
    const a = kv[i], b = kv[i + 1] || ["", ""];
    grid.push([a[0], a[1], b[0], b[1]]);
  }

  // Variables
  grid.push(["", "", "", ""]);
  grid.push(["Pipeline Variables", "", "", ""]);
  sectionRows.push(grid.length - 1);
  grid.push(["Name", "Default Value", "Type", "Description"]);
  const vars = pipe.variables || pipe.pipelineVariables || [];
  if (!vars.length) grid.push(["(no variables defined)", "", "", ""]);
  else for (const v of vars) grid.push([v.name || "", v.defaultValue || v.value || "", v.type || "", v.description || ""]);

  // Stages / jobs
  grid.push(["", "", "", ""]);
  grid.push(["Stages / Jobs (in execution order)", "", "", ""]);
  sectionRows.push(grid.length - 1);
  grid.push(["Step", "Job Name", "Job Type", "Notes"]);
  const stages = pipe.stages || pipe.steps || pipe.jobs || [];
  if (!stages.length) grid.push(["(no stages defined)", "", "", ""]);
  else stages.forEach((s, i) => {
    grid.push([i + 1, s.name || s.jobName || "", s.type || s.jobType || "", s.description || s.notes || ""]);
  });

  grid.push(["", "", "", ""]);
  grid.push(["Tip", "Pipelines orchestrate sequences of jobs. Variables let one pipeline parameterize multiple environments. Execution from this add-in isn't wired yet.", "", ""]);
  sectionRows.push(grid.length - 1);

  return {
    sheetName: `Pipe_${(pipe.name || wanted).slice(0, 23)}`,
    grid,
    gridDescriptor: null,
    inPlace: true,
    format: "help",
    sectionRows
  };
}

