// Truncate a JSON-serializable value to a short human-readable string for
// debug traces. Keeps the chat transcript scannable.
function truncateForTrace(value, max) {
  let s;
  try { s = JSON.stringify(value); } catch { s = String(value); }
  if (s == null) s = "";
  return s.length > max ? s.slice(0, max) + "…" : s;
}

// ── MS engagement hours: live refresh from NetSuite ──────────────────────────
// POST /api/ms-hours/refresh {envKey} → re-queries NetSuite (SuiteQL over REST,
// Token-Based Auth) and updates the Customer Hub's client_engagement/{envKey}
// snapshot in Firestore (via its REST API — the doc is get/write-open by rules).
// Requires five worker secrets, created once by a NetSuite admin:
//   NS_ACCOUNT (e.g. 7282750), NS_CONSUMER_KEY, NS_CONSUMER_SECRET,
//   NS_TOKEN_ID, NS_TOKEN_SECRET
// Until they exist the endpoint answers 503 netsuite-not-provisioned and the
// hub button explains itself. The snapshot must carry `ns.jobId` (the NetSuite
// job/sub-customer id) so the worker knows what to query.

const FIRESTORE_BASE = "https://firestore.googleapis.com/v1/projects/npsb-kb/databases/(default)/documents";
const FIRESTORE_KEY = "AIzaSyDsZm_O1FiyveMVnE4ooC35hVx7YasOJnc"; // public web API key (rules gate access)

// JS value → Firestore REST typed value (subset: what a snapshot contains).
function toFsValue(v) {
  if (v === null || v === undefined) return { nullValue: null };
  if (typeof v === "boolean") return { booleanValue: v };
  if (typeof v === "number") return Number.isInteger(v) ? { integerValue: String(v) } : { doubleValue: v };
  if (typeof v === "string") return { stringValue: v };
  if (Array.isArray(v)) return { arrayValue: { values: v.map(toFsValue) } };
  const fields = {};
  for (const k of Object.keys(v)) { if (v[k] !== undefined) fields[k] = toFsValue(v[k]); }
  return { mapValue: { fields } };
}
function fromFsValue(v) {
  if (!v || typeof v !== "object") return null;
  if ("nullValue" in v) return null;
  if ("booleanValue" in v) return v.booleanValue;
  if ("integerValue" in v) return Number(v.integerValue);
  if ("doubleValue" in v) return v.doubleValue;
  if ("stringValue" in v) return v.stringValue;
  if ("timestampValue" in v) return v.timestampValue;
  if ("arrayValue" in v) return (v.arrayValue.values || []).map(fromFsValue);
  if ("mapValue" in v) { const o = {}; for (const [k, x] of Object.entries(v.mapValue.fields || {})) o[k] = fromFsValue(x); return o; }
  return null;
}

// OAuth 1.0a header (HMAC-SHA256) for NetSuite TBA.
async function nsOauthHeader(env, method, url) {
  const enc = (s) => encodeURIComponent(s).replace(/[!*'()]/g, c => "%" + c.charCodeAt(0).toString(16).toUpperCase());
  const nonce = crypto.randomUUID().replace(/-/g, "");
  const ts = String(Math.floor(Date.now() / 1000));
  const p = {
    oauth_consumer_key: env.NS_CONSUMER_KEY, oauth_token: env.NS_TOKEN_ID,
    oauth_signature_method: "HMAC-SHA256", oauth_timestamp: ts, oauth_nonce: nonce, oauth_version: "1.0",
  };
  const u = new URL(url);
  const qp = [...u.searchParams.entries()];
  const all = [...Object.entries(p), ...qp].map(([k, v]) => [enc(k), enc(v)]).sort((a, b) => a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : (a[1] < b[1] ? -1 : 1));
  const baseUrl = u.origin + u.pathname;
  const base = [method.toUpperCase(), enc(baseUrl), enc(all.map(([k, v]) => `${k}=${v}`).join("&"))].join("&");
  const keyBytes = new TextEncoder().encode(`${enc(env.NS_CONSUMER_SECRET)}&${enc(env.NS_TOKEN_SECRET)}`);
  const cryptoKey = await crypto.subtle.importKey("raw", keyBytes, { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", cryptoKey, new TextEncoder().encode(base));
  const b64 = btoa(String.fromCharCode(...new Uint8Array(sig)));
  const realm = String(env.NS_ACCOUNT).toUpperCase().replace("-", "_");
  return `OAuth realm="${realm}", oauth_consumer_key="${enc(p.oauth_consumer_key)}", oauth_token="${enc(p.oauth_token)}", oauth_signature_method="HMAC-SHA256", oauth_timestamp="${ts}", oauth_nonce="${nonce}", oauth_version="1.0", oauth_signature="${enc(b64)}"`;
}

async function nsSuiteQL(env, sql) {
  const acct = String(env.NS_ACCOUNT).toLowerCase().replace("_", "-");
  const url = `https://${acct}.suitetalk.api.netsuite.com/services/rest/query/v1/suiteql?limit=1000`;
  const auth = await nsOauthHeader(env, "POST", url);
  const r = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json", Prefer: "transient", Authorization: auth },
    body: JSON.stringify({ q: sql }),
  });
  const j = await r.json();
  if (!r.ok) throw new Error(`SuiteQL ${r.status}: ${JSON.stringify(j).slice(0, 300)}`);
  return j.items || [];
}

// Deterministic memo cleaning (no LLM): drop internal prefixes/framing, commit
// hashes, boilerplate; collapse whitespace. Mirrors the report kit's rules.
function cleanMemo(memo) {
  let s = String(memo || "");
  s = s.replace(/^\s*(Offline|Internal)\s*[|:]\s*/i, "");
  s = s.replace(/^\s*[A-Za-z ]+\|\s*[A-Za-z0-9 .]*\|\s*/, "");          // "Client | SOW | " prefixes
  s = s.replace(/\b[0-9a-f]{7,40}\b/g, "").replace(/\(covering [^)]*\)/gi, "");
  s = s.replace(/\s*\r?\n\s*[-•]?\s*/g, "; ").replace(/\s+/g, " ").trim();
  if (/^Weekly PM Update/i.test(s)) return "Weekly PM update — resource allocations, RAIDD log, dashboards and action items";
  if (/invoice.*(ensuring|accurate|aligned)/i.test(s)) return "Invoice review and approval";
  return s.length > 320 ? s.slice(0, 317) + "…" : s;
}

const NS_MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

async function runMsHoursRefresh(request, env) {
  if (!env.NS_ACCOUNT || !env.NS_CONSUMER_KEY || !env.NS_CONSUMER_SECRET || !env.NS_TOKEN_ID || !env.NS_TOKEN_SECRET) {
    return json({ error: "netsuite-not-provisioned", message: "NetSuite TBA secrets are not configured on the worker yet (one-time admin setup)." }, 503);
  }
  try {
    const { envKey } = await request.json();
    if (!envKey || !/^env_[a-f0-9]{16,64}$/.test(envKey)) return json({ error: "bad envKey" }, 400);

    // 1 · Current snapshot from Firestore (carries ns.jobId + static config).
    const docUrl = `${FIRESTORE_BASE}/client_engagement/${envKey}?key=${FIRESTORE_KEY}`;
    const cur = await fetch(docUrl).then(r => r.json());
    if (!cur.fields) return json({ error: "no snapshot for that envKey" }, 404);
    const snapshot = fromFsValue({ mapValue: { fields: cur.fields } }).snapshot;
    if (!snapshot || !snapshot.ns || !snapshot.ns.jobId) return json({ error: "snapshot has no ns.jobId mapping" }, 400);
    const jobId = Number(snapshot.ns.jobId);
    const project = snapshot.kind === "project";

    // 2 · Re-query NetSuite. Hours ALWAYS from projecttask.actualwork (live).
    let months;
    if (project) {
      const ids = (snapshot.months || []).map(m => Number((snapshot.ns.taskIds || {})[m.label])).filter(Boolean);
      const rows = ids.length ? await nsSuiteQL(env, `SELECT pt.id, pt.actualwork, pt.estimatedwork FROM projecttask pt WHERE pt.id IN (${ids.join(",")})`) : [];
      months = (snapshot.months || []).map(m => {
        const row = rows.find(r => Number(r.id) === Number((snapshot.ns.taskIds || {})[m.label]));
        return row ? { label: m.label, contracted: Number(row.estimatedwork) || m.contracted, used: Number(row.actualwork) || 0 } : m;
      });
    } else {
      const rows = await nsSuiteQL(env, `SELECT pt.id, pt.title, pt.custevent_bpc_prepaid_hours AS prepaid, pt.actualwork FROM projecttask pt WHERE pt.project = ${jobId} AND pt.custevent_bpc_prepaid_hours IS NOT NULL AND pt.custevent_bpc_prepaid_hours > 0 ORDER BY pt.title`);
      const FULL = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
      months = rows.map(r => {
        const m = String(r.title || "").match(/^(\d{4})-(\d{2})/); // task title "2026-04 - April"
        const label = m ? `${FULL[Number(m[2]) - 1]} ${m[1]}` : String(r.title);
        return { label, contracted: Number(r.prepaid) || 0, used: Number(r.actualwork) || 0 };
      });
    }

    // 3 · Time log. Retainer: billable memo rows for the whole engagement.
    //     Project: recent activity (last 45 days), any memo row.
    const days = project ? 45 : 130;
    const billableFilter = project ? "" : " AND t.isbillable = 'T'";
    const tb = await nsSuiteQL(env, `SELECT t.trandate, e.entityid AS who, t.hours, t.memo FROM timebill t LEFT JOIN employee e ON e.id = t.employee WHERE t.customer = ${jobId} AND t.memo IS NOT NULL${billableFilter} AND t.trandate >= (SYSDATE - ${days}) ORDER BY t.trandate`);
    const timebill = tb.map(r => {
      const dm = String(r.trandate || "").match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/); // MM/DD/YYYY
      const d = dm ? `${NS_MONTHS[Number(dm[1]) - 1]} ${Number(dm[2])}` : String(r.trandate);
      return { d, who: String(r.who || ""), h: Number(r.hours) || 0, note: cleanMemo(r.memo) };
    }).filter(t => t.h > 0 && t.note);

    // 4 · Recompute the billable overage for monthly retainers (never copy).
    const next = { ...snapshot, months, timebill };
    if (!project && (snapshot.billingMode || "monthly") === "monthly") {
      next.billableOverage = +months.reduce((s, m) => s + Math.max(0, m.used - m.contracted), 0).toFixed(2);
    }
    if (project) next.timelogNote = `recent activity, last ${days} days`;

    // 5 · Persist (updateMask keeps `published` and anything else untouched).
    const patchUrl = `${FIRESTORE_BASE}/client_engagement/${envKey}?key=${FIRESTORE_KEY}&updateMask.fieldPaths=snapshot&updateMask.fieldPaths=updatedAt&updateMask.fieldPaths=updatedBy`;
    const body = { fields: { snapshot: toFsValue(next), updatedAt: { timestampValue: new Date().toISOString() }, updatedBy: { stringValue: "NetSuite refresh" } } };
    const pr = await fetch(patchUrl, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
    if (!pr.ok) throw new Error(`Firestore write ${pr.status}: ${(await pr.text()).slice(0, 200)}`);

    const c = months.reduce((s, m) => s + m.contracted, 0), u = +months.reduce((s, m) => s + m.used, 0).toFixed(2);
    return json({ ok: true, contracted: c, used: u, entries: timebill.length });
  } catch (e) {
    return json({ error: String((e && e.message) || e) }, 500);
  }
}

// ── Router ───────────────────────────────────────────────────────────────────
const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization"
};

function json(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { "Content-Type": "application/json", ...CORS_HEADERS }
  });
}

// Screenshots attached to a hub chat question ([{mime,data(base64)}]) →
// Gemini inlineData parts. Hard caps: 3 images, ~4MB base64 each, image/* only.
function chatImageParts(body) {
  const imgs = Array.isArray(body && body.images) ? body.images : [];
  const parts = [];
  for (const im of imgs.slice(0, 3)) {
    const mime = String((im && im.mime) || "");
    const data = String((im && im.data) || "");
    if (!/^image\/(png|jpe?g|webp|gif)$/i.test(mime)) continue;
    if (!data || data.length > 4_200_000) continue;
    parts.push({ inline_data: { mime_type: mime, data } });
  }
  return parts;
}

// ── Hub platform settings (Firestore portal/settings, project npsb-kb) ──────
// The hub's super-admin Settings page stores BPC's Gemini key there; the hub AI
// endpoints (askKB / hubChat / envChat) PREFER it over the worker's baked-in
// GEMINI_API_KEY secret, so switching whose credits burn needs no redeploy.
// Best-effort in-memory cache (~5 min), same spirit as svSessionCache — the
// worker stays stateless; a cold isolate just refetches. Beta caveat: the doc
// is world-readable under the hub's open Firestore rules; move the key to a
// worker secret at GA.
let __hubSettingsCache = { at: 0, data: null };
async function getHubPortalSettings() {
  const now = Date.now();
  if (__hubSettingsCache.data && now - __hubSettingsCache.at < 5 * 60 * 1000) return __hubSettingsCache.data;
  try {
    const r = await fetch("https://firestore.googleapis.com/v1/projects/npsb-kb/databases/(default)/documents/portal/settings");
    if (!r.ok) throw new Error(String(r.status));
    const d = await r.json();
    const f = (d && d.fields) || {};
    const keys = (((f.keys || {}).mapValue || {}).fields) || {};
    const geminiKey = String(((keys.geminiKey || {}).stringValue) || "").trim();
    __hubSettingsCache = { at: now, data: { geminiKey } };
  } catch (_) {
    // Keep whatever we had; empty settings on a cold failure (falls back to the secret).
    __hubSettingsCache = { at: now, data: __hubSettingsCache.data || { geminiKey: "" } };
  }
  return __hubSettingsCache.data;
}
async function hubGeminiKey(env) {
  const s = await getHubPortalSettings();
  return (s && s.geminiKey) || (env && env.GEMINI_API_KEY) || null;
}

// NSPB Hub KB chat — server-side Gemini, two-step (pick articles → read → answer).
async function runAskKB(request, env) {
  // Where the Customer Hub's /kb markdown actually lives. nspbhub.web.app is a
  // different hosting site that rewrites everything to the SPA index.html — a
  // fetch there returns HTTP 200 with HTML, silently un-grounding the chat.
  const HUB_BASE = "https://bpccustomerhub.web.app";
  try {
    const body = await request.json();
    const question = String((body && body.question) || "").trim();
    const currentArticle = (body && body.currentArticle) || "";
    const articles = Array.isArray(body && body.articles) ? body.articles : []; // [{title, path}]
    const imageParts = chatImageParts(body); // attached NSPB screenshots (optional)
    const key = await hubGeminiKey(env); // Settings-page key first, worker secret as fallback
    if (!question) return json({ error: "question required" }, 400);
    if (!key) return json({ answer: "The knowledge-base assistant isn't configured yet (no server AI key)." });

    // extraParts: Gemini inlineData images appended AFTER the text (multimodal).
    const gem = async (prompt, extraParts) => {
      const u = GEMINI_API_BASE + GEMINI_MODEL_FAST + ":generateContent?key=" + encodeURIComponent(key);
      const parts = [{ text: prompt }, ...(extraParts || [])];
      const r = await fetch(u, { method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ contents: [{ role: "user", parts }] }) });
      const j = await r.json();
      try { return (j.candidates[0].content.parts[0].text || "").trim(); } catch (_) { return ""; }
    };

    let used = [], block = "";
    if (articles.length) {
      const titles = articles.map(a => a.title).join("\n");
      // Article picking sees the screenshot too — what's ON the screen often
      // routes better than the words ("what is this?" + a Smart View dialog).
      const selRaw = await gem(`You route support questions to knowledge base articles. From the list below, pick up to 4 article titles most likely to answer the question${imageParts.length ? " (the user also attached screenshot(s) of their screen — use what they show)" : ""}. Reply with ONLY a JSON array of exact titles; [] if none.\n\nTITLES:\n${titles}\n\nQUESTION: ${question}`, imageParts);
      let picks = [];
      try { picks = JSON.parse(selRaw.replace(/^```json?|```$/g, "").trim()); } catch (_) {}
      if (Array.isArray(picks)) {
        const chosen = picks.map(t => articles.find(a => String(a.title).toLowerCase() === String(t).toLowerCase())).filter(Boolean).slice(0, 4);
        const parts = [];
        for (const art of chosen) {
          try {
            const res = await fetch(HUB_BASE + encodeURI(art.path));
            if (!res.ok) continue;
            parts.push(`=== ARTICLE: ${art.title} ===\n${(await res.text()).slice(0, 9000)}`);
            used.push(art.title);
          } catch (_) {}
        }
        block = parts.join("\n\n");
      }
    }

    const prompt = `You are an action-oriented support assistant for an internal Oracle NSPB / NetSuite knowledge base. The user wants to get tasks done quickly.\nRULES:\n1. Always respond in English.\n2. For "how to" questions give concise, step-by-step instructions saying exactly where to click. For "explain/what is" questions give a clear conceptual explanation.\n3. When your answer draws on an article, cite it exactly as [ARTICLE|Exact Article Title].\n4. End with up to 3 related follow-up questions, each on its own line formatted exactly as: #question: <the question>${imageParts.length ? `\n5. The user ATTACHED ${imageParts.length} SCREENSHOT(S) of their NSPB/Excel screen. Read them carefully: identify the screen/dialog shown, any error text, and the exact field or menu involved, and ground your answer in what is visible. If the screenshot shows an error message, quote it.` : ""}${currentArticle ? `\nThe user is currently reading the article "${currentArticle}".` : ""}${block ? `\nKNOWLEDGE BASE ARTICLES:\n${block}` : "\n(No directly relevant articles were found — answer from standard NSPB/NetSuite knowledge and say which official topic to look under.)"}\n\nUSER QUESTION: ${question}`;
    const answer = await gem(prompt, imageParts);
    return json({ answer: answer || "I couldn't generate an answer.", articles: used });
  } catch (e) {
    return json({ answer: "Sorry, I couldn't reach the AI service. (" + ((e && e.message) || e) + ")" });
  }
}

// Everything the "Ask the Hub" site assistant is allowed to talk about — the
// BPC offerings exactly as presented on the Customer Hub. The model answers
// ONLY from this; anything NSPB how-to is bounced to the Knowledge Hub.
// KEEP IN SYNC with the hub's section registry (nspbhub/src/sections.ts): the
